// v2.0.6 — Race-Guard für Detail-Page-Sub-Loader. Wenn der User schnell von
// Firma A zu Firma B navigiert, läuft A's Promise-Kette weiter und kommt
// nach B's zurück. Ohne Guard würde A's Daten in B's UI landen. Jeder
// Sub-Loader ruft direkt vor dem DOM-Update isStillOnDetail(...) und
// returnt früh, wenn die User-Page sich geändert hat.
function isStillOnDetail(entityType, id) {
  if (entityType === 'company') return currentCompanyDetailId === id;
  if (entityType === 'project') return currentProjectDetailId === id;
  if (entityType === 'contact') return currentContactDetailId === id;
  return true;
}

// v2.1.0 — Helper: schon getippten Notiztext beim Sidepanel-Klick als
// Modal-Titel übernehmen. Reduziert Reibung: User schreibt erst im Stream
// drauf los, entscheidet dann per Klick "ist eigentlich ein Termin/Aufgabe/
// Einsatz/Projekt". Wenn das Notiz-Input leer ist, normales Verhalten.
async function openModalWithNoteAsTitle(noteInputId, openerFn, titleFieldId) {
  const input = document.getElementById(noteInputId);
  const text = input?.value.trim() || '';
  await openerFn();
  if (text && input) input.value = '';
  if (text && titleFieldId) {
    const titel = document.getElementById(titleFieldId);
    if (titel) titel.value = text;
  }
}

// v2.1.1 — Hilfsformatierer für Firmenadresse als Vor-Ort-Text.
function formatCompanyAddress(c) {
  if (!c) return '';
  const parts = [c.strasse, [c.plz, c.stadt].filter(Boolean).join(' '), c.land && c.land !== 'Deutschland' ? c.land : null]
    .filter(Boolean);
  return parts.join(', ');
}

// v2.1.2 — Kontext-Icons im Activity-Stream-Eingabefeld:
// Klick auf 📞/✉️/🤝/💬 schreibt "Call: " / "Mail: " / "Meeting: " / "Chat: "
// als Prefix in den Input. Schon vorhandene bekannte Prefixe werden ersetzt
// (nicht doppelt). Cursor landet ans Ende, Input bekommt Fokus.
const _NOTE_CONTEXT_PREFIXES = ['Call: ', 'Mail: ', 'Meeting: ', 'Chat: '];
function setNoteContext(inputId, prefix) {
  const input = document.getElementById(inputId);
  if (!input) return;
  let text = input.value || '';
  for (const p of _NOTE_CONTEXT_PREFIXES) {
    if (text.startsWith(p)) { text = text.slice(p.length); break; }
  }
  input.value = prefix + text;
  input.focus();
  const len = input.value.length;
  if (typeof input.setSelectionRange === 'function') input.setSelectionRange(len, len);
}

// v2.13.4: Note-Icons doppelte Funktion — Prefix setzen UND Activity-Stream
// auf Notizen mit diesem Prefix filtern. Zweiter Klick auf dasselbe Icon
// hebt den Filter wieder auf.
let _currentCompanyNoteContextFilter = null;
let _currentContactNoteContextFilter = null;
let _currentProjectNoteContextFilter = null;

// v2.13.5: Zeit-Filter pro Detail-Page (null | 'heute' | 'bevorstehend' | 'geschehen').
// Zweiter Klick auf dieselbe Pille schaltet ihn wieder aus.
let _currentCompanyTimeFilter = null;
let _currentContactTimeFilter = null;
let _currentProjectTimeFilter = null;

function toggleNoteContextFilter(entityType, contextKey, inputId, prefix) {
  const stateKey = `_current${entityType[0].toUpperCase()}${entityType.slice(1)}NoteContextFilter`;
  // entityType: 'company' | 'contact' | 'project'
  const currentValue = (entityType === 'company') ? _currentCompanyNoteContextFilter
                     : (entityType === 'contact') ? _currentContactNoteContextFilter
                     : _currentProjectNoteContextFilter;
  const newValue = (currentValue === contextKey) ? null : contextKey;

  if (entityType === 'company') _currentCompanyNoteContextFilter = newValue;
  else if (entityType === 'contact') _currentContactNoteContextFilter = newValue;
  else _currentProjectNoteContextFilter = newValue;

  // Visual mark: aktiver Icon-Button bekommt .is-active
  const iconRow = document.getElementById(inputId)?.closest('.proj-activity-pane')?.querySelector('.proj-note-icons')
              || document.querySelector(`#${entityType}-panel-aktivitaeten .proj-note-icons`);
  if (iconRow) {
    iconRow.querySelectorAll('.proj-note-icon').forEach(b => {
      b.classList.toggle('is-active', b.dataset.contextKey === newValue);
    });
  }

  // Prefix nur setzen, wenn Filter aktiviert wird (nicht beim Deaktivieren)
  if (newValue) setNoteContext(inputId, prefix);

  // Wenn Filter aktiv: Top-Filter auch auf „Notizen" setzen, sonst zurück auf „Alle".
  const targetTopFilter = newValue ? 'notizen' : 'alle';
  if (entityType === 'company')      filterCompanyActivity(targetTopFilter);
  else if (entityType === 'contact') filterContactActivity(targetTopFilter);
  else                                filterProjectActivity(targetTopFilter);
}

// v2.1.0 — Activity-Stream in "Bevorstehend" + "Geschehen" splitten.
// Bevorstehend: alle items mit ts >= heute, aufsteigend (nächstes oben).
// Geschehen: alle items mit ts < heute (oder ohne ts), absteigend (neuestes oben).
function _splitActivities(items) {
  const today = toISODate(new Date());
  const heute = [], future = [], past = [];
  items.forEach(it => {
    const itDate = (it.ts || '').substring(0, 10);
    if (!itDate) { past.push(it); return; }
    if (itDate === today)      heute.push(it);
    else if (itDate > today)   future.push(it);
    else                       past.push(it);
  });
  heute.sort((a, b) => (a.ts || '').localeCompare(b.ts || ''));
  future.sort((a, b) => (a.ts || '').localeCompare(b.ts || ''));
  past.sort((a, b) => (b.ts || '').localeCompare(a.ts || ''));
  return { heute, future, past };
}

/** v2.25.9: Mappt Einsatz-/Aufgaben-Status auf eine semantische Farbklasse
 *  für den Status-Pill und den Row-Akzent in der Aktivitäten-Timeline. */
function _activityStatusStyle(status) {
  // Funktion ist shared für Einsatz (einsatz_status), Termin (termin_status)
  // und Aufgabe (aufgabe_status); 'geplant'/'durchgefuehrt' decken alle drei ab.
  switch (status) {
    case 'geplant':            return { cls: 'is-blue',   label: dispStatus(status) };
    case 'durchgefuehrt':      return { cls: 'is-lgreen', label: dispStatus(status) };
    case 'abgerechnet':        return { cls: 'is-dgreen', label: dispStatus(status) };
    case 'storniert':          return { cls: 'is-red',    label: dispStatus(status) };
    case 'erledigt':           return { cls: 'is-lgreen', label: dispStatus(status) };
    case 'offen':              return { cls: 'is-grey',   label: dispStatus(status) };
    default:                   return status ? { cls: 'is-grey', label: dispStatus(status) } : null;
  }
}

function _activityItemHTML(it) {
  const cls = it.type.toLowerCase();
  // v2.1.0: nur der Titel ist klickbar (nicht das ganze Item — sonst
  // greift der Klick auch auf Datum/Type-Pille). Click-Quelle: it.click.
  // v2.25.9: Bei Einsatz/Aufgabe-Items zusätzlich einen farbigen Status-Pill
  // und einen Row-Akzent (linke Kante) anzeigen — Storniert + Erledigt werden
  // durchgestrichen, damit sie auf einen Blick als „abgehakt"/„entfallen"
  // erkennbar sind, ohne die ganze Zeile lesen zu müssen.
  const statusStyle = _activityStatusStyle(it.status);
  const statusPill = statusStyle ? `<span class="proj-activity-status-pill ${statusStyle.cls}">${esc(statusStyle.label)}</span>` : '';
  const isStruck = it.status === TASK_STATUS.STORNIERT || it.status === 'erledigt';
  const rowAccentCls = statusStyle ? ` proj-activity-item-accent-${statusStyle.cls}` : '';
  const titleCls = `proj-activity-title${isStruck ? ' proj-activity-title-struck' : ''}`;
  const titleHtml = it.click
    ? `<a class="${titleCls} proj-link" onclick="${it.click}">${esc(it.title)}</a>`
    : `<span class="${titleCls}">${esc(it.title)}</span>`;
  return `
    <div class="proj-activity-item${rowAccentCls}">
      <div class="proj-activity-date">${esc(formatDateCompact((it.ts || '').substring(0, 10)))}</div>
      <div class="proj-activity-body">
        <div class="proj-activity-head">
          <span class="type-pill type-pill-${cls}">${esc(it.type)}</span>
          ${statusPill}
          ${titleHtml}
        </div>
        <div class="proj-activity-meta">${esc(it.meta || '')}</div>
      </div>
    </div>`;
}

// v2.1.0 — NOTIZ-EDIT-MODAL: Klick auf Notiz im Activity-Stream öffnet
// dieses Modal mit dem Inhalt vorbelegt; speichern aktualisiert die Notiz,
// löschen entfernt sie (notes hat kein deleted_at, also echter DELETE).
let _editingNotizId = null;
let _editingNotizContext = null; // 'company' | 'project' | 'contact'

async function openNotizModal(notizId, context) {
  _editingNotizId = notizId;
  _editingNotizContext = context;
  const { data, error } = await db.from('notes')
    .select('inhalt, created_at, user:user_profiles!notes_erstellt_von_fkey(name)')
    .eq('id', notizId).single();
  if (error || !data) {
    showToast('Notiz nicht gefunden: ' + (error?.message || ''), true);
    return;
  }
  document.getElementById('n-inhalt').value = data.inhalt || '';
  const meta = document.getElementById('n-meta');
  if (meta) {
    const who = data.user?.name || '—';
    const when = data.created_at ? formatDateDE(data.created_at.substring(0, 10)) : '—';
    meta.textContent = `Erstellt von ${who} · ${when}`;
  }
  document.getElementById('modal-notiz').classList.add('open');
  setTimeout(() => document.getElementById('n-inhalt')?.focus(), 50);
}

function closeNotizModal() {
  document.getElementById('modal-notiz').classList.remove('open');
  _editingNotizId = null;
  _editingNotizContext = null;
}

async function saveNotizFromModal() {
  if (!_editingNotizId) return;
  const text = document.getElementById('n-inhalt').value.trim();
  if (!text) { showToast('Notiz darf nicht leer sein.', true); return; }
  const { error } = await db.from('notes').update({ inhalt: text }).eq('id', _editingNotizId);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  const ctx = _editingNotizContext;
  closeNotizModal();
  showToast('Notiz aktualisiert.');
  // Stream der jeweiligen Detail-Page neu laden
  if (ctx === 'company' && currentCompanyDetailId) loadCompanyActivityStream(currentCompanyDetailId);
  else if (ctx === 'project' && currentProjectDetailId) loadProjectActivityStream(currentProjectDetailId);
  else if (ctx === 'contact' && currentContactDetailId) loadContactActivityStream(currentContactDetailId);
  // v2.9.5: Notizen-Liste aktualisieren, wenn sie offen ist
  if (document.getElementById('page-notes')?.classList.contains('active')) loadNotesList();
}

async function deleteNotizFromModal() {
  if (!_editingNotizId) return;
  const ok = await confirmDialog({ title: 'Notiz löschen?', message: 'Diese Aktion kann nicht rückgängig gemacht werden.', okLabel: 'Löschen', isDanger: true });
  if (!ok) return;
  const { error } = await db.from('notes').delete().eq('id', _editingNotizId);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  const ctx = _editingNotizContext;
  closeNotizModal();
  showToast('Notiz gelöscht.');
  if (ctx === 'company' && currentCompanyDetailId) loadCompanyActivityStream(currentCompanyDetailId);
  else if (ctx === 'project' && currentProjectDetailId) loadProjectActivityStream(currentProjectDetailId);
  else if (ctx === 'contact' && currentContactDetailId) loadContactActivityStream(currentContactDetailId);
  // v2.9.5: Notizen-Liste aktualisieren, wenn sie offen ist
  if (document.getElementById('page-notes')?.classList.contains('active')) loadNotesList();
}

function renderActivityStreamSections(filtered, timeFilter) {
  if (filtered.length === 0) {
    return '<div class="info-card-empty">Keine Aktivitäten in dieser Kategorie.</div>';
  }
  const { heute, future, past } = _splitActivities(filtered);
  const parts = [];
  const show = (sec) => !timeFilter || timeFilter === sec;
  if (show('heute') && heute.length > 0) {
    parts.push('<div class="activity-section-header activity-section-header-today">Heute</div>');
    parts.push(heute.map(_activityItemHTML).join(''));
  }
  if (show('bevorstehend') && future.length > 0) {
    parts.push('<div class="activity-section-header">Bevorstehend</div>');
    parts.push(future.map(_activityItemHTML).join(''));
  }
  if (show('geschehen') && past.length > 0) {
    parts.push('<div class="activity-section-header">Geschehen</div>');
    parts.push(past.map(_activityItemHTML).join(''));
  }
  if (parts.length === 0) {
    const label = timeFilter === 'heute' ? 'heute' : timeFilter === 'bevorstehend' ? 'in der Zukunft' : 'in der Vergangenheit';
    return `<div class="info-card-empty">Keine Aktivitäten ${label}.</div>`;
  }
  return parts.join('');
}
