/** v2.0.0 Phase 9e — Listen-Tab-Counts mit Filter-Reaktivität. Loader rufen
 *  setListenTabCount('companies', anzahlGefiltert) auf, sobald sie ihre
 *  Liste gerendert haben — der Wert reflektiert dann die aktuell sichtbaren
 *  Zeilen, nicht die Total-Anzahl. */
function setListenTabCount(page, count) {
  const el = document.getElementById('listen-tab-count-' + page);
  if (!el) return;
  if (count == null || count === '') { el.textContent = ''; return; }
  el.textContent = `· ${count}`;
}

/** v2.0.0 — Sub-Nav für Listen ein-/ausblenden + aktiven Tab markieren.
 *  v2.3.2: Counts für ALLE Listen-Tabs vorladen (nicht nur den aktiven),
 *  damit der User auf einen Blick sieht wieviel pro Tab steckt. */
const LISTEN_PAGES = ['companies','contacts','projects','appointments','deployments','tasks','notes'];
const EINSTELLUNGEN_PAGES = ['lookups','services','programs','templates','users','tags','products','themes','dubletten','shortcuts','import'];
function updateListenTabBar(pageName) {
  const listenBar = document.getElementById('listen-tab-bar');
  const settingsBar = document.getElementById('einstellungen-tab-bar');
  if (listenBar) {
    const inListen = LISTEN_PAGES.includes(pageName);
    listenBar.style.display = inListen ? 'flex' : 'none';
    if (inListen) {
      listenBar.querySelectorAll('.listen-tab').forEach(t => {
        t.classList.toggle('active', t.dataset.page === pageName);
      });
      // v2.3.2: alle Counts proaktiv laden, damit auch inaktive Tabs Zahlen zeigen
      loadAllListenTabCounts();
    }
  }
  if (settingsBar) {
    const inSettings = EINSTELLUNGEN_PAGES.includes(pageName);
    settingsBar.style.display = inSettings ? 'flex' : 'none';
    if (inSettings) {
      settingsBar.querySelectorAll('.listen-tab').forEach(t => {
        t.classList.toggle('active', t.dataset.page === pageName);
      });
    }
  }
}

// v2.3.2 — Counts für alle 6 Listen-Tabs parallel zählen.
// Greift jedes Mal beim Wechsel in den Listen-Bereich, sodass die Zahlen
// nach jeder CRUD-Aktion ungefähr aktuell bleiben (der aktive Tab
// überschreibt seinen Count exakt nach dem Render).
async function loadAllListenTabCounts() {
  const tableMap = {
    companies: 'companies', contacts: 'contacts', projects: 'projects',
    appointments: 'appointments', deployments: 'deployments', tasks: 'tasks'
  };
  await Promise.all(Object.entries(tableMap).map(async ([page, table]) => {
    const { count } = await db.from(table).select('id', { count: 'exact', head: true })
      .is('deleted_at', null);
    setListenTabCount(page, count == null ? '' : count);
  }));
  // v2.9.5: Notizen haben kein deleted_at — separater Count.
  const { count: notesCount } = await db.from('notes').select('id', { count: 'exact', head: true });
  setListenTabCount('notes', notesCount == null ? '' : notesCount);
}

