async function loadEinsatzStatus() {
  if (einsatzStatusCache.length > 0) return einsatzStatusCache;
  const { data, error } = await db.from('lookup_values')
    .select('id, wert, farbe, reihenfolge, system_key').eq('kategorie', 'einsatz_status').eq('ist_aktiv', true).order('reihenfolge');
  if (error) { return []; }
  einsatzStatusCache = data || [];
  return einsatzStatusCache;
}

function einsatzStatusFarbe(systemKey) {
  const s = einsatzStatusCache.find(x => x.system_key === systemKey);
  return s?.farbe || '#6b7280';
}

async function loadServicesCache() {
  if (servicesCache.length > 0) return servicesCache;
  const { data, error } = await db.from('services')
    .select('id, name, einheit, standardpreis, ist_aktiv, standard_uhrzeit_von, standard_uhrzeit_bis')
    .eq('ist_aktiv', true).order('name');
  if (error) { return []; }
  servicesCache = data || [];
  return servicesCache;
}

// Kompaktes Datum-Range-Format: "21.04.2026" oder "21.04.–23.04.2026" oder "Ungeplant"
function formatDeploymentDateRange(von, bis) {
  if (!von && !bis) return 'Ungeplant';
  if (!von) return '—';
  if (!bis || von === bis) return formatDateDE(von);
  // Beide Daten im selben Jahr?
  const vonD = parseLocalDate(von);
  const bisD = parseLocalDate(bis);
  if (vonD.getFullYear() === bisD.getFullYear()) {
    const vonStr = `${String(vonD.getDate()).padStart(2,'0')}.${String(vonD.getMonth()+1).padStart(2,'0')}.`;
    return `${vonStr}–${formatDateDE(bis).replace(/^[A-Za-z]{2}, /, '')}`;
  }
  return `${formatDateDE(von)} – ${formatDateDE(bis)}`;
}

/**
 * Rendert das Datum einer Deployment-Zeile, inkl. "Ungeplant"-Badge bei NULL.
 */
function renderDeploymentDateCell(von, bis) {
  if (!von && !bis) {
    return '<span class="badge" style="background:#f3f4f6;color:#6b7280">Ungeplant</span>';
  }
  return `<div class="date-cell">${esc(formatDeploymentDateRange(von, bis))}</div>`;
}

function calcDeploymentGesamt(menge, einzelpreis) {
  const m = Number(menge) || 0;
  const e = Number(einzelpreis) || 0;
  return m * e;
}

/** v2.28.2 — Rabatt-Helper.
 *  Errechnet aus Brutto + Rabatt-Typ/-Wert den Rabatt-Betrag und das Netto.
 *  Brutto bleibt unverändert die Basis (Menge × Einzelpreis bzw. VK).
 *  rabattTyp NULL/undefined/'' = kein Rabatt → rabatt = 0, netto = brutto. */
function applyRabatt(brutto, rabattTyp, rabattWert) {
  const b = Number(brutto) || 0;
  if (!rabattTyp || rabattWert == null) return { brutto: b, rabatt: 0, netto: b };
  const w = Number(rabattWert) || 0;
  let rabatt = 0;
  if (rabattTyp === 'prozent')      rabatt = Math.min(b, b * (w / 100));
  else if (rabattTyp === 'betrag')  rabatt = Math.min(b, w);
  const netto = b - rabatt;
  return { brutto: b, rabatt, netto };
}

/** Netto eines Einsatzes (Menge × Einzelpreis abzüglich Rabatt). */
function calcDeploymentNetto(d) {
  const brutto = calcDeploymentGesamt(d?.menge, d?.einzelpreis);
  return applyRabatt(brutto, d?.rabatt_typ, d?.rabatt_wert).netto;
}

/** Netto einer Produktposition (Menge × VK abzüglich Rabatt). */
function calcProductPositionNetto(p) {
  const brutto = (Number(p?.menge) || 0) * (Number(p?.einzelpreis_vk) || 0);
  return applyRabatt(brutto, p?.rabatt_typ, p?.rabatt_wert).netto;
}

// v2.28.2 — Toggle-Handler für die Rabatt-Felder in den Modals: Wert ist
// disabled, solange kein Typ gewählt ist (verhindert versehentliche Werte).
function onDeploymentRabattTypChange() {
  const typ = document.getElementById('d-rabatt-typ')?.value || '';
  const wert = document.getElementById('d-rabatt-wert');
  if (!wert) return;
  if (!typ) { wert.value = ''; wert.disabled = true; }
  else      { wert.disabled = false; if (!wert.value) wert.focus(); }
}
function onProductRabattTypChange() {
  const typ = document.getElementById('pp-rabatt-typ')?.value || '';
  const wert = document.getElementById('pp-rabatt-wert');
  if (!wert) return;
  if (!typ) { wert.value = ''; wert.disabled = true; }
  else      { wert.disabled = false; if (!wert.value) wert.focus(); }
}

async function loadDeployments() {
  const tbody = document.getElementById('deployments-table-body');
  tbody.innerHTML = '<tr><td colspan="8"><div class="empty">Lade Einsätze ...</div></td></tr>';

  await loadEinsatzStatus();
  await loadServicesCache();

  // Firmen und Projekte für Filter
  if (companiesCache.length === 0) {
    // v2.33.13 (Phase A.4 #20): kanonisches companiesCache-Schema id, name,
    // strasse, plz, stadt. Vorher waren manche Lazy-Loader auf `id, name`
    // beschränkt — wenn so ein Loader vor dem Einsatz-Modal lief, fand
    // dessen Auto-Ort-Auto-Fill keine Adress-Spalten im Cache.
    const { data: cs } = await db.from('companies').select('id, name, strasse, plz, stadt').is('deleted_at', null).order('name');
    companiesCache = cs || [];
  }
  if (projectsCache.length === 0) {
    const { data: ps } = await db.from('projects').select('id, name, company_id').is('deleted_at', null).order('name');
    projectsCache = ps || [];
  }

  const companyFilter = document.getElementById('deployments-company-filter');
  const existingCompany = companyFilter.value;
  companyFilter.innerHTML = '<option value="">Alle Firmen</option>'
    + companiesCache.map(c => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
  if (existingCompany) companyFilter.value = existingCompany;

  const projectFilter = document.getElementById('deployments-project-filter');
  const existingProject = projectFilter.value;
  projectFilter.innerHTML = '<option value="">Alle Projekte</option><option value="__none__">Ohne Projekt (Einzelbuchung)</option>'
    + projectsCache.map(p => `<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
  if (existingProject) projectFilter.value = existingProject;

  // Pending-Filter aus Drill-Down anwenden (v1.44.12)
  if (pendingDeploymentsFilter) {
    if (pendingDeploymentsFilter.range)   document.getElementById('deployments-range-filter').value  = pendingDeploymentsFilter.range;
    if (pendingDeploymentsFilter.status)  document.getElementById('deployments-status-filter').value = pendingDeploymentsFilter.status;
    if (pendingDeploymentsFilter.firma)   companyFilter.value = pendingDeploymentsFilter.firma;
    if (pendingDeploymentsFilter.projekt) projectFilter.value = pendingDeploymentsFilter.projekt;
    pendingDeploymentsFilter = null;
  }

  const { data, error } = await db.from('deployments')
    .select('*, company:companies(id, name), project:projects(id, name), service:services(id, name, einheit)').is('deleted_at', null)
    .order('datum_von', { ascending: false, nullsFirst: false })
    .order('created_at', { ascending: false });

  if (error) { tbody.innerHTML = `<tr><td colspan="8"><div class="empty">Fehler: ${esc(error.message)}</div></td></tr>`; return; }

  deploymentsCache = data || [];
  filterDeployments();
}

function filterDeployments() {
  const searchTerm  = document.getElementById('deployments-search').value.trim().toLowerCase();
  const rangeFilter = document.getElementById('deployments-range-filter').value;
  const statusFilter = document.getElementById('deployments-status-filter').value;
  const companyFilterVal = document.getElementById('deployments-company-filter').value;
  const projectFilterVal = document.getElementById('deployments-project-filter').value;

  const today = new Date(); today.setHours(0, 0, 0, 0);
  const todayISO = toISODate(today);

  let filtered = deploymentsCache;

  // Zeitraum
  if (rangeFilter === 'unscheduled') {
    filtered = filtered.filter(d => !d.datum_von);
  } else if (rangeFilter === 'upcoming') {
    filtered = filtered.filter(d => d.datum_bis && d.datum_bis >= todayISO);
  } else if (rangeFilter === 'past') {
    filtered = filtered.filter(d => d.datum_bis && d.datum_bis < todayISO);
  } else if (rangeFilter === 'month') {
    const mStart = toISODate(new Date(today.getFullYear(), today.getMonth(), 1));
    const mEnd   = toISODate(new Date(today.getFullYear(), today.getMonth() + 1, 0));
    filtered = filtered.filter(d => d.datum_von && d.datum_bis && d.datum_von <= mEnd && d.datum_bis >= mStart);
  } else if (rangeFilter === 'quarter') {
    const q = Math.floor(today.getMonth() / 3);
    const qStart = toISODate(new Date(today.getFullYear(), q * 3, 1));
    const qEnd   = toISODate(new Date(today.getFullYear(), q * 3 + 3, 0));
    filtered = filtered.filter(d => d.datum_von && d.datum_bis && d.datum_von <= qEnd && d.datum_bis >= qStart);
  } else if (rangeFilter === 'year') {
    const yStart = toISODate(new Date(today.getFullYear(), 0, 1));
    const yEnd   = toISODate(new Date(today.getFullYear(), 11, 31));
    filtered = filtered.filter(d => d.datum_von && d.datum_bis && d.datum_von <= yEnd && d.datum_bis >= yStart);
  }
  // 'all' zeigt alle (inkl. Ungeplante)

  if (statusFilter) filtered = filtered.filter(d => d.status === statusFilter);
  if (companyFilterVal) filtered = filtered.filter(d => d.company_id === companyFilterVal);
  if (projectFilterVal === '__none__') {
    filtered = filtered.filter(d => !d.project_id);
  } else if (projectFilterVal) {
    filtered = filtered.filter(d => d.project_id === projectFilterVal);
  }

  if (searchTerm) {
    filtered = filtered.filter(d => {
      const haystack = [d.titel, d.beschreibung, d.notizen, d.ort, d.externe_techniker,
                        d.company?.name, d.project?.name, d.service?.name]
        .filter(Boolean).join(' ').toLowerCase();
      return haystack.includes(searchTerm);
    });
  }

  renderDeploymentsTable(filtered);
}

function renderDeploymentsTable(deployments) {
  closeExpandedRow();
  const tbody = document.getElementById('deployments-table-body');
  const countEl = document.getElementById('deployments-count');

  const total = deploymentsCache.length;
  const shown = deployments.length;
  countEl.textContent = (shown === total)
    ? `${total} Einsatz${total === 1 ? '' : '̈e'}`.replace('tz̈e', 'tze')
    : `${shown} von ${total} Einsätzen`;
  // v2.6.3: Tab-Count zeigt Total, nicht shown
  // Hinweis zum Umsatz aktiver Einsätze
  const umsatzAktiv = deployments
    .filter(d => [DEPLOYMENT_STATUS.DURCHGEFUEHRT, DEPLOYMENT_STATUS.ABGERECHNET].includes(d.status) && !d.project_id)
    .reduce((sum, d) => sum + calcDeploymentNetto(d), 0);
  if (umsatzAktiv > 0) {
    countEl.textContent += ` · ${formatPreis(umsatzAktiv)} direkt abrechenbar`;
  }

  if (shown === 0) {
    const msg = total === 0
      ? 'Noch keine Einsätze angelegt. Klicke oben auf „+ Neuer Einsatz".'
      : 'Keine Einsätze entsprechen den Filterkriterien.';
    tbody.innerHTML = `<tr><td colspan="8"><div class="empty">${msg}</div></td></tr>`;
    return;
  }

  tbody.innerHTML = deployments.map(d => {
    const statusColor = einsatzStatusFarbe(d.status);
    const firmaHtml = d.company
      ? `<div class="cell-link" onclick="navigateTo('firma', '${esc(d.company.id)}')">${esc(d.company.name)}</div>`
      : '<span style="color:var(--muted);font-style:italic">—</span>';
    const projektHtml = d.project
      ? `<div class="cell-link" onclick="navigateTo('projekt', '${esc(d.project.id)}')">${esc(d.project.name)}</div>`
      : '<span style="color:var(--muted);font-style:italic">Einzelbuchung</span>';
    const leistungHtml = d.service
      ? esc(d.service.name)
      : '<span style="color:var(--muted);font-style:italic">—</span>';
    const brutto = calcDeploymentGesamt(d.menge, d.einzelpreis);
    const { rabatt, netto } = applyRabatt(brutto, d.rabatt_typ, d.rabatt_wert);
    const rabattLine = rabatt > 0
      ? `<div style="font-size:11px;color:var(--status-overdue-accent);margin-top:2px">${d.rabatt_typ === 'prozent' ? `Rabatt ${formatMenge(d.rabatt_wert)} % (−${formatPreis(rabatt)})` : `Rabatt −${formatPreis(rabatt)}`}</div>`
      : '';

    return `
      <tr data-dep-id="${esc(d.id)}" data-company-id="${esc(d.company_id || '')}" data-project-id="${esc(d.project_id || '')}">
        <td>${renderDeploymentDateCell(d.datum_von, d.datum_bis)}</td>
        <td>
          <div class="cell-link" onclick="toggleRowExpand('deployment','${esc(d.id)}',this.closest('tr'))">${esc(d.titel || '—')}${d.datum_von ? ROW_CAL_ICON : ''}</div>
        </td>
        <td class="col-tablet">${firmaHtml}</td>
        <td class="col-desktop">${projektHtml}</td>
        <td class="col-desktop" style="color:var(--muted)">${leistungHtml}</td>
        <td><span class="badge" style="background:${esc(statusColor)}22;color:${esc(statusColor)}">${esc(dispStatus(d.status))}</span></td>
        <td class="col-tablet">${esc(formatPreis(netto))}${rabattLine}</td>
        <td class="col-action" style="text-align:right">${renderActionIcons('deployment', d.id, renderDeploymentQuickStatusIcons(d))}</td>
      </tr>`;
  }).join('');
}

/**
 * Generiert einen Auto-Titel für den Einsatz:
 *   "Leistungsname × Firma × Benutzer"
 * Leere Teile werden übersprungen. Wird nur beim Neu-Anlegen verwendet.
 */
function generateDeploymentAutoTitle() {
  const serviceSelect = document.getElementById('d-service');
  let serviceName = '';
  if (serviceSelect.value) {
    const raw = serviceSelect.options[serviceSelect.selectedIndex]?.textContent || '';
    serviceName = raw.split(' (')[0].trim(); // Einheit-Klammer entfernen
  }

  // v1.44.11: d-company ist eine Combobox — der Anzeigename steht im Input
  const companyInput = document.getElementById('d-company');
  const companyName = (companyInput?.value || '').trim();

  // v2.33.20 (von Selcuk gemeldet): Der Auto-Titel nimmt den/die ANGEWÄHLTEN
  // Techniker (nicht mehr den eingeloggten User). Ist kein Techniker gewählt,
  // bleibt der Titel ohne Technikernamen.
  const technikerNames = [...selectedTechnikerIds]
    .map(id => (userProfilesCache.find(u => u.id === id)?.name) || '')
    .filter(Boolean)
    .join(', ');

  return [serviceName, companyName, technikerNames].filter(Boolean).join(' × ');
}

/**
 * Generiert eine Auto-Beschreibung für den Einsatz.
 * Format: "Leistung bei Firma am Datum von/bis. Techniker: ... Ort: ..."
 * Keine Preise. Wird nur beim Neu-Anlegen verwendet.
 */
function generateDeploymentAutoDescription() {
  const lines = [];

  const serviceSelect = document.getElementById('d-service');
  let serviceName = 'Einsatz';
  if (serviceSelect.value) {
    const raw = serviceSelect.options[serviceSelect.selectedIndex]?.textContent || '';
    serviceName = raw.split(' (')[0].trim();
  }

  // v1.44.11: d-company ist eine Combobox — der Anzeigename steht im Input
  const companyInput = document.getElementById('d-company');
  const companyName = (companyInput?.value || '').trim();

  const datumVon = document.getElementById('d-datum-von').value;
  const datumBis = document.getElementById('d-datum-bis').value;
  const uhrzeitVon = document.getElementById('d-uhrzeit-von').value;
  const uhrzeitBis = document.getElementById('d-uhrzeit-bis').value;

  // Satz 1: Was, Wo, Wann
  let satz = `${serviceName}${companyName ? ' bei ' + companyName : ''}`;
  if (datumVon && datumBis) {
    if (datumVon === datumBis) {
      satz += ` am ${formatDateDE(datumVon)}`;
    } else {
      satz += ` vom ${formatDateDE(datumVon)} bis ${formatDateDE(datumBis)}`;
    }
    if (uhrzeitVon && uhrzeitBis) {
      satz += ` von ${uhrzeitVon} bis ${uhrzeitBis} Uhr`;
    } else if (uhrzeitVon) {
      satz += ` ab ${uhrzeitVon} Uhr`;
    }
  }
  lines.push(satz + '.');

  // Techniker
  const techniker = [];
  if (selectedTechnikerIds && selectedTechnikerIds.size > 0) {
    const internal = [...selectedTechnikerIds]
      .map(uid => userProfilesCache.find(u => u.id === uid)?.name)
      .filter(Boolean);
    techniker.push(...internal);
  }
  const externe = document.getElementById('d-externe-techniker').value.trim();
  if (externe) techniker.push(externe + ' (extern)');
  if (techniker.length > 0) {
    lines.push(`Techniker: ${techniker.join(', ')}`);
  }

  // Ort
  const ort = document.getElementById('d-ort').value.trim();
  if (ort) {
    lines.push(`Ort: ${ort}`);
  }

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════
//  EINSATZ-MODAL
// ═══════════════════════════════════════════════════════════

async function openDeploymentModal(mode, deploymentId = null) {
  editingDeploymentId = deploymentId;
  selectedTechnikerIds = new Set();
  _deploymentMengeManuallyEdited = false;  // v1.33: Auto-Menge-Flag zurücksetzen
  _deploymentEinzelpreisManuallyEdited = false;  // v2.11.2: Auto-Preis-Flag zurücksetzen
  renderDateShortcuts();                    // v1.33: aktuelle Monats-Buttons

  // Caches sicherstellen
  await Promise.all([loadEinsatzStatus(), loadServicesCache(), loadUserProfilesCache()]);

  if (companiesCache.length === 0) {
    const { data: cs } = await db.from('companies').select('id, name, strasse, plz, stadt').is('deleted_at', null).order('name');
    companiesCache = cs || [];
  }
  // v2.32.7: Redundanten Reload-bei-jedem-Open entfernt — beim Composer-
  // Wechsel zwischen den Anlage-Aktionen lief der Query jedes Mal, was
  // spürbar bremste. Neue Firmen, die in einer parallelen Session
  // angelegt wurden, landen erst nach Browser-Reload im Cache — das ist
  // ein akzeptabler Trade-off für den Speed-Gewinn.

  // v1.44.11: d-company ist eine Combobox
  fillCompanyCombobox('d-company', 'd-company-list');
  // v2.32.6: Ansprechpartner-Combobox initial leer
  await fillContactCombobox('d-contact', 'd-contact-list', '');

  // Service-Dropdown (mit data-Attributen für Auto-Fill von Preis und Zeiten)
  const serviceSelect = document.getElementById('d-service');
  serviceSelect.innerHTML = '<option value="">— Keine Leistung —</option>'
    + servicesCache.map(s => {
        const uhrzeitVon = s.standard_uhrzeit_von ? s.standard_uhrzeit_von.substring(0, 5) : '';
        const uhrzeitBis = s.standard_uhrzeit_bis ? s.standard_uhrzeit_bis.substring(0, 5) : '';
        return `<option value="${esc(s.id)}"
                  data-preis="${s.standardpreis || 0}"
                  data-einheit="${esc(s.einheit || '')}"
                  data-uhrzeit-von="${esc(uhrzeitVon)}"
                  data-uhrzeit-bis="${esc(uhrzeitBis)}">${esc(s.name)} (${esc(s.einheit || '—')})</option>`;
      }).join('');

  // Status-Select dynamisch aus Lookup-Cache
  const statusSelect = document.getElementById('d-status');
  statusSelect.innerHTML = einsatzStatusCache.map(s =>
    `<option value="${esc(s.system_key)}">${esc(s.wert)}</option>`
  ).join('');
  statusSelect.value = einsatzStatusCache.find(s => s.system_key === DEPLOYMENT_STATUS.GEPLANT)?.system_key || einsatzStatusCache[0]?.system_key || '';

  // Felder zurücksetzen
  document.getElementById('d-titel').value = '';
  // Datum bleibt leer beim Neu-Anlegen → User kann bewusst "Ungeplant" wählen
  document.getElementById('d-datum-von').value = '';
  document.getElementById('d-datum-bis').value = '';
  document.getElementById('d-uhrzeit-von').value = '';
  document.getElementById('d-uhrzeit-bis').value = '';
  document.getElementById('d-uhrzeit-von').disabled = false;
  document.getElementById('d-uhrzeit-bis').disabled = false;
  const dGanz = document.getElementById('d-ganztag'); if (dGanz) dGanz.checked = false;
  document.getElementById('d-ort').value = '';
  document.getElementById('d-ort-hint').style.display = 'none';
  document.getElementById('d-menge').value = '1';
  document.getElementById('d-einzelpreis').value = '';
  // v2.28.2: Rabatt-Felder zurücksetzen
  const dRabattTyp = document.getElementById('d-rabatt-typ');
  const dRabattWert = document.getElementById('d-rabatt-wert');
  if (dRabattTyp) dRabattTyp.value = '';
  if (dRabattWert) { dRabattWert.value = ''; dRabattWert.disabled = true; }
  // v2.25.2: Kurz-Beschreibung + Doku-Block aus dem Einsatz-Modal entfernt
  // (User-Wunsch). Daten in deployments.beschreibung / .dokumentation bleiben
  // in der DB — werden beim Speichern nur nicht mehr überschrieben.
  document.getElementById('d-externe-techniker').value = '';
  document.getElementById('d-create-appointment').checked = false;
  // Redeem-State zurücksetzen (v1.14.0)
  document.getElementById('d-redeem-check').checked = false;
  document.getElementById('d-redeem-details').style.display = 'none';
  document.getElementById('d-redeem-wrap').style.display = 'none';
  const datumHintWrap = document.getElementById('d-datum-hint-wrap');
  if (datumHintWrap) datumHintWrap.style.display = '';
  // v2.12.2: Bündel-Banner per default verstecken; wird im Edit-Pfad ggf. wieder eingeblendet.
  const _bundleBanner = document.getElementById('d-bundle-banner');
  if (_bundleBanner) _bundleBanner.style.display = 'none';

  renderTechnikerChipsForDeployment();
  await rebuildProjectDropdownForDeployment('');
  updateDeploymentPriceHint();

  setupDeploymentModalListeners();

  if (mode === 'new') {
    document.getElementById('modal-deployment-title').textContent = 'Neuer Einsatz';
    document.getElementById('d-save-btn').textContent = 'Anlegen';
    document.getElementById('d-delete-btn').style.display = 'none';

    // Prefill aus Firmen-Detail / Projekt-Detail
    if (deploymentModalPrefillCompanyId) {
      setCompanyComboboxValue('d-company', 'd-company-list', deploymentModalPrefillCompanyId);
      await rebuildContactDropdownForDeployment(deploymentModalPrefillCompanyId);  // v2.32.6
      await rebuildProjectDropdownForDeployment(deploymentModalPrefillCompanyId);
      updateDeploymentOrtHint();
      // v2.1.2: Firma-Adresse direkt ins Ort-Feld
      const ortInput = document.getElementById('d-ort');
      if (!ortInput.value.trim()) {
        const company = companiesCache.find(c => c.id === deploymentModalPrefillCompanyId);
        const addr = formatCompanyAddress(company);
        if (addr) ortInput.value = addr;
      }
      deploymentModalPrefillCompanyId = null;
    }
    if (deploymentModalPrefillProjectId) {
      // Projekt laden + dessen Firma setzen, falls noch nicht
      const { data: proj } = await db.from('projects')
        .select('id, name, company_id').is('deleted_at', null).eq('id', deploymentModalPrefillProjectId).single();
      if (proj) {
        if (proj.company_id) {
          setCompanyComboboxValue('d-company', 'd-company-list', proj.company_id);
          await rebuildProjectDropdownForDeployment(proj.company_id);
          updateDeploymentOrtHint();
        }
        document.getElementById('d-project').value = proj.id;
      }
      deploymentModalPrefillProjectId = null;
    }
    // Service-Prefill (Schnellaktionen, v1.25)
    if (window._pendingDeploymentPrefillServiceId) {
      serviceSelect.value = window._pendingDeploymentPrefillServiceId;
      window._pendingDeploymentPrefillServiceId = null;
      // Auto-Fill von Preis/Uhrzeit/Titel anstoßen (wie wenn der User selbst klickt)
      serviceSelect.dispatchEvent(new Event('change', { bubbles: true }));
    }
    updateDeploymentPriceHint();
  } else {
    document.getElementById('modal-deployment-title').textContent = 'Einsatz bearbeiten';
    document.getElementById('d-save-btn').textContent = 'Speichern';
    document.getElementById('d-delete-btn').style.display = 'block';

    const { data, error } = await db.from('deployments').select('*').is('deleted_at', null).eq('id', deploymentId).single();
    if (error || !data) { showToast('Einsatz konnte nicht geladen werden: ' + (error?.message || 'Unbekannter Fehler'), true); editingDeploymentId = null; return; }

    document.getElementById('d-titel').value = data.titel || '';
    document.getElementById('d-datum-von').value = data.datum_von || '';
    document.getElementById('d-datum-bis').value = data.datum_bis || '';
    document.getElementById('d-uhrzeit-von').value = data.uhrzeit_von ? data.uhrzeit_von.substring(0, 5) : '';
    document.getElementById('d-uhrzeit-bis').value = data.uhrzeit_bis ? data.uhrzeit_bis.substring(0, 5) : '';
    document.getElementById('d-status').value = data.status || DEPLOYMENT_STATUS.GEPLANT;
    document.getElementById('d-ort').value = data.ort || '';
    document.getElementById('d-menge').value = data.menge ?? 1;
    _deploymentMengeManuallyEdited = true;  // v1.33: existierende Menge nicht durch Auto-Berechnung ersetzen
    document.getElementById('d-einzelpreis').value = data.einzelpreis ?? '';
    // v2.28.2: Rabatt aus DB lesen
    const dRabattTypEl = document.getElementById('d-rabatt-typ');
    const dRabattWertEl = document.getElementById('d-rabatt-wert');
    if (dRabattTypEl)  dRabattTypEl.value  = data.rabatt_typ || '';
    if (dRabattWertEl) {
      dRabattWertEl.value = data.rabatt_wert ?? '';
      dRabattWertEl.disabled = !data.rabatt_typ;
    }
    _deploymentEinzelpreisManuallyEdited = true;  // v2.11.2: gespeicherter Preis ist heilig — Service-Wechsel überschreibt ihn nicht
    // v2.25.2: Kurz-Beschreibung + Doku-Block aus dem Einsatz-Modal entfernt
    // (User-Wunsch). Werte werden hier nicht mehr in die UI gespiegelt.
    document.getElementById('d-externe-techniker').value = data.externe_techniker || '';

    // v2.11.3: Wenn der Einsatz ein Projekt hat, aber keine Firma (z.B. weil er
    // vor v2.11.3 aus einem Template angelegt wurde), Firma aus dem Projekt
    // nachladen — sonst öffnet sich der Edit-Modal mit leerem Firma-Feld und
    // Projekt-Dropdown ohne passende Option.
    let effectiveCompanyId = data.company_id;
    if (!effectiveCompanyId && data.project_id) {
      const { data: projRow } = await db.from('projects')
        .select('company_id').is('deleted_at', null).eq('id', data.project_id).single();
      effectiveCompanyId = projRow?.company_id || null;
    }
    if (effectiveCompanyId) {
      setCompanyComboboxValue('d-company', 'd-company-list', effectiveCompanyId);
      // v2.32.6: Kontakt-Dropdown nach Firma laden, dann ggf. den gespeicherten Kontakt setzen
      await rebuildContactDropdownForDeployment(effectiveCompanyId);
      if (data.contact_id) setContactComboboxValue('d-contact', 'd-contact-list', data.contact_id);
      // v2.31.1: forceIncludeProjectId stellt sicher, dass das aktuell zugeordnete
      // Projekt in der Dropdown landet, auch wenn sein Status nicht im Default-Filter
      // ist (z. B. ABSCHLUSSPHASE — vorher Outlier — oder VERLOREN/STORNIERT).
      await rebuildProjectDropdownForDeployment(effectiveCompanyId, data.project_id || null);
      if (data.project_id) document.getElementById('d-project').value = data.project_id;
      updateDeploymentOrtHint();
    }

    if (data.service_id) serviceSelect.value = data.service_id;

    // v2.12.2: Bündel-Banner anzeigen, wenn der Einsatz Teil eines Bündels ist.
    const banner = document.getElementById('d-bundle-banner');
    if (banner && data.bundle_id) {
      const { data: bundleRow } = await db.from('deployment_bundles')
        .select('id, titel').is('deleted_at', null).eq('id', data.bundle_id).single();
      if (bundleRow) {
        const link = document.getElementById('d-bundle-banner-link');
        if (link) {
          link.textContent = bundleRow.titel || 'Bündel öffnen';
          link.onclick = (e) => {
            e.preventDefault();
            closeDeploymentModal();
            openDeploymentBundleModal('edit', bundleRow.id);
          };
        }
        const hint = document.getElementById('d-bundle-banner-hint');
        if (hint) {
          const overrides = Array.isArray(data.bundle_overrides) ? data.bundle_overrides : [];
          hint.textContent = overrides.length === 0
            ? 'Felder, die du hier änderst, werden beim nächsten Bündel-Save nicht mehr überschrieben.'
            : `Schon entkoppelte Felder: ${overrides.join(', ')}. Weitere Änderungen werden ebenfalls geschützt.`;
        }
        banner.style.display = '';
      }
    } else if (banner) {
      banner.style.display = 'none';
    }

    // Techniker laden
    const { data: techRows } = await db.from('deployment_technicians')
      .select('user_id').eq('deployment_id', deploymentId);
    selectedTechnikerIds = new Set((techRows || []).map(t => t.user_id));
    renderTechnikerChipsForDeployment();

    // Verknüpften Termin prüfen
    const { data: linkedAppt } = await db.from('appointments')
      .select('id').is('deleted_at', null).eq('deployment_id', deploymentId).limit(1);
    document.getElementById('d-create-appointment').checked = (linkedAppt || []).length > 0;

    // Bestehende Redemption laden (v1.14.0)
    const { data: linkedRedemption } = await db.from('entitlement_redemptions')
      .select('entitlement_id, menge_eingeloest')
      .eq('deployment_id', deploymentId).limit(1);
    if (linkedRedemption && linkedRedemption.length > 0) {
      // Merken - wird nach refreshRedeemSection angewandt
      window._pendingRedemptionEntitlementId = linkedRedemption[0].entitlement_id;
      window._pendingRedemptionMenge = linkedRedemption[0].menge_eingeloest;
    } else {
      window._pendingRedemptionEntitlementId = null;
      window._pendingRedemptionMenge = null;
    }

    updateDeploymentPriceHint();
  }

  await refreshRedeemSection();  // v1.14.0 - lädt offene Entitlements der Firma

  setupDeploymentPreviewListeners();  // v1.38
  renderDeploymentPreview();           // v1.38

  // v2.11.2: Einmaliger initialer Check für den Aktualisieren-Button — wenn
  // Edit-Preis vom Service-Standard abweicht, leuchtet der Button sofort beim
  // Öffnen des Modals. v2.11.4: dasselbe für die Menge.
  updateEinzelpreisOutdatedState();
  updateMengeOutdatedState();

  await populateTemplateDropdown('einsatz', mode);

  // v1.53.0: Theme-Picker initialisieren — Edit-Modus mit existierenden Themen,
  // New-Modus leer. _deploymentInitialThemeIds spiegelt den DB-Stand für Save-Diff.
  const _projectSel = document.getElementById('d-project');
  const _initialProjectId = _projectSel ? (_projectSel.value || null) : null;
  let _initialThemeIds = [];
  if (mode === 'edit' && deploymentId) {
    _initialThemeIds = await fetchDeploymentThemeIds(deploymentId);
  }
  _deploymentInitialThemeIds = new Set(_initialThemeIds);
  await renderDeploymentThemePicker(_initialProjectId, _initialThemeIds);

  document.getElementById('modal-deployment').classList.add('open');
  setTimeout(() => document.getElementById('d-titel').focus(), 100);
}

function setupDeploymentModalListeners() {
  const companyInput = document.getElementById('d-company');
  const serviceSelect = document.getElementById('d-service');
  const datumVon = document.getElementById('d-datum-von');
  const datumBis = document.getElementById('d-datum-bis');
  const menge = document.getElementById('d-menge');
  const einzelpreis = document.getElementById('d-einzelpreis');

  // v1.44.11: Combobox-Input statt Select. Bei Match (existierende Firma)
  // werden Projekt-Dropdown und Adress-Auto-Fill getriggert.
  companyInput.oninput = async () => {
    const id = getCompanyComboboxId('d-company', 'd-company-list');
    await rebuildProjectDropdownForDeployment(id);
    updateDeploymentOrtHint();

    // Auto-Ort: Wenn Ort-Feld leer und Firma (mit Match) Adresse hat → übernehmen
    const ortInput = document.getElementById('d-ort');
    if (!ortInput.value.trim() && id) {
      const company = companiesCache.find(c => c.id === id);
      if (company) {
        const parts = [company.strasse, [company.plz, company.stadt].filter(Boolean).join(' ')].filter(Boolean);
        if (parts.length > 0) {
          ortInput.value = parts.join(', ');
        }
      }
    }

    updateDeploymentPriceHint();
    await refreshRedeemSection();  // v1.14.0
  };

  // v1.53.0: Projekt-Wechsel mit existierenden Theme-Zuordnungen → Confirm-Dialog
  const projectSel = document.getElementById('d-project');
  projectSel.onchange = async () => {
    const newProjectId = projectSel.value || null;
    const ok = await confirmDeploymentProjectSwitch(newProjectId);
    if (!ok) {
      projectSel.value = _deploymentLastProjectId || '';
      return;
    }
    _deploymentSelectedThemeIds = new Set();
    _deploymentInitialThemeIds  = new Set();
    await renderDeploymentThemePicker(newProjectId, []);
    updateDeploymentPriceHint();
  };

  serviceSelect.onchange = () => {
    // v2.11.2: Auto-fill Einzelpreis nur dann, wenn der User ihn NICHT manuell
    // editiert hat. Sonst bleibt der individuelle Preis stehen — der
    // Aktualisieren-Button neben dem Preisfeld leuchtet aber farbig, damit
    // sofort erkennbar ist, dass der Preis vom Service-Standard abweicht.
    const opt = serviceSelect.options[serviceSelect.selectedIndex];
    const preis = opt?.getAttribute('data-preis');
    const uhrzeitVon = opt?.getAttribute('data-uhrzeit-von');
    const uhrzeitBis = opt?.getAttribute('data-uhrzeit-bis');

    if (preis && !_deploymentEinzelpreisManuallyEdited) {
      document.getElementById('d-einzelpreis').value = preis;
    }

    // Auto-fill Uhrzeiten aus Service-Defaults, wenn Felder leer
    const dVon = document.getElementById('d-uhrzeit-von');
    const dBis = document.getElementById('d-uhrzeit-bis');
    if (uhrzeitVon && !dVon.value) dVon.value = uhrzeitVon;
    if (uhrzeitBis && !dBis.value) dBis.value = uhrzeitBis;

    updateDeploymentPriceHint();
    updateEinzelpreisOutdatedState();
  };

  // Gemeinsamer Handler für Datums-Änderungen — v1.33 auto-Menge nach Werktagen.
  const onDatumChange = () => {
    // datum_bis mit-anpassen wenn vorher = datum_von oder leer
    if (datumVon.value && (!datumBis.value || datumBis.value < datumVon.value)) {
      datumBis.value = datumVon.value;
    }
    recomputeDeploymentMengeFromDates();
    // v2.11.4: Auch wenn die Menge wegen Manual-Override stehen blieb, soll
    // der ↻-Button warnfarbig leuchten, falls die Menge zum neuen Datums-
    // bereich nicht mehr passt.
    updateMengeOutdatedState();
  };
  datumVon.onchange = onDatumChange;
  datumBis.onchange = onDatumChange;

  // User-Edit auf Menge setzt den Manual-Override-Flag, damit die Auto-Berechnung
  // die manuelle Eingabe nicht überschreibt.
  menge.addEventListener('input', (e) => {
    if (e.isTrusted) _deploymentMengeManuallyEdited = true;
    updateDeploymentPriceHint();
    updateMengeOutdatedState();
  });
  // v2.11.2: User-Edit am Einzelpreis setzt analog den Manual-Override-Flag,
  // damit der nächste Service-Wechsel den Preis nicht überschreibt. Außerdem
  // Aktualisieren-Button-State neu berechnen.
  einzelpreis.addEventListener('input', (e) => {
    if (e.isTrusted) _deploymentEinzelpreisManuallyEdited = true;
    updateDeploymentPriceHint();
    updateEinzelpreisOutdatedState();
  });

  // Reset-Icon neben Menge
  const resetBtn = document.getElementById('d-menge-reset');
  if (resetBtn) {
    resetBtn.onclick = () => {
      _deploymentMengeManuallyEdited = false;
      recomputeDeploymentMengeFromDates(true);
      updateMengeOutdatedState();   // v2.11.4
    };
  }

  // v2.11.2: Reset-Icon neben Einzelpreis — auf Service-Standardpreis springen
  // und das Manual-Override-Flag zurücksetzen.
  const priceResetBtn = document.getElementById('d-einzelpreis-reset');
  if (priceResetBtn) {
    priceResetBtn.onclick = () => {
      const opt = serviceSelect.options[serviceSelect.selectedIndex];
      const preis = opt?.getAttribute('data-preis');
      if (!preis) { showToast('Kein Service mit Standardpreis gewählt.', true); return; }
      document.getElementById('d-einzelpreis').value = preis;
      _deploymentEinzelpreisManuallyEdited = false;
      updateDeploymentPriceHint();
      updateEinzelpreisOutdatedState();
    };
  }
}

/** v2.11.2: Markiert den Aktualisieren-Button neben dem Einzelpreis farblich,
 *  sobald der aktuelle Preis vom Service-Standardpreis abweicht. Greift bei
 *  Service-Wechsel, manuellem Edit und beim Öffnen im Edit-Modus. */
function updateEinzelpreisOutdatedState() {
  const btn = document.getElementById('d-einzelpreis-reset');
  if (!btn) return;
  const serviceSelect = document.getElementById('d-service');
  const opt = serviceSelect?.options?.[serviceSelect.selectedIndex];
  const standard = Number(opt?.getAttribute('data-preis') || 0);
  const aktuell  = Number(document.getElementById('d-einzelpreis').value || 0);
  // Ohne Service oder ohne Standardpreis kein Hinweis — Button bleibt neutral.
  const showOutdated = standard > 0 && aktuell !== standard;
  btn.classList.toggle('is-outdated', showOutdated);
  btn.title = showOutdated
    ? `Einzelpreis abweichend von Service-Standardpreis (${formatPreis(standard)}). Klick übernimmt den Standardpreis.`
    : 'Einzelpreis auf Service-Standardpreis aktualisieren';
}

/** v2.11.4: Markiert den Aktualisieren-Button neben der Menge farblich, sobald
 *  die aktuelle Menge nicht mehr zur Werktage-Zahl im gewählten Datumsbereich
 *  passt — also entweder der User die Menge manuell überschrieben hat, oder
 *  das Datum nachträglich geändert wurde. Greift bei Datums-Change, manuellem
 *  Edit und beim Öffnen im Edit-Modus. */
function updateMengeOutdatedState() {
  const btn = document.getElementById('d-menge-reset');
  if (!btn) return;
  const von = document.getElementById('d-datum-von').value;
  const bis = document.getElementById('d-datum-bis').value || von;
  if (!von) {
    btn.classList.remove('is-outdated');
    btn.title = 'Menge aus Datumsbereich neu berechnen (Werktage)';
    return;
  }
  const workdays = countWorkdaysInclusive(von, bis);
  const aktuell  = Number(document.getElementById('d-menge').value || 0);
  const showOutdated = workdays >= 1 && aktuell !== workdays;
  btn.classList.toggle('is-outdated', showOutdated);
  btn.title = showOutdated
    ? `Menge passt nicht zur Werktage-Zahl im Datumsbereich (${workdays} WT). Klick berechnet neu.`
    : 'Menge aus Datumsbereich neu berechnen (Werktage)';
}

/** Werktags-Menge aus datum_von/bis berechnen (v1.33). Überschreibt Menge nicht,
 *  wenn der User bereits manuell editiert hat — außer `force=true` (Reset-Icon). */
function recomputeDeploymentMengeFromDates(force = false) {
  if (!force && _deploymentMengeManuallyEdited) return;
  const von = document.getElementById('d-datum-von').value;
  const bis = document.getElementById('d-datum-bis').value || von;
  if (!von) return;
  const workdays = countWorkdaysInclusive(von, bis);
  if (workdays < 1) return;
  const mengeInput = document.getElementById('d-menge');
  mengeInput.value = String(workdays);
  updateDeploymentPriceHint();
}

function updateDeploymentOrtHint() {
  const companyId = getCompanyComboboxId('d-company', 'd-company-list');
  const hint = document.getElementById('d-ort-hint');
  if (!companyId) { hint.style.display = 'none'; return; }
  const company = companiesCache.find(c => c.id === companyId);
  if (!company) { hint.style.display = 'none'; return; }
  const parts = [company.strasse, [company.plz, company.stadt].filter(Boolean).join(' ')].filter(Boolean);
  if (parts.length === 0) { hint.style.display = 'none'; return; }
  hint.innerHTML = `Firmenadresse: ${esc(parts.join(', '))} <span style="text-decoration:underline">· übernehmen</span>`;
  hint.style.display = '';
}

function useCompanyAddressForDeploymentOrt() {
  const companyId = getCompanyComboboxId('d-company', 'd-company-list');
  if (!companyId) return;
  const company = companiesCache.find(c => c.id === companyId);
  if (!company) return;
  const parts = [company.strasse, [company.plz, company.stadt].filter(Boolean).join(' ')].filter(Boolean);
  if (parts.length === 0) return;
  document.getElementById('d-ort').value = parts.join(', ');
}

function updateDeploymentPriceHint() {
  const hintEl = document.getElementById('d-preis-hint');
  const mengeGroup = document.getElementById('d-menge-group');
  const preisGroup = document.getElementById('d-einzelpreis-group');
  const menge = Number(document.getElementById('d-menge').value) || 0;
  const einzel = Number(document.getElementById('d-einzelpreis').value) || 0;
  const gesamt = menge * einzel;
  const projectId = document.getElementById('d-project').value;
  const projectSelect = document.getElementById('d-project');
  const projectName = projectId ? (projectSelect.options[projectSelect.selectedIndex]?.textContent || 'Projekt') : null;

  // Menge + Einzelpreis immer sichtbar — auch bei Projekt, damit Mehr-/Mindereinsätze trackbar sind
  mengeGroup.style.display = '';
  preisGroup.style.display = '';

  if (projectId) {
    // Projekt-Zuordnung: Hinweis, dass Wert nur für internes Tracking ist
    hintEl.innerHTML = `Interner Wert: <strong>${esc(formatPreis(gesamt))}</strong> · Nur zum Aufwands-Tracking. Kundenumsatz läuft über Projekt-Paketpreis „${esc(projectName)}".`;
  } else {
    // Einzelbuchung: Gesamt-Preis wird direkt abgerechnet
    hintEl.innerHTML = `Gesamt: <strong>${esc(formatPreis(gesamt))}</strong> · Wird direkt dem Kunden berechnet.`;
  }
}

async function rebuildProjectDropdownForDeployment(companyId, forceIncludeProjectId = null) {
  const select = document.getElementById('d-project');
  if (!select) return;
  if (!companyId) {
    select.innerHTML = '<option value="">— Kein Projekt (Einzelbuchung) —</option>';
    return;
  }
  // v2.31.1: ABSCHLUSSPHASE war als Outlier nicht in der Liste — die Modal-Dropdown
  // hat das Projekt verschluckt, beim Save wurde project_id auf null geschrieben
  // und der Einsatz aus dem Projekt ausgehängt.
  const { data, error } = await db.from('projects')
    .select('id, name, status').is('deleted_at', null).eq('company_id', companyId)
    .in('status', [PROJECT_STATUS.LEAD, PROJECT_STATUS.ANGEBOT, PROJECT_STATUS.IN_ARBEIT, PROJECT_STATUS.ABSCHLUSSPHASE, PROJECT_STATUS.ABGESCHLOSSEN])
    .order('name');
  if (error) { select.innerHTML = '<option value="">Fehler beim Laden</option>'; return; }
  const projects = data || [];
  // v2.31.1: defensive — wenn der Edit-Pfad ein zugeordnetes Projekt hat, das nicht
  // im Filter landet (z. B. VERLOREN, STORNIERT), trotzdem als Option anhängen, damit
  // setValue() greift und die Zuordnung nicht stillschweigend zerstört wird.
  if (forceIncludeProjectId && !projects.some(p => p.id === forceIncludeProjectId)) {
    const { data: extra } = await db.from('projects')
      .select('id, name, status').is('deleted_at', null).eq('id', forceIncludeProjectId).single();
    if (extra) projects.push(extra);
  }
  select.innerHTML = '<option value="">— Kein Projekt (Einzelbuchung) —</option>'
    + projects.map(p => `<option value="${esc(p.id)}">${esc(p.name)} · ${esc(dispStatus(p.status))}</option>`).join('');
}

function renderTechnikerChipsForDeployment() {
  const wrap = document.getElementById('d-techniker-list');
  if (userProfilesCache.length === 0) {
    wrap.innerHTML = '<span style="font-size:12px;color:var(--muted)">Keine internen Techniker verfügbar.</span>';
    return;
  }
  wrap.innerHTML = userProfilesCache.map(u => {
    const selected = selectedTechnikerIds.has(u.id);
    return `
      <div class="techniker-chip${selected ? ' selected' : ''}" data-user-id="${esc(u.id)}"
           onclick="toggleTechnikerChip('${esc(u.id)}')">
        <span class="techniker-chip-avatar">${esc(ini(u.name))}</span>
        <span>${esc(u.name)}</span>
      </div>`;
  }).join('');
}

function toggleTechnikerChip(userId) {
  if (selectedTechnikerIds.has(userId)) selectedTechnikerIds.delete(userId);
  else selectedTechnikerIds.add(userId);
  renderTechnikerChipsForDeployment();
}

function closeDeploymentModal() {
  document.getElementById('modal-deployment').classList.remove('open');
  editingDeploymentId = null;
  deploymentModalPrefillCompanyId = null;
  deploymentModalPrefillProjectId = null;
  selectedTechnikerIds = new Set();
}

// v2.33.14 (QA-Sweep Phase B #2): Ein Einsatz darf nur dann auf
// „durchgeführt"/„abgerechnet" gesetzt werden, wenn ein Datum hinterlegt ist.
// Ein erledigter/abgerechneter Einsatz ohne Datum ist fachlich widersprüchlich —
// Monats-/Auslastungs-Reports können ihn nicht periodisch zuordnen und die
// Auto-Projektstatus-Logik verhält sich undefiniert. Genau so entstanden die
// zwei dateless ifm-GmbH-Einsätze. Zentral, weil sechs Pfade den Status auf
// durchgeführt/abgerechnet setzen können (Modal, Composer→Modal, Quick-Toggle,
// Hero-Buttons, Status-Pille, Advance).
function deploymentStatusRequiresDatum(status) {
  return status === DEPLOYMENT_STATUS.DURCHGEFUEHRT
      || status === DEPLOYMENT_STATUS.ABGERECHNET;
}
/** @returns {boolean} true = Statuswechsel erlaubt; false = blockiert (zeigt Toast). */
function ensureDeploymentDatumForStatus(status, hasDatum) {
  if (deploymentStatusRequiresDatum(status) && !hasDatum) {
    showToast('Status „durchgeführt"/„abgerechnet" braucht ein Datum am Einsatz — bitte zuerst „Datum von" setzen.', true);
    return false;
  }
  return true;
}

async function saveDeployment() {
  const titel         = document.getElementById('d-titel').value.trim();
  const datum_von     = document.getElementById('d-datum-von').value;
  const datum_bis     = document.getElementById('d-datum-bis').value;
  const uhrzeit_von   = document.getElementById('d-uhrzeit-von').value;
  const uhrzeit_bis   = document.getElementById('d-uhrzeit-bis').value;
  const status        = document.getElementById('d-status').value;
  const project_id    = document.getElementById('d-project').value || null;
  const service_id    = document.getElementById('d-service').value || null;
  const mengeRaw      = document.getElementById('d-menge').value;
  const einzelRaw     = document.getElementById('d-einzelpreis').value;
  const ort           = document.getElementById('d-ort').value.trim();
  // v2.25.2: Kurz-Beschreibung + Doku-Block aus dem Einsatz-Modal entfernt.
  // Bestehender Wert wird beim Bearbeiten erhalten (read-from-DB, write-back).
  let beschreibungInput = '';
  let _existingDeploymentDoc = null;
  let _existingDeploymentBundleId = null;
  let _existingDeploymentOverrides = [];
  let _oldProjectId = null;  // v2.33.16 (Phase A.1 #6): altes Projekt für Auto-Status nach Wechsel
  if (editingDeploymentId) {
    const { data: _existing } = await db.from('deployments')
      .select('beschreibung, dokumentation, bundle_id, bundle_overrides, project_id').eq('id', editingDeploymentId).single();
    beschreibungInput = _existing?.beschreibung || '';
    _existingDeploymentDoc = _existing?.dokumentation || null;
    _existingDeploymentBundleId = _existing?.bundle_id || null;
    _existingDeploymentOverrides = Array.isArray(_existing?.bundle_overrides) ? _existing.bundle_overrides : [];
    _oldProjectId = _existing?.project_id || null;
  }
  const dokumentation = _existingDeploymentDoc || {};
  const externe_techniker = document.getElementById('d-externe-techniker').value.trim();
  const createAppointment = document.getElementById('d-create-appointment').checked;
  const btn           = document.getElementById('d-save-btn');

  // v2.33.7: Doppelklick-Race-Guard (Phase A.2 #1). Bisher wurde
  // `btn.disabled = true` erst nach den awaits gesetzt (Z. ~14820),
  // davor laufen resolveCompanyComboboxValue + resolveContactComboboxValue,
  // die bei unbekanntem Combobox-Text einen DB-Insert machen → zwei
  // schnelle Klicks erzeugten zwei Firmen + zwei deployment-Rows.
  // Mit dataset.busy als Re-Entry-Guard bail-out wir den zweiten Klick
  // sofort. Sicherheitsnetz (10s setTimeout) räumt auf, falls der Code
  // vorher per early-return aus den sync-Validierungen rausspringt.
  if (btn.dataset.busy === '1') return;
  btn.dataset.busy = '1';
  const _saveDepReleaseT = setTimeout(() => { btn.dataset.busy = '0'; }, 10000);

  // Auto-Titel + Auto-Beschreibung nur beim Neu-Anlegen (nicht beim Edit)
  const isNew = !editingDeploymentId;
  // v1.44.11: Firma-Combobox auflösen — legt ggf. eine neue Firma an.
  // Muss VOR Auto-Titel-Generierung passieren, damit der Firmen-Name
  // im Cache steht.
  let company_id = null;
  try {
    company_id = await resolveCompanyComboboxValue('d-company', 'd-company-list');
  } catch (e) {
    return;
  }
  // v2.32.6: Kontakt-Combobox auflösen — legt ggf. neuen Kontakt mit der
  // resolved company_id an. Eine Firma kann mehrere Ansprechpartner haben;
  // saveDeployment akzeptiert auch null (Kontakt optional).
  let contact_id = null;
  try {
    contact_id = await resolveContactComboboxValue('d-contact', 'd-contact-list', company_id);
  } catch (e) {
    return;
  }

  const finalTitel = titel || (isNew ? generateDeploymentAutoTitle() : '');
  const finalBeschreibung = beschreibungInput || (isNew ? generateDeploymentAutoDescription() : '');

  if (!finalTitel) { showToast('Bitte Titel eingeben (oder Leistung/Firma wählen für Auto-Titel).', true); return; }
  if (!company_id) { showToast('Bitte Firma auswählen oder neuen Namen tippen.', true); return; }

  // v2.10.3: Datum und Uhrzeit dürfen jederzeit teilweise oder gar nicht
  // gefüllt sein — der Einsatz darf in jeder Vorbereitungsstufe gespeichert
  // werden. Nachgezogen werden später automatisch:
  //   1) datum_bis spiegelt datum_von (falls leer), um den DB-CHECK
  //      `deployments_datum_consistency` (entweder beide NULL oder beide
  //      NOT NULL) zu erfüllen — siehe Payload-Bau unten.
  //   2) status springt auf „Ungeplant", wenn kein datum_von gesetzt ist
  //      und der User noch keinen finalen Status vergeben hat.
  const vonGesetzt = !!datum_von;
  const bisGesetzt = !!datum_bis;
  if (vonGesetzt && bisGesetzt && datum_bis < datum_von) {
    showToast('Datum bis muss nach Datum von liegen.', true); return;
  }

  if (!Object.values(DEPLOYMENT_STATUS).includes(status) &&
      !einsatzStatusCache.some(s => s.system_key === status)) {
    showToast('Status ungültig. Bitte aus Liste wählen.', true); return;
  }
  // v2.33.14: durchgeführt/abgerechnet verlangt ein Datum (Phase B #2). Greift
  // auch beim Bearbeiten von Altbeständen — der frühere „Bestandsschutz" (siehe
  // effStatus-Block unten) ließ dateless Done-Einsätze durch. busy-Flag wird vom
  // 10s-Sicherheitsnetz (_saveDepReleaseT, oben) zurückgesetzt.
  if (!ensureDeploymentDatumForStatus(status, vonGesetzt || bisGesetzt)) return;
  if (uhrzeit_von && uhrzeit_bis && uhrzeit_von >= uhrzeit_bis) {
    showToast('„Uhrzeit bis" muss nach „Uhrzeit von" liegen.', true); return;
  }

  const menge = mengeRaw === '' ? 1 : Number(mengeRaw);
  if (Number.isNaN(menge) || menge < 0) { showToast('Menge muss eine Zahl ≥ 0 sein.', true); return; }
  const einzelpreis = einzelRaw === '' ? 0 : Number(einzelRaw);
  if (Number.isNaN(einzelpreis) || einzelpreis < 0) { showToast('Einzelpreis muss eine Zahl ≥ 0 sein.', true); return; }

  // v2.28.2: Rabatt-Felder einlesen + validieren
  const rabattTypRaw  = document.getElementById('d-rabatt-typ')?.value || '';
  const rabattWertRaw = document.getElementById('d-rabatt-wert')?.value || '';
  let rabatt_typ = null;
  let rabatt_wert = null;
  if (rabattTypRaw && rabattWertRaw !== '') {
    const wert = Number(rabattWertRaw);
    if (Number.isNaN(wert) || wert < 0) {
      showToast('Rabatt-Wert muss eine Zahl ≥ 0 sein.', true); return;
    }
    if (rabattTypRaw === 'prozent' && wert > 100) {
      showToast('Rabatt-Prozent kann nicht über 100 % liegen.', true); return;
    }
    rabatt_typ = rabattTypRaw;
    rabatt_wert = wert;
  }

  btn.disabled = true;
  btn.textContent = editingDeploymentId ? 'Wird gespeichert ...' : 'Wird angelegt ...';

  try {
    // v2.10.3: Teil-gefüllte Daten/Uhrzeiten ergänzen, damit der DB-CHECK
    // `deployments_datum_consistency` (entweder beide NULL oder beide gesetzt)
    // erfüllt ist und der Status zur Realität passt.
    let effDatumVon = datum_von || null;
    let effDatumBis = datum_bis || null;
    if (effDatumVon && !effDatumBis) effDatumBis = effDatumVon;        // Single-Day-Default
    else if (!effDatumVon && effDatumBis) effDatumVon = effDatumBis;   // umgekehrt analog
    // Status auto-flippen: Kein Datum + noch „Geplant" → „Ungeplant"
    // (Durchgeführt/Abgerechnet/Storniert bleiben unangetastet — die haben
    // Bestandsschutz, falls der User einen abgeschlossenen Einsatz nachträglich
    // ohne Datum bearbeiten muss.)
    let effStatus = status;
    if (!effDatumVon && effStatus === DEPLOYMENT_STATUS.GEPLANT) effStatus = DEPLOYMENT_STATUS.UNGEPLANT;

    const payload = {
      titel: finalTitel,
      datum_von: effDatumVon,
      datum_bis: effDatumBis,
      uhrzeit_von: uhrzeit_von || null,
      uhrzeit_bis: uhrzeit_bis || null,
      status: effStatus,
      company_id, contact_id, project_id, service_id,
      menge, einzelpreis,
      rabatt_typ,         // v2.28.2
      rabatt_wert,        // v2.28.2
      ort: ort || null,
      beschreibung: finalBeschreibung || null,
      dokumentation,
      externe_techniker: externe_techniker || null
    };
    if (!editingDeploymentId) payload.erstellt_von = currentUser?.id || null;

    // v2.12.2: Override-Schutz für Bündel-Mitglieder. Wenn der Einsatz an einem
    // Bündel hängt, vergleichen wir jeden shared Feld-Wert mit dem aktuellen
    // Bündel-Wert. Felder, die abweichen, kommen ins bundle_overrides-Array
    // und werden bei der nächsten Bündel-Speicherung NICHT mehr überschrieben.
    // Felder, die wieder mit dem Bündel übereinstimmen, fliegen aus dem Array
    // raus → die Standard-Propagation greift wieder.
    if (editingDeploymentId && _existingDeploymentBundleId) {
      const { data: bundleRow } = await db.from('deployment_bundles')
        .select('titel, service_id, einzelpreis, ort, externe_techniker, beschreibung, dokumentation')
        .eq('id', _existingDeploymentBundleId).single();
      if (bundleRow) {
        const sharedKeys = ['titel', 'service_id', 'einzelpreis', 'ort', 'externe_techniker', 'beschreibung', 'dokumentation'];
        const overrides = [];
        for (const k of sharedKeys) {
          const a = payload[k] ?? null;
          const b = bundleRow[k] ?? null;
          const same = (typeof a === 'object' || typeof b === 'object')
            ? JSON.stringify(a || {}) === JSON.stringify(b || {})
            : a === b;
          if (!same) overrides.push(k);
        }
        payload.bundle_overrides = overrides;
      }
    }

    let saved;
    if (editingDeploymentId) {
      const { data, error } = await db.from('deployments').update(payload).eq('id', editingDeploymentId).select().single();
      if (error) throw new Error(error.message);
      saved = data;
    } else {
      const { data, error } = await db.from('deployments').insert(payload).select().single();
      if (error) throw new Error(error.message);
      saved = data;
    }

    // v2.32.11: Themen aus dem Composer-Picker als deployment_themes-Junction
    // schreiben, sobald der Einsatz angelegt ist. Pending-Set kommt vom
    // Inline-Composer (_composerToggleThema / _composerAddThemaAdHoc).
    if (typeof _pendingComposerThemenIds !== 'undefined' && _pendingComposerThemenIds.size > 0) {
      // Erst alte Junctions weg (für den Edit-Fall idempotent), dann neu schreiben
      await db.from('deployment_themes').delete().eq('deployment_id', saved.id);
      const themeRows = [..._pendingComposerThemenIds].map(tid => ({ deployment_id: saved.id, theme_id: tid }));
      const { error: tErr } = await db.from('deployment_themes').insert(themeRows);
      if (tErr) console.warn('Composer deployment_themes insert:', tErr.message);
      _pendingComposerThemenIds = new Set();  // reset nach Save
    }

    // ──────── Techniker-Relations synchronisieren ────────
    // Zuerst alle existierenden löschen, dann neu anlegen (simpler als Diff)
    await db.from('deployment_technicians').delete().eq('deployment_id', saved.id);
    if (selectedTechnikerIds.size > 0) {
      const techRows = [...selectedTechnikerIds].map(uid => ({ deployment_id: saved.id, user_id: uid }));
      const { error: techErr } = await db.from('deployment_technicians').insert(techRows);
      if (techErr) {
        console.warn('Techniker konnten nicht gespeichert werden:', techErr.message);
        showToast('Einsatz gespeichert, Techniker-Zuordnung fehlgeschlagen.', true);
      }
    }

    // ──────── v1.53.0: Themen-Zuordnung syncen ────────
    try {
      await syncDeploymentThemes(saved.id);
    } catch (e) {
      console.warn('Themen-Zuordnung konnte nicht synchronisiert werden:', e.message);
    }

    // ──────── Termin-Kopplung ────────
    await syncDeploymentAppointment(saved, createAppointment);

    // ──────── Entitlement-Einlösung (v1.14.0) ────────
    try {
      await syncDeploymentRedemption(saved.id);
    } catch (redeemErr) {
      // Einsatz ist bereits gespeichert - Redemption-Fehler als Warnung zeigen, nicht abbrechen
      showToast('Einsatz gespeichert, aber: ' + redeemErr.message, true);
    }

    closeDeploymentModal();
    showToast(editingDeploymentId ? 'Einsatz aktualisiert.' : 'Einsatz angelegt.');

    // Auto-Projekt-Status-Check wenn Einsatz an Projekt gebunden
    if (saved.project_id) {
      await checkAndUpdateProjectStatus(saved.project_id);
    }
    // v2.33.16 (Phase A.1 #6): bei Projekt-Wechsel/Entkopplung auch das ALTE
    // Projekt nachrechnen — sonst bleibt es im veralteten Auto-Status hängen.
    if (_oldProjectId && _oldProjectId !== saved.project_id) {
      await checkAndUpdateProjectStatus(_oldProjectId);
    }

    // Kontext-sensibles Refresh
    if (currentProjectDetailId && document.getElementById('page-project-detail').classList.contains('active')) {
      await loadProjectDetail(currentProjectDetailId);
    } else if (currentCompanyDetailId && document.getElementById('page-company-detail').classList.contains('active')) {
      await loadCompanyDeployments(currentCompanyDetailId);
      // Memberships-Section neu rendern, damit Fortschritt aktualisiert wird
      await renderCompanyMemberships(currentCompanyDetailId);
    } else {
      await loadDeployments();
    }
    refreshCalendarBar();  // v1.32
  } catch (e) {
    showToast(e.message, true);
  } finally {
    btn.disabled = false;
    btn.textContent = editingDeploymentId ? 'Speichern' : 'Anlegen';
    // v2.33.7: Race-Guard freigeben + Sicherheitsnetz-Timeout abbrechen.
    clearTimeout(_saveDepReleaseT);
    btn.dataset.busy = '0';
  }
}

/**
 * Synchronisiert einen Termin zum Einsatz basierend auf Checkbox-Status.
 * Semantik (v1.9.4): Checkbox=Termin-Existenz, keine halben Sachen.
 * - Checkbox an + kein Termin          → neuen Termin anlegen
 * - Checkbox an + Termin existiert     → Termin updaten
 * - Checkbox aus + Termin existiert    → Termin LÖSCHEN (verhindert Duplikate)
 * - Checkbox aus + kein Termin         → nichts tun
 * - Kein Datum am Einsatz              → existierenden Termin löschen (Termin braucht Datum)
 */
async function syncDeploymentAppointment(deployment, shouldHaveAppointment) {
  // v2.33.16 (Phase A.4 #15): genau EINE Termin-Zeile pro deployment_id halten —
  // inklusive bereits soft-gelöschter. Vorher filterte der Lookup auf
  // `deleted_at IS NULL` und legte beim Wieder-Anhaken eine NEUE Zeile an,
  // während die alte soft-gelöscht liegen blieb; ein Undo der alten konnte dann
  // zwei aktive Termine auf demselben Einsatz erzeugen. Jetzt wird die
  // vorhandene (ggf. soft-gelöschte) Zeile reaktiviert/aktualisiert statt neu
  // eingefügt. nullsFirst priorisiert eine noch aktive Zeile, falls (durch den
  // alten Bug) mehrere existieren.
  const { data: existing } = await db.from('appointments')
    .select('id, deleted_at').eq('deployment_id', deployment.id)
    .order('deleted_at', { nullsFirst: true }).limit(1);
  const existingId      = existing?.[0]?.id || null;
  const existingDeleted = !!existing?.[0]?.deleted_at;

  // Ohne Datum kann kein Termin angelegt werden (Termine brauchen Datum)
  if (!deployment.datum_von) {
    if (existingId && !existingDeleted) {
      await db.from('appointments').update({ deleted_at: new Date().toISOString() }).eq('id', existingId);
    }
    if (shouldHaveAppointment) {
      showToast('Termin-Kopplung benötigt ein Datum. Bitte Datum setzen und erneut speichern.', true);
    }
    return;
  }

  if (!shouldHaveAppointment) {
    if (existingId && !existingDeleted) {
      // Soft-löschen — die Zeile bleibt für spätere Reaktivierung erhalten
      await db.from('appointments').update({ deleted_at: new Date().toISOString() }).eq('id', existingId);
    }
    return;
  }

  // Default-Termintyp: "Vor Ort" suchen, sonst erster aktiver
  await loadTerminTypen();
  const typVorOrt = terminTypenCache.find(t => /vor[- ]?ort/i.test(t.wert)) || terminTypenCache[0];
  const typ_id = typVorOrt?.id || null;

  // Terminstatus: Geplant → 'geplant', sonst 'durchgefuehrt'
  const terminStatus = deployment.status === DEPLOYMENT_STATUS.GEPLANT ? 'geplant' : 'durchgefuehrt';

  const payload = {
    titel: deployment.titel,
    datum: deployment.datum_von,
    uhrzeit_von: deployment.uhrzeit_von,
    uhrzeit_bis: deployment.uhrzeit_bis,
    status: terminStatus,
    company_id: deployment.company_id,
    project_id: deployment.project_id,
    ort: deployment.ort,
    notizen: deployment.notizen ? `[Einsatz-Termin]\n${esc(deployment.notizen)}` : '[Einsatz-Termin]',
    typ_id,
    deployment_id: deployment.id
  };

  if (existingId) {
    // Vorhandene (ggf. soft-gelöschte) Zeile reaktivieren + aktualisieren
    payload.deleted_at = null;
    await db.from('appointments').update(payload).eq('id', existingId);
  } else {
    payload.erstellt_von = currentUser?.id || null;
    await db.from('appointments').insert(payload);
  }
  // v2.33.10: Termin-Map invalidieren — der gekoppelte Termin würde sonst
  // erst nach loadAppointments im `companyAppointmentMap` sichtbar
  // (Phase A.4 #13). Nächster Firmen-Listen-Besuch baut sie frisch auf.
  invalidateAppointmentMaps();
}

// v2.33.17 (Phase A.1 #5): Quick-Status-Wechsel eines Einsatzes (Checkbox-Toggle
// auf der Projekt-Detailseite, Hero-Buttons, Status-Pille) auf den gekoppelten
// Termin spiegeln. Bisher tat das nur der Modal-Save via syncDeploymentAppointment;
// per Quick-Toggle blieb der Termin auf „Geplant", während der Einsatz schon
// „Durchgeführt" war (sichtbar inkonsistent in Termin-Liste/Kalender). Mapping
// wie in syncDeploymentAppointment: durchgeführt/abgerechnet → 'durchgefuehrt',
// sonst → 'geplant'. Trifft nur einen aktiven gekoppelten Termin; gibt es keinen,
// matcht das UPDATE 0 Zeilen (No-op). Best-effort — ein Fehler hier soll den
// bereits persistierten Einsatz-Statuswechsel nicht zurückrollen.
async function syncCoupledAppointmentStatus(deploymentId, deploymentStatus) {
  const terminStatus = (deploymentStatus === DEPLOYMENT_STATUS.DURCHGEFUEHRT
                     || deploymentStatus === DEPLOYMENT_STATUS.ABGERECHNET)
                     ? 'durchgefuehrt' : 'geplant';
  await db.from('appointments')
    .update({ status: terminStatus })
    .eq('deployment_id', deploymentId)
    .is('deleted_at', null);
}

// ═══════════════════════════════════════════════════════════
//  ENTITLEMENT-EINLÖSUNG IM EINSATZ-MODAL (v1.14.0)
// ═══════════════════════════════════════════════════════════

/**
 * Lädt offene Entitlements der gewählten Firma und befüllt das Dropdown.
 * Wird bei Firmenwechsel und beim Modal-Open aufgerufen.
 */
async function refreshRedeemSection() {
  const companyId = getCompanyComboboxId('d-company', 'd-company-list');
  const wrap = document.getElementById('d-redeem-wrap');
  const select = document.getElementById('d-redeem-entitlement');
  const check = document.getElementById('d-redeem-check');
  const hint = document.getElementById('d-redeem-hint');

  // Ohne Firma: Section verstecken
  if (!companyId) {
    wrap.style.display = 'none';
    check.checked = false;
    document.getElementById('d-redeem-details').style.display = 'none';
    return;
  }

  // Offene Entitlements der Firma laden (inkl. bereits-eingeloester Mengen).
  // v2.33.2: memberships.deleted_at mit selektieren, damit Bonis einer
  // soft-gelöschten Mitgliedschaft unten ausgefiltert werden können
  // (Cluster-7 / Phase A.4 #6 — Phantom-Boni-Bug).
  const { data: entitlements, error } = await db.from('entitlements')
    .select(`
      *,
      memberships(mitgliedsnummer, deleted_at, membership_programs(name)),
      projects(name)
    `)
    .eq('company_id', companyId)
    .order('verfall_datum', { ascending: true, nullsFirst: false });

  if (error) {
    wrap.style.display = 'none';
    return;
  }

  // Für jedes Entitlement: wie viel ist bereits eingelöst?
  const entIds = (entitlements || []).map(e => e.id);
  let redemptionsByEnt = {};
  if (entIds.length > 0) {
    const { data: redemptions } = await db.from('entitlement_redemptions')
      .select('entitlement_id, menge_eingeloest, deployment_id')
      .in('entitlement_id', entIds);
    (redemptions || []).forEach(r => {
      // Bei Edit: die eigene bestehende Redemption bei der Rest-Berechnung NICHT abziehen
      // (damit man sie in einem Schritt anpassen kann)
      if (editingDeploymentId && r.deployment_id === editingDeploymentId) return;
      redemptionsByEnt[r.entitlement_id] = (redemptionsByEnt[r.entitlement_id] || 0) + Number(r.menge_eingeloest || 0);
    });
  }

  // Nur Entitlements mit offener Menge > 0 ODER bereits verknüpfte bestehende Redemption anzeigen.
  // v2.33.2: zusätzlich Entitlements einer soft-gelöschten Mitgliedschaft ausblenden —
  // sie tauchten sonst als Phantom-Boni weiter im Picker auf und waren buchbar.
  // Projekt-Entitlements (memberships === null) bleiben unangetastet.
  const offen = (entitlements || []).filter(e => {
    if (e.memberships && e.memberships.deleted_at) return false;
    const rest = Number(e.gesamt_menge) - (redemptionsByEnt[e.id] || 0);
    const istAktuelleRedemption = window._pendingRedemptionEntitlementId === e.id;
    return rest > 0 || istAktuelleRedemption;
  });

  if (offen.length === 0) {
    wrap.style.display = 'block';
    check.checked = false;
    check.disabled = true;
    document.getElementById('d-redeem-details').style.display = 'none';
    hint.textContent = 'Diese Firma hat aktuell keine offenen Bonis.';
    return;
  }

  hint.textContent = 'Wähle einen offenen Bonus aus den Mitgliedschaften/Projekten dieser Firma.';
  check.disabled = false;
  wrap.style.display = 'block';

  // Dropdown befüllen
  select.innerHTML = offen.map(e => {
    const rest = Number(e.gesamt_menge) - (redemptionsByEnt[e.id] || 0);
    const quelle = e.memberships
      ? `Mitgliedschaft: ${esc(e.memberships.membership_programs?.name || '?')}`
      : e.projects
        ? `Projekt: ${esc(e.projects.name)}`
        : 'Manuell';
    const verfallInfo = e.verfall_datum ? ` · bis ${formatDateDE(e.verfall_datum)}` : '';
    return `<option value="${esc(e.id)}" data-rest="${rest}" data-gesamt="${e.gesamt_menge}">
      ${esc(e.titel)} (${rest} offen${verfallInfo}) — ${esc(quelle)}
    </option>`;
  }).join('');

  // Bei Edit-Mode: bestehende Redemption wieder anwenden
  if (window._pendingRedemptionEntitlementId) {
    check.checked = true;
    select.value = window._pendingRedemptionEntitlementId;
    document.getElementById('d-redeem-menge').value = window._pendingRedemptionMenge || 1;
    document.getElementById('d-redeem-details').style.display = 'block';
    onRedeemEntitlementChange();
    // Nach Anwendung löschen, damit nicht erneut angewandt wird
    window._pendingRedemptionEntitlementId = null;
    window._pendingRedemptionMenge = null;
  } else if (check.checked) {
    onRedeemEntitlementChange();
  }
}

/** Togglet den Details-Bereich beim Klick auf die Haupt-Checkbox. */
function onRedeemCheckToggle() {
  const check = document.getElementById('d-redeem-check');
  const details = document.getElementById('d-redeem-details');
  if (check.checked) {
    details.style.display = 'block';
    onRedeemEntitlementChange();
  } else {
    details.style.display = 'none';
  }
}

/** Aktualisiert den Mengen-Hinweis bei Entitlement-Auswahl. */
function onRedeemEntitlementChange() {
  const select = document.getElementById('d-redeem-entitlement');
  const mengeInput = document.getElementById('d-redeem-menge');
  const mengeHint = document.getElementById('d-redeem-menge-hint');
  const opt = select.options[select.selectedIndex];
  if (!opt) { mengeHint.textContent = ''; return; }

  const rest = Number(opt.getAttribute('data-rest') || 0);
  const gesamt = Number(opt.getAttribute('data-gesamt') || 0);
  mengeInput.max = rest;
  mengeHint.textContent = `Maximal ${rest} von ${gesamt} verbleibend.`;

  // Bei Einzel-Bonis (gesamt=1) Menge auf 1 fixieren
  if (gesamt === 1) {
    mengeInput.value = 1;
    mengeInput.readOnly = true;
    mengeHint.textContent = 'Einzel-Bonus: wird vollständig eingelöst.';
  } else {
    mengeInput.readOnly = false;
    if (Number(mengeInput.value) > rest) mengeInput.value = rest;
  }
}

/**
 * Schreibt oder aktualisiert die Redemption für einen Einsatz.
 * Wird aus saveDeployment aufgerufen nach erfolgreichem Speichern.
 */
async function syncDeploymentRedemption(deploymentId) {
  const wantRedeem = document.getElementById('d-redeem-check').checked;
  const entitlementId = document.getElementById('d-redeem-entitlement').value;
  const mengeRaw = document.getElementById('d-redeem-menge').value;
  const menge = Number(mengeRaw);

  // Bestehende Redemption für diesen Einsatz holen
  const { data: existing } = await db.from('entitlement_redemptions')
    .select('id, entitlement_id')
    .eq('deployment_id', deploymentId).limit(1);
  const existingRedemption = existing && existing.length > 0 ? existing[0] : null;

  // Fall A: Soll gelöscht werden (Checkbox aus, aber Redemption existiert)
  if (!wantRedeem) {
    if (existingRedemption) {
      await db.from('entitlement_redemptions').delete().eq('id', existingRedemption.id);
    }
    return;
  }

  // Validierung
  if (!entitlementId) throw new Error('Bitte einen Bonus auswählen oder die Einlöse-Checkbox deaktivieren.');
  if (!menge || menge <= 0) throw new Error('Einlöse-Menge muss > 0 sein.');

  const payload = {
    entitlement_id: entitlementId,
    deployment_id: deploymentId,
    menge_eingeloest: menge,
    // v2.33.4: toISODate gegen Vortag-Bug (UTC-Versatz).
    einloesung_datum: toISODate(new Date()),
    erstellt_von: currentProfile?.id || null
  };

  if (existingRedemption) {
    // Update (bei Entitlement-Wechsel: erst löschen, dann neu)
    if (existingRedemption.entitlement_id !== entitlementId) {
      await db.from('entitlement_redemptions').delete().eq('id', existingRedemption.id);
      const { error } = await db.from('entitlement_redemptions').insert(payload);
      if (error) throw new Error('Einlösung konnte nicht gespeichert werden: ' + error.message);
    } else {
      const { error } = await db.from('entitlement_redemptions')
        .update({ menge_eingeloest: menge })
        .eq('id', existingRedemption.id);
      if (error) throw new Error('Einlösung konnte nicht aktualisiert werden: ' + error.message);
    }
  } else {
    const { error } = await db.from('entitlement_redemptions').insert(payload);
    if (error) throw new Error('Einlösung konnte nicht gespeichert werden: ' + error.message);
  }
}

async function deleteDeployment() {
  if (!editingDeploymentId) return;
  const id = editingDeploymentId;

  // Prüfen, ob Redemptions existieren (für die Warnung im Confirm)
  const { data: existingReds } = await db.from('entitlement_redemptions')
    .select('id').eq('deployment_id', id);
  const hasRedemptions = (existingReds || []).length > 0;

  const ok = await confirmDialog({
    title: 'Einsatz löschen?',
    message: hasRedemptions
      ? 'Der Einsatz wird ausgeblendet. Verknüpfte Termine werden mit-ausgeblendet und sind über die Rückgängig-Aktion wieder erreichbar.<br><br><strong>Bonus-Einlösungen werden hart gelöscht</strong> und können nicht über Rückgängig wiederhergestellt werden.'
      : 'Der Einsatz und der gekoppelte Termin werden ausgeblendet. Rückgängig-Link erscheint 5 Sekunden lang.',
    confirmLabel: 'Löschen', cancelLabel: 'Abbrechen', danger: true
  });
  if (!ok) return;

  try {
    // project_id + company_id vorher merken für Status-Check nach Löschung
    const { data: depInfo } = await db.from('deployments')
      .select('project_id, company_id').is('deleted_at', null).eq('id', id).single();
    const affectedProjectId = depInfo?.project_id || null;
    const affectedCompanyId = depInfo?.company_id || null;

    // Gekoppelte Termine erst: IDs merken + soft-delete
    const { data: appts } = await db.from('appointments').select('id').is('deleted_at', null).eq('deployment_id', id);
    const coupledApptIds = (appts || []).map(a => a.id);
    const deletedAt = new Date().toISOString();
    if (coupledApptIds.length) {
      await db.from('appointments').update({ deleted_at: deletedAt }).eq('deployment_id', id);
    }

    // Zugehörige Redemptions hart löschen (v1.14.0) — NICHT über Undo wiederherstellbar
    await db.from('entitlement_redemptions').delete().eq('deployment_id', id);

    const { error } = await db.from('deployments').update({ deleted_at: deletedAt }).eq('id', id);
    if (error) throw new Error(error.message);

    closeDeploymentModal();

    if (affectedProjectId) await checkAndUpdateProjectStatus(affectedProjectId);
    await _refreshDeploymentContext(affectedCompanyId);

    showToast('Einsatz gelöscht.', false, {
      actionLabel: 'Rückgängig',
      durationMs: 5000,
      onAction: async () => {
        try {
          await db.from('deployments').update({ deleted_at: null }).eq('id', id);
          if (coupledApptIds.length) {
            await db.from('appointments').update({ deleted_at: null }).in('id', coupledApptIds);
          }
          if (affectedProjectId) await checkAndUpdateProjectStatus(affectedProjectId);
          await _refreshDeploymentContext(affectedCompanyId);
          showToast(hasRedemptions
            ? 'Einsatz wiederhergestellt (Bonus-Einlösungen bleiben gelöscht).'
            : 'Einsatz wiederhergestellt.');
        } catch (err) {
          showToast('Wiederherstellen fehlgeschlagen: ' + err.message, true);
        }
      }
    });
  } catch (e) {
    showToast(e.message, true);
  }
}

async function _refreshDeploymentContext(companyId) {
  if (currentProjectDetailId && document.getElementById('page-project-detail').classList.contains('active')) {
    await loadProjectDetail(currentProjectDetailId);
  } else if (currentCompanyDetailId && document.getElementById('page-company-detail').classList.contains('active')) {
    await loadCompanyDeployments(currentCompanyDetailId);
    if (companyId) await renderCompanyMemberships(companyId);
  } else {
    await loadDeployments();
  }
}

// ═══════════════════════════════════════════════════════════
//  EINSÄTZE AUF FIRMA-DETAIL
// ═══════════════════════════════════════════════════════════

async function loadCompanyDeployments(companyId) {
  closeExpandedRow();
  const tbody = document.getElementById('company-deployments-body');
  const countEl = document.getElementById('company-deployments-count');
  // v2.7.4: visible-Body immer mit-aktualisieren — sonst bleibt "Lade Einsätze ..."
  // bei 0-Treffer oder Error stehen
  const visTbody = document.getElementById('company-deployments-body-visible');
  const visCountEl = document.getElementById('company-deployments-count-visible');
  const visEmpty = (msg) => {
    if (visTbody) visTbody.innerHTML = `<tr><td colspan="7"><div class="empty">${msg}</div></td></tr>`;
  };

  await loadEinsatzStatus();

  const { data, error } = await db.from('deployments')
    .select('*, project:projects(id, name), service:services(id, name)').is('deleted_at', null)
    .eq('company_id', companyId)
    .order('datum_von', { ascending: false, nullsFirst: false })
    .order('created_at', { ascending: false });
  if (!isStillOnDetail('company', companyId)) return;  // v2.0.6: race-guard

  if (error) {
    tbody.innerHTML = `<tr><td colspan="6"><div class="empty">Fehler: ${esc(error.message)}</div></td></tr>`;
    countEl.textContent = 'Einsätze';
    if (visCountEl) visCountEl.textContent = 'Einsätze';
    visEmpty(`Fehler: ${esc(error.message)}`);
    return;
  }

  const all = data || [];
  const total = all.length;
  setTabCount('company', 'einsaetze', total);

  if (total === 0) {
    countEl.textContent = 'Keine Einsätze';
    tbody.innerHTML = '<tr><td colspan="6"><div class="empty">Noch keine Einsätze für diese Firma. Klicke oben auf „+ Einsatz hinzufügen".</div></td></tr>';
    if (visCountEl) visCountEl.textContent = 'Keine Einsätze';
    visEmpty('Noch keine Einsätze für diese Firma. Klicke oben auf „+ Einsatz hinzufügen".');
    return;
  }

  const umsatz = all
    .filter(d => !d.project_id && [DEPLOYMENT_STATUS.DURCHGEFUEHRT, DEPLOYMENT_STATUS.ABGERECHNET].includes(d.status))
    .reduce((sum, d) => sum + calcDeploymentNetto(d), 0);

  countEl.textContent = `${total} Einsatz${total === 1 ? '' : 'e'}`
    + (umsatz > 0 ? ` · ${formatPreis(umsatz)} direkt abrechenbar` : '');

  tbody.innerHTML = all.map(d => {
    const statusColor = einsatzStatusFarbe(d.status);
    const projektHtml = d.project
      ? `<div class="cell-link" onclick="navigateTo('projekt', '${esc(d.project.id)}')">${esc(d.project.name)}</div>`
      : '<span style="color:var(--muted);font-style:italic">Einzelbuchung</span>';
    const brutto = calcDeploymentGesamt(d.menge, d.einzelpreis);
    const { rabatt, netto } = applyRabatt(brutto, d.rabatt_typ, d.rabatt_wert);
    const rabattLine = rabatt > 0
      ? `<div style="font-size:11px;color:var(--status-overdue-accent);margin-top:2px">${d.rabatt_typ === 'prozent' ? `Rabatt ${formatMenge(d.rabatt_wert)} % (−${formatPreis(rabatt)})` : `Rabatt −${formatPreis(rabatt)}`}</div>`
      : '';

    return `
      <tr data-dep-id="${esc(d.id)}" data-company-id="${esc(d.company_id || '')}" data-project-id="${esc(d.project_id || '')}">
        <td>${renderDeploymentDateCell(d.datum_von, d.datum_bis)}</td>
        <td>
          <div class="cell-link" onclick="toggleRowExpand('deployment','${esc(d.id)}',this.closest('tr'))">${esc(d.titel || '—')}${d.datum_von ? ROW_CAL_ICON : ''}</div>
        </td>
        <td class="col-tablet">${projektHtml}</td>
        <td><span class="badge" style="background:${esc(statusColor)}22;color:${esc(statusColor)}">${esc(dispStatus(d.status))}</span></td>
        <td class="col-desktop">${esc(formatPreis(netto))}${rabattLine}</td>
        <td class="col-action" style="text-align:right">
          <button class="btn btn-sm" onclick="openDeploymentModal('edit', '${esc(d.id)}')">Bearbeiten</button>
        </td>
      </tr>`;
  }).join('');

  // Auto-Expand wenn genau ein Einsatz (v1.28)
  autoExpandSingleRow(tbody, 'deployment', all);

  // v2.7.3/4/5: zusätzlich den neuen sichtbaren Tab-Body rendern.
  // Variablen `visTbody` und `visCountEl` sind oben in der Funktion deklariert
  // — hier nicht erneut deklarieren (sonst SyntaxError "already declared",
  // bricht das ganze Script-Loading).
  if (visTbody) {
    if (visCountEl) visCountEl.textContent = `${total} Einsatz${total === 1 ? '' : 'e'}`
      + (umsatz > 0 ? ` · ${formatPreis(umsatz)} direkt abrechenbar` : '');
    visTbody.innerHTML = all.map(d => {
      const statusColor = einsatzStatusFarbe(d.status);
      const projektHtml = d.project
        ? `<span class="cell-link" onclick="navigateTo('projekt', '${esc(d.project.id)}')">${esc(d.project.name)}</span>`
        : '<span class="muted">Direktverkauf</span>';
      const brutto = calcDeploymentGesamt(d.menge, d.einzelpreis);
      const { rabatt, netto } = applyRabatt(brutto, d.rabatt_typ, d.rabatt_wert);
      const rabattLine = rabatt > 0
        ? `<div style="font-size:11px;color:var(--status-overdue-accent);margin-top:2px">${d.rabatt_typ === 'prozent' ? `Rabatt ${formatMenge(d.rabatt_wert)} % (−${formatPreis(rabatt)})` : `Rabatt −${formatPreis(rabatt)}`}</div>`
        : '';
      return `
        <tr>
          <td><span class="cell-link" onclick="navigateTo('einsatz','${esc(d.id)}')">${esc(d.titel || '—')}</span></td>
          <td class="col-tablet">${renderDeploymentDateCell(d.datum_von, d.datum_bis)}</td>
          <td class="col-tablet">${esc(d.service?.name || '—')}</td>
          <td class="col-desktop">${projektHtml}</td>
          <td><span class="badge" style="background:${esc(statusColor)}22;color:${esc(statusColor)}">${esc(dispStatus(d.status))}</span></td>
          <td>${esc(formatPreis(netto))}${rabattLine}</td>
          <td class="col-action" style="text-align:right">
            <button class="btn btn-sm" onclick="openDeploymentModal('edit','${esc(d.id)}')">Bearbeiten</button>
          </td>
        </tr>`;
    }).join('');
  }
}

// ═══════════════════════════════════════════════════════════
//  EINSÄTZE AUF PROJEKT-DETAIL
// ═══════════════════════════════════════════════════════════

async function loadProjectDeployments(projectId) {
  closeExpandedRow();
  const tbody = document.getElementById('project-deployments-body');
  const countEl = document.getElementById('project-deployments-count');
  const summaryEl = document.getElementById('project-deployments-summary');
  const leistungsUmsatzEl = document.getElementById('project-detail-leistungsumsatz');

  await loadEinsatzStatus();

  // v2.12.0: Bündel + zugehörige Einsätze parallel laden.
  const [depsRes, bundlesRes] = await Promise.all([
    db.from('deployments')
      .select('*, service:services(id, name)').is('deleted_at', null)
      .eq('project_id', projectId)
      .order('datum_von', { ascending: true, nullsFirst: false })
      .order('created_at', { ascending: true }),
    db.from('deployment_bundles')
      .select('id, titel').is('deleted_at', null).eq('project_id', projectId)
      .order('created_at', { ascending: true })
  ]);
  if (!isStillOnDetail('project', projectId)) return;  // v2.0.6: race-guard

  if (depsRes.error) {
    tbody.innerHTML = `<tr><td colspan="7"><div class="empty">Fehler: ${esc(depsRes.error.message)}</div></td></tr>`;
    countEl.textContent = 'Einsätze';
    summaryEl.style.display = 'none';
    if (leistungsUmsatzEl) leistungsUmsatzEl.textContent = '—';
    return;
  }

  const all = depsRes.data || [];
  const bundles = bundlesRes.data || [];
  _projectBundlesCache = bundles;
  const total = all.length;
  setTabCount('project', 'einsaetze', total);

  // v2.25.11: Stornierte Einsätze fließen NICHT in Aufwand/Leistungsumsatz.
  // Sie bleiben in der Tabelle sichtbar (durchgestrichen als Storniert-Badge),
  // werden aber für jede Summe konsequent ausgenommen.
  const billable = all.filter(d => d.status !== DEPLOYMENT_STATUS.STORNIERT);
  const stornoCount = all.length - billable.length;
  const stornoSum   = all.filter(d => d.status === DEPLOYMENT_STATUS.STORNIERT)
    .reduce((s, d) => s + calcDeploymentGesamt(d.menge, d.einzelpreis), 0);

  // Leistungsumsatz (Summe aller nicht-stornierten Einsatz-Werte) im Header
  // v2.28.2: Leistungsumsatz/-Aufwand mit Rabatt-Effekt (echter Kundenwert).
  const leistungsUmsatz = billable.reduce((s, d) => s + calcDeploymentNetto(d), 0);
  if (leistungsUmsatzEl) {
    leistungsUmsatzEl.textContent = formatPreis(leistungsUmsatz);
    leistungsUmsatzEl.style.color = leistungsUmsatz > 0 ? 'var(--text)' : 'var(--muted)';
  }

  if (total === 0 && bundles.length === 0) {
    countEl.textContent = 'Keine Einsätze';
    tbody.innerHTML = '<tr><td colspan="7"><div class="empty">Noch keine Einsätze für dieses Projekt. Klicke oben auf „+ Einsatz hinzufügen".</div></td></tr>';
    summaryEl.style.display = 'none';
    return;
  }

  const anzGeplant      = all.filter(d => d.status === DEPLOYMENT_STATUS.GEPLANT).length;
  const anzDurchgefuehrt = all.filter(d => d.status === DEPLOYMENT_STATUS.DURCHGEFUEHRT).length;
  const anzAbgerechnet  = all.filter(d => d.status === DEPLOYMENT_STATUS.ABGERECHNET).length;
  const anzStorniert    = all.filter(d => d.status === DEPLOYMENT_STATUS.STORNIERT).length;
  const anzUngeplant    = all.filter(d => !d.datum_von).length;
  const summeAufwand    = leistungsUmsatz;

  let countText = `${total} Einsatz${total === 1 ? '' : 'e'} · ${anzGeplant} geplant · ${anzDurchgefuehrt} durchgef. · ${anzAbgerechnet} abgerechnet`;
  if (anzStorniert > 0) countText += ` · ${anzStorniert} storniert`;
  if (anzUngeplant > 0) countText += ` · ${anzUngeplant} ohne Datum`;
  if (bundles.length > 0) countText += ` · ${bundles.length} Bündel`;
  countEl.textContent = countText;

  // v2.12.0: Zeile bauen — Helper, wird sowohl für ungebündelte als auch für
  // Bündel-Mitglieder genutzt. `isMember`-Flag setzt eine CSS-Klasse für die
  // Einrückung der Tage unter dem Bündel-Header.
  const renderRow = (d, isMember) => {
    const statusColor = einsatzStatusFarbe(d.status);
    const leistungHtml = d.service
      ? esc(d.service.name)
      : '<span style="color:var(--muted);font-style:italic">—</span>';
    const brutto = calcDeploymentGesamt(d.menge, d.einzelpreis);
    const { rabatt, netto } = applyRabatt(brutto, d.rabatt_typ, d.rabatt_wert);
    const rabattLine = rabatt > 0
      ? `<div style="font-size:11px;color:var(--status-overdue-accent);margin-top:2px">${d.rabatt_typ === 'prozent' ? `Rabatt ${formatMenge(d.rabatt_wert)} % (−${formatPreis(rabatt)})` : `Rabatt −${formatPreis(rabatt)}`}</div>`
      : '';
    const isDone = d.status === DEPLOYMENT_STATUS.DURCHGEFUEHRT || d.status === DEPLOYMENT_STATUS.ABGERECHNET;
    const isLocked = d.status === DEPLOYMENT_STATUS.ABGERECHNET || d.status === DEPLOYMENT_STATUS.STORNIERT;
    const checkboxTitle = isLocked
      ? `Status „${esc(dispStatus(d.status))}" kann nicht per Checkbox geändert werden`
      : (isDone ? 'Als nicht durchgeführt markieren' : 'Als durchgeführt markieren');
    return `
      <tr class="${isMember ? 'bundle-member-row' : ''}" data-dep-id="${esc(d.id)}" data-dep-status="${esc(d.status || '')}" data-company-id="${esc(d.company_id || '')}" data-project-id="${esc(d.project_id || '')}">
        <td style="text-align:center">
          <input type="checkbox" class="deployment-done-check"
                 ${isDone ? 'checked' : ''}
                 ${isLocked ? 'disabled' : ''}
                 onchange="toggleDeploymentDone('${esc(d.id)}', this.checked, this)"
                 title="${esc(checkboxTitle)}"
                 style="width:16px;height:16px;cursor:${isLocked ? 'not-allowed' : 'pointer'};margin:0">
        </td>
        <td>${renderDeploymentDateCell(d.datum_von, d.datum_bis)}</td>
        <td>
          <div class="cell-link" onclick="toggleRowExpand('deployment','${esc(d.id)}',this.closest('tr'))">${esc(d.titel || '—')}${d.datum_von ? ROW_CAL_ICON : ''}</div>
        </td>
        <td class="col-tablet" style="color:var(--muted)">${leistungHtml}</td>
        <td class="dep-status-cell"><span class="badge" style="background:${esc(statusColor)}22;color:${esc(statusColor)}">${esc(dispStatus(d.status))}</span></td>
        <td class="col-desktop">${esc(formatPreis(netto))}${rabattLine}</td>
        <td class="col-action" style="text-align:right">
          <button class="btn btn-sm" onclick="openDeploymentModal('edit', '${esc(d.id)}')">Bearbeiten</button>
        </td>
      </tr>`;
  };

  // v2.12.0: Bündel als Gruppe rendern — Header + Mitglieder-Zeilen.
  const ungebuendelt = all.filter(d => !d.bundle_id);
  const htmlParts = [];
  ungebuendelt.forEach(d => htmlParts.push(renderRow(d, false)));
  bundles.forEach(b => {
    const members = all.filter(d => d.bundle_id === b.id);
    if (members.length === 0) return;
    // v2.25.11: Bündel-Header zeigt nur die nicht-stornierten Werte und Tage.
    // Stornierte Mitglieder werden separat ausgewiesen, damit der User weiß,
    // dass das Bündel ursprünglich mehr Tage hatte.
    const billableMembers = members.filter(d => d.status !== DEPLOYMENT_STATUS.STORNIERT);
    const stornoMembers   = members.filter(d => d.status === DEPLOYMENT_STATUS.STORNIERT);
    // v2.28.2: Bündel-Summe mit Rabatt-Berücksichtigung
    const bundleSum = billableMembers.reduce((s, d) => s + calcDeploymentNetto(d), 0);
    const bundleStornoSum = stornoMembers.reduce((s, d) => s + calcDeploymentGesamt(d.menge, d.einzelpreis), 0);
    const dateLabels = members.filter(d => d.datum_von).map(d => formatDateDE(d.datum_von)).join(' · ');
    const collapsed = _collapsedBundleIds.has(b.id);
    const stornoHint = stornoMembers.length > 0
      ? ` · <span style="color:var(--status-overdue-accent)">${stornoMembers.length} storn. (${esc(formatPreis(bundleStornoSum))})</span>`
      : '';
    htmlParts.push(`
      <tr class="bundle-header-row${collapsed ? ' is-collapsed' : ''}" data-bundle-id="${esc(b.id)}" onclick="toggleBundleCollapse('${esc(b.id)}')">
        <td colspan="7" class="bundle-header-cell">
          <div class="bundle-header-cell-inner">
            <span class="bundle-header-chevron">▼</span>
            <span class="bundle-header-label">Bündel</span>
            <span class="bundle-header-title">${esc(b.titel)}</span>
            <span style="font-size:11px;color:var(--muted)">${esc(dateLabels)}</span>
            <span class="bundle-header-stats">${billableMembers.length} Tag${billableMembers.length === 1 ? '' : 'e'} · ${esc(formatPreis(bundleSum))}${stornoHint}</span>
            <button class="btn btn-sm" style="margin-left:8px" onclick="event.stopPropagation();openDeploymentBundleModal('edit','${esc(b.id)}')">Bündel bearbeiten</button>
          </div>
        </td>
      </tr>`);
    if (!collapsed) members.forEach(d => htmlParts.push(renderRow(d, true)));
  });

  tbody.innerHTML = htmlParts.join('') ||
    '<tr><td colspan="7"><div class="empty">Noch keine Einsätze für dieses Projekt.</div></td></tr>';

  // Summary mit Aufwands-Info — v2.25.11: Storniert wird separat ausgewiesen.
  summaryEl.style.display = '';
  const stornoHintHtml = stornoCount > 0
    ? ` <span style="color:var(--status-overdue-accent)">· ${stornoCount} storniert (${esc(formatPreis(stornoSum))} ignoriert)</span>`
    : '';
  summaryEl.innerHTML = `Interner Aufwand laut Einsatz-Preisen: <strong>${esc(formatPreis(summeAufwand))}</strong>${stornoHintHtml}. Kundenumsatz läuft über den Projekt-Paketpreis.`;

  // Auto-Expand wenn genau ein Einsatz (v1.28)
  autoExpandSingleRow(tbody, 'deployment', all);
}

// ═══════════════════════════════════════════════════════════
//  PROJEKT-PRODUKTE (v2.10.0 — Verkaufspositionen + Marge)
// ═══════════════════════════════════════════════════════════

let editingProjectProductId = null;

/** Lädt die Verkaufspositionen eines Projekts und rendert Tabelle + Summary.
 *  Stößt anschließend die Wirtschaftlichkeits-Summary an, damit die Marge-Karte
 *  mit Einsätzen + Produkten konsistent ist. */
async function loadProjectProducts(projectId) {
  const tbody = document.getElementById('project-products-body');
  const countEl = document.getElementById('project-products-count');
  const summaryEl = document.getElementById('project-products-summary');
  if (!tbody) return;

  const { data, error } = await db.from('project_products')
    .select('*, product:products(id, name, einheit)').is('deleted_at', null)
    .eq('project_id', projectId)
    .order('created_at', { ascending: true });
  if (!isStillOnDetail('project', projectId)) return;

  if (error) {
    tbody.innerHTML = `<tr><td colspan="7"><div class="empty">Fehler: ${esc(error.message)}</div></td></tr>`;
    if (countEl) countEl.textContent = 'Produkte und Verkäufe';
    if (summaryEl) summaryEl.style.display = 'none';
    return;
  }

  const all = data || [];
  const total = all.length;

  if (total === 0) {
    if (countEl) countEl.textContent = 'Keine Produkt-Positionen';
    tbody.innerHTML = '<tr><td colspan="7"><div class="empty">Noch keine Produkte erfasst. Klicke oben auf „+ Produkt hinzufügen", um Hardware oder andere Verkaufspositionen am Projekt zu führen.</div></td></tr>';
    if (summaryEl) summaryEl.style.display = 'none';
    loadProjectWirtschaftlichkeitSummary(projectId);
    return;
  }

  // v2.28.12: Rabatt fließt in die Erlös-Summe „außerhalb Paket". Für
  // Pakete-Positionen ist der Rabatt informativ und nicht erlöswirksam,
  // weil dort der Paketpreis maßgeblich ist.
  const sumVkExkl = all.filter(r => !r.im_paket)
    .reduce((s, r) => s + calcProductPositionNetto(r), 0);
  const sumEkAll = all.reduce((s, r) => s + (Number(r.menge) || 0) * (Number(r.einzelpreis_ek) || 0), 0);
  const sumEkPaket = all.filter(r => r.im_paket)
    .reduce((s, r) => s + (Number(r.menge) || 0) * (Number(r.einzelpreis_ek) || 0), 0);
  const anzPaket = all.filter(r => r.im_paket).length;
  const anzExkl  = total - anzPaket;

  if (countEl) {
    let countText = `${total} Position${total === 1 ? '' : 'en'}`;
    if (anzPaket > 0) countText += ` · ${anzPaket} im Paket`;
    if (anzExkl > 0)  countText += ` · ${anzExkl} zusätzlich`;
    countEl.textContent = countText;
  }

  tbody.innerHTML = all.map(r => {
    const menge = Number(r.menge) || 0;
    const vk = Number(r.einzelpreis_vk) || 0;
    const ek = Number(r.einzelpreis_ek) || 0;
    const einheit = r.product?.einheit ? ` ${esc(r.product.einheit)}` : '';
    const bruttoWert = menge * vk;
    // v2.28.12: bei zusätzlichen Positionen den Rabatt anwenden,
    // bei Paket-Positionen den Brutto-Wert behalten (Rabatt ist dort nicht wirksam).
    const { rabatt, netto } = applyRabatt(bruttoWert, r.rabatt_typ, r.rabatt_wert);
    const positionsWert = r.im_paket ? bruttoWert : netto;
    const showRabatt = !r.im_paket && rabatt > 0;
    let rabattLine = '';
    if (showRabatt) {
      const rabattLabel = r.rabatt_typ === 'prozent'
        ? `Rabatt ${formatMenge(r.rabatt_wert)} % (−${formatPreis(rabatt)})`
        : `Rabatt −${formatPreis(rabatt)}`;
      rabattLine = `<div style="font-size:11px;color:var(--status-overdue-accent);margin-top:2px">${rabattLabel}</div>`;
    }
    const paketBadge = r.im_paket
      ? '<span class="badge" style="background:#94a3b822;color:#475569">im Paket</span>'
      : '<span class="badge" style="background:#22c55e22;color:#16a34a">zusätzlich</span>';
    return `
      <tr data-pp-id="${esc(r.id)}">
        <td>
          <div class="cell-link" onclick="openProjectProductModal('edit','${esc(r.id)}')">${esc(r.bezeichnung || '—')}</div>
          ${r.notizen ? `<div style="font-size:11px;color:var(--muted);margin-top:2px">${esc(r.notizen)}</div>` : ''}
          ${rabattLine}
        </td>
        <td class="col-tablet">${esc(formatMenge(menge))}${einheit}</td>
        <td class="col-tablet">${esc(formatPreis(vk))}</td>
        <td class="col-desktop">${esc(formatPreis(ek))}</td>
        <td>${esc(formatPreis(positionsWert))}</td>
        <td>${paketBadge}</td>
        <td class="col-action" style="text-align:right">
          <button class="btn btn-sm" onclick="openProjectProductModal('edit','${esc(r.id)}')">Bearbeiten</button>
        </td>
      </tr>`;
  }).join('');

  if (summaryEl) {
    const parts = [];
    if (anzExkl > 0)  parts.push(`Zusätzlicher Verkauf (außerhalb Paket): <strong>${esc(formatPreis(sumVkExkl))}</strong>`);
    if (anzPaket > 0) parts.push(`EK im Paket: <strong>${esc(formatPreis(sumEkPaket))}</strong>`);
    parts.push(`EK gesamt: <strong>${esc(formatPreis(sumEkAll))}</strong>`);
    summaryEl.style.display = '';
    summaryEl.innerHTML = parts.join(' · ');
  }

  loadProjectWirtschaftlichkeitSummary(projectId);
}

/** Hilfs-Format für Mengen: nur Nachkommastellen anzeigen, wenn nötig. */
function formatMenge(menge) {
  const n = Number(menge) || 0;
  return Number.isInteger(n) ? String(n) : n.toLocaleString('de-DE', { maximumFractionDigits: 3 });
}

/** Aggregiert Paketpreis + Einsätze + Produkte zu einer Marge-Übersicht. */
async function loadProjectWirtschaftlichkeitSummary(projectId) {
  const el = document.getElementById('project-wirtschaftlichkeit-summary');
  if (!el) return;

  const [projRes, depRes, prodRes] = await Promise.all([
    // v2.28.9: preis_nach_aufwand-Flag mitlesen.
    db.from('projects').select('geschaetzter_umsatz, preis_nach_aufwand').is('deleted_at', null).eq('id', projectId).single(),
    // v2.25.11/v2.28.2: status + Rabatt mitlesen für korrekte Marge.
    db.from('deployments').select('menge, einzelpreis, status, rabatt_typ, rabatt_wert').is('deleted_at', null).eq('project_id', projectId),
    db.from('project_products').select('menge, einzelpreis_vk, einzelpreis_ek, im_paket, rabatt_typ, rabatt_wert').is('deleted_at', null).eq('project_id', projectId)
  ]);
  if (!isStillOnDetail('project', projectId)) return;

  const paket = Number(projRes.data?.geschaetzter_umsatz) || 0;
  const nachAufwand = !!projRes.data?.preis_nach_aufwand;
  // v2.25.11: Stornierte Einsätze sind nie ein Aufwand — sie entstehen nie.
  // v2.28.2: Rabatt wirkt mit (echter Rabatt → Marge sinkt).
  const einsatzSumme = (depRes.data || [])
    .filter(d => d.status !== DEPLOYMENT_STATUS.STORNIERT)
    .reduce((s, d) => s + calcDeploymentNetto(d), 0);
  const prods = prodRes.data || [];
  const produktUmsatzExkl = prods.filter(p => !p.im_paket)
    .reduce((s, p) => s + calcProductPositionNetto(p), 0);
  const produktEkGesamt = prods.reduce((s, p) => s + (Number(p.menge) || 0) * (Number(p.einzelpreis_ek) || 0), 0);

  // v2.28.9: Bei „Preis nach Aufwand" werden die Einsätze zu Erlösen statt
  // zu Aufwand — der Kunde zahlt sie ja direkt. Sonst (Festpreis-Projekt)
  // bleibt es wie bisher: Paketpreis = Erlös, Einsätze = interner Aufwand.
  const erloese = nachAufwand
    ? (einsatzSumme + produktUmsatzExkl)
    : (paket + produktUmsatzExkl);
  const aufwand = nachAufwand
    ? produktEkGesamt
    : (einsatzSumme + produktEkGesamt);
  const marge = erloese - aufwand;
  const margePct = erloese > 0 ? (marge / erloese * 100) : null;

  const margeColor = marge >= 0 ? 'var(--success)' : 'var(--danger)';
  const margeLabel = marge >= 0 ? 'Marge' : 'Überziehung';

  const row = (label, value, opts = {}) => {
    const color = opts.color || 'var(--text)';
    const weight = opts.bold ? '600' : '400';
    return `<div style="display:flex;justify-content:space-between;gap:16px;padding:2px 0">
              <span style="color:var(--muted)">${esc(label)}</span>
              <span style="color:${color};font-weight:${weight}">${esc(value)}</span>
            </div>`;
  };

  // v2.28.13: Render-Zeilen je nach Preis-Modus differenziert. Bei
  // „Preis nach Aufwand" sind Einsätze ein Erlös (Σ Einsätze), nicht ein
  // Aufwand. Variablenname `einsatzSumme` wurde in v2.28.11 umbenannt.
  const erloeseRows = nachAufwand
    ? `
        ${row('Summe Einsätze', formatPreis(einsatzSumme))}
        ${row('Zusätzliche Produkte (nicht im Paket)', formatPreis(produktUmsatzExkl))}
        ${row('Erlöse gesamt', formatPreis(erloese), { bold: true })}`
    : `
        ${row('Projekt-Paketpreis', formatPreis(paket))}
        ${row('Zusätzliche Produkte (nicht im Paket)', formatPreis(produktUmsatzExkl))}
        ${row('Erlöse gesamt', formatPreis(erloese), { bold: true })}`;

  const aufwandRows = nachAufwand
    ? `
        ${row('Produkt-Einkauf (Material)', formatPreis(produktEkGesamt))}
        ${row('Aufwand gesamt', formatPreis(aufwand), { bold: true })}`
    : `
        ${row('Interner Einsatz-Aufwand', formatPreis(einsatzSumme))}
        ${row('Produkt-Einkauf (alle Positionen)', formatPreis(produktEkGesamt))}
        ${row('Aufwand gesamt', formatPreis(aufwand), { bold: true })}`;

  el.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:24px">
      <div>
        <div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin-bottom:6px">Erlöse</div>
        ${erloeseRows}
      </div>
      <div>
        <div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin-bottom:6px">Aufwand</div>
        ${aufwandRows}
      </div>
    </div>
    <div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border);display:flex;justify-content:space-between;align-items:baseline">
      <span style="font-weight:600">${esc(margeLabel)}${margePct !== null ? ` (${margePct.toFixed(1)} %)` : ''}</span>
      <span style="color:${margeColor};font-weight:600;font-size:16px">${esc(formatPreis(Math.abs(marge)))}</span>
    </div>
  `;
}

/** Modal-Open für eine neue oder bestehende Verkaufsposition. */
async function openProjectProductModal(mode, id) {
  if (!currentProjectDetailId) {
    showToast('Kein Projekt aktiv.', true);
    return;
  }
  editingProjectProductId = (mode === 'edit') ? id : null;

  const titleEl = document.getElementById('modal-project-product-title');
  const deleteBtn = document.getElementById('pp-delete-btn');
  if (titleEl) titleEl.textContent = (mode === 'edit') ? 'Produkt bearbeiten' : 'Produkt hinzufügen';
  if (deleteBtn) deleteBtn.style.display = (mode === 'edit') ? '' : 'none';

  // Produkt-Dropdown füllen
  const sel = document.getElementById('pp-product');
  if (sel) {
    sel.innerHTML = '<option value="">— Produkt wählen —</option><option value="" disabled>Lade …</option>';
    const { data: products } = await db.from('products')
      .select('id, name, einheit, einkaufspreis, verkaufspreis, ist_aktiv').is('deleted_at', null)
      .order('name', { ascending: true });
    const opts = ['<option value="">— Produkt wählen —</option>'];
    (products || []).filter(p => p.ist_aktiv !== false).forEach(p => {
      opts.push(`<option value="${esc(p.id)}"
        data-name="${esc(p.name)}"
        data-einheit="${esc(p.einheit || 'Stk')}"
        data-ek="${esc(p.einkaufspreis ?? 0)}"
        data-vk="${esc(p.verkaufspreis ?? 0)}">${esc(p.name)}</option>`);
    });
    sel.innerHTML = opts.join('');
  }

  // Felder zurücksetzen
  document.getElementById('pp-bezeichnung').value = '';
  document.getElementById('pp-menge').value = 1;
  document.getElementById('pp-einheit').value = 'Stk';
  document.getElementById('pp-vk').value = 0;
  document.getElementById('pp-ek').value = 0;
  document.getElementById('pp-im-paket').checked = false;
  document.getElementById('pp-notizen').value = '';
  // v2.28.2: Rabatt zurücksetzen
  const ppRabattTyp = document.getElementById('pp-rabatt-typ');
  const ppRabattWert = document.getElementById('pp-rabatt-wert');
  if (ppRabattTyp) ppRabattTyp.value = '';
  if (ppRabattWert) { ppRabattWert.value = ''; ppRabattWert.disabled = true; }

  if (mode === 'edit') {
    const { data: row, error } = await db.from('project_products').select('*').eq('id', id).single();
    if (error || !row) {
      showToast('Position konnte nicht geladen werden.', true);
      return;
    }
    if (sel && row.product_id) sel.value = row.product_id;
    document.getElementById('pp-bezeichnung').value = row.bezeichnung || '';
    document.getElementById('pp-menge').value = row.menge ?? 1;
    document.getElementById('pp-vk').value = row.einzelpreis_vk ?? 0;
    document.getElementById('pp-ek').value = row.einzelpreis_ek ?? 0;
    document.getElementById('pp-im-paket').checked = !!row.im_paket;
    document.getElementById('pp-notizen').value = row.notizen || '';
    // v2.28.2: Rabatt aus DB lesen
    if (ppRabattTyp)  ppRabattTyp.value  = row.rabatt_typ || '';
    if (ppRabattWert) {
      ppRabattWert.value = row.rabatt_wert ?? '';
      ppRabattWert.disabled = !row.rabatt_typ;
    }
    // Einheit aus dem Produktoption übernehmen, falls vorhanden
    const opt = sel?.selectedOptions?.[0];
    if (opt?.dataset?.einheit) document.getElementById('pp-einheit').value = opt.dataset.einheit;
  }

  document.getElementById('modal-project-product').classList.add('open');
  setTimeout(() => document.getElementById('pp-product')?.focus(), 100);
}

function closeProjectProductModal() {
  document.getElementById('modal-project-product').classList.remove('open');
  editingProjectProductId = null;
}

/** Übernimmt Bezeichnung/Einheit/VK/EK aus dem gewählten Produktstammdatensatz. */
function onProjectProductSelect() {
  const sel = document.getElementById('pp-product');
  const opt = sel?.selectedOptions?.[0];
  if (!opt || !opt.value) return;
  document.getElementById('pp-bezeichnung').value = opt.dataset.name || '';
  document.getElementById('pp-einheit').value    = opt.dataset.einheit || 'Stk';
  document.getElementById('pp-vk').value         = opt.dataset.vk || 0;
  document.getElementById('pp-ek').value         = opt.dataset.ek || 0;
}

async function saveProjectProduct() {
  if (!currentProjectDetailId) return;

  const productId   = document.getElementById('pp-product').value || null;
  const bezeichnung = document.getElementById('pp-bezeichnung').value.trim();
  const menge       = Number(document.getElementById('pp-menge').value);
  const vk          = Number(document.getElementById('pp-vk').value);
  const ek          = Number(document.getElementById('pp-ek').value);
  const imPaket     = document.getElementById('pp-im-paket').checked;
  const notizen     = document.getElementById('pp-notizen').value.trim() || null;

  if (!bezeichnung) { showToast('Bezeichnung ist Pflicht.', true); return; }
  if (!(menge > 0)) { showToast('Menge muss größer als 0 sein.', true); return; }
  if (vk < 0 || ek < 0) { showToast('Preise dürfen nicht negativ sein.', true); return; }

  // v2.28.2: Rabatt einlesen + validieren
  const ppRabattTypRaw  = document.getElementById('pp-rabatt-typ')?.value || '';
  const ppRabattWertRaw = document.getElementById('pp-rabatt-wert')?.value || '';
  let rabatt_typ = null;
  let rabatt_wert = null;
  if (ppRabattTypRaw && ppRabattWertRaw !== '') {
    const wert = Number(ppRabattWertRaw);
    if (Number.isNaN(wert) || wert < 0) {
      showToast('Rabatt-Wert muss eine Zahl ≥ 0 sein.', true); return;
    }
    if (ppRabattTypRaw === 'prozent' && wert > 100) {
      showToast('Rabatt-Prozent kann nicht über 100 % liegen.', true); return;
    }
    rabatt_typ = ppRabattTypRaw;
    rabatt_wert = wert;
  }

  const payload = {
    project_id: currentProjectDetailId,
    product_id: productId,
    bezeichnung,
    menge,
    einzelpreis_vk: vk,
    einzelpreis_ek: ek,
    rabatt_typ,        // v2.28.2
    rabatt_wert,       // v2.28.2
    im_paket: imPaket,
    notizen
  };
  if (currentProfile?.id && !editingProjectProductId) payload.erstellt_von = currentProfile.id;

  try {
    if (editingProjectProductId) {
      const { error } = await db.from('project_products').update(payload).eq('id', editingProjectProductId);
      if (error) throw new Error(error.message);
    } else {
      const { error } = await db.from('project_products').insert(payload);
      if (error) throw new Error(error.message);
    }
    closeProjectProductModal();
    showToast(editingProjectProductId ? 'Position aktualisiert.' : 'Position angelegt.');
    await refreshProjectAfterFinanceChange(currentProjectDetailId);
  } catch (e) {
    showToast(e.message, true);
  }
}

async function deleteProjectProduct() {
  if (!editingProjectProductId) return;
  if (!confirm('Position wirklich löschen?')) return;
  try {
    const { error } = await db.from('project_products')
      .update({ deleted_at: new Date().toISOString() })
      .eq('id', editingProjectProductId);
    if (error) throw new Error(error.message);
    closeProjectProductModal();
    showToast('Position gelöscht.');
    if (currentProjectDetailId) await refreshProjectAfterFinanceChange(currentProjectDetailId);
  } catch (e) {
    showToast(e.message, true);
  }
}

/** Refresh nach Finanz-relevantem CRUD (Produkt-Position, Einsatz innerhalb des
 *  Projekts): aktualisiert Produkt-Liste + Wirtschaftlichkeits-Summary + Hero-
 *  Marge-Card, ohne das ganze Projekt neu zu rendern (kein Tab-Wechsel, kein
 *  Scroll-Reset). Stat-Card-Loader wird mit frischem Projekt-Datensatz erneut
 *  angestoßen — die Wirtschaftlichkeits-Summary darin holt sich Einsätze und
 *  Produkte selbst nach. */
async function refreshProjectAfterFinanceChange(projectId) {
  const { data: p } = await db.from('projects')
    .select('*, company:companies(id, name)')
    .is('deleted_at', null).eq('id', projectId).single();
  await Promise.all([
    loadProjectProducts(projectId),
    loadProjectDeployments(projectId),
    p ? loadProjectDashboard(p) : Promise.resolve()
  ]);
}

// ═══════════════════════════════════════════════════════════
//  v2.12.0 — EINSATZ-BÜNDEL (Mehrtages-Klammer)
//  Tabellen: deployment_bundles, deployment_bundle_technicians,
//  deployments.bundle_id + bundle_overrides
// ═══════════════════════════════════════════════════════════

let editingBundleId = null;
let selectedBundleTeamIds = new Set();
let _bundleDayRows = [];       // [{ id?, datum_von, uhrzeit_von, uhrzeit_bis, menge, status }]
let _bundleDeletedDayIds = []; // existierende Einsätze, die aus der Tage-Liste entfernt wurden

/** Öffnet das Bündel-Modal entweder leer (für ein neues Bündel) oder mit
 *  vorbefüllten Werten + Tagen aus einem bestehenden Bündel. Optional kann
 *  eine Liste vorhandener Deployment-IDs als Tage-Vorbefüllung übergeben
 *  werden — das ist der Konvertier-Flow „Auswahl bündeln". */
async function openDeploymentBundleModal(mode, bundleId = null, opts = {}) {
  if (!currentProjectDetailId) {
    showToast('Bündel können aktuell nur aus einem Projekt heraus angelegt werden.', true);
    return;
  }
  editingBundleId = (mode === 'edit') ? bundleId : null;

  // Caches sicherstellen
  await Promise.all([loadEinsatzStatus(), loadServicesCache(), loadUserProfilesCache()]);

  // Titel + Delete-Button
  document.getElementById('modal-deployment-bundle-title').textContent =
    (mode === 'edit') ? 'Einsatz-Bündel bearbeiten' : 'Neues Einsatz-Bündel';
  const deleteBtn = document.getElementById('b-delete-btn');
  if (deleteBtn) deleteBtn.style.display = (mode === 'edit') ? '' : 'none';

  // Service-Dropdown füllen (mit data-Attributen für Auto-Fill)
  const serviceSelect = document.getElementById('b-service');
  serviceSelect.innerHTML = '<option value="">— Keine Leistung —</option>'
    + servicesCache.map(s =>
        `<option value="${esc(s.id)}" data-preis="${s.standardpreis || 0}">${esc(s.name)} (${esc(s.einheit || '—')})</option>`
      ).join('');
  serviceSelect.onchange = onBundleServiceChange;

  // Felder zurücksetzen
  document.getElementById('b-titel').value = '';
  document.getElementById('b-einzelpreis').value = '';
  document.getElementById('b-ort').value = '';
  document.getElementById('b-beschreibung').value = '';
  document.getElementById('b-notizen').value = '';
  document.getElementById('b-externe-techniker').value = '';
  // v2.25.2: Doku-Block im Bündel-Modal entfernt — Render-Call weg.
  selectedBundleTeamIds = new Set();
  _bundleDayRows = [];
  _bundleDeletedDayIds = [];

  // Reset-Button am Preis verdrahten
  const priceReset = document.getElementById('b-einzelpreis-reset');
  if (priceReset) {
    priceReset.onclick = () => {
      const opt = serviceSelect.options[serviceSelect.selectedIndex];
      const preis = opt?.getAttribute('data-preis');
      if (!preis) { showToast('Kein Service mit Standardpreis gewählt.', true); return; }
      document.getElementById('b-einzelpreis').value = preis;
    };
  }

  // + Tag hinzufügen
  document.getElementById('b-add-day').onclick = () => addBundleDayRow();

  if (mode === 'edit' && bundleId) {
    const { data: bundle, error } = await db.from('deployment_bundles')
      .select('*').eq('id', bundleId).single();
    if (error || !bundle) {
      showToast('Bündel konnte nicht geladen werden.', true);
      return;
    }
    document.getElementById('b-titel').value         = bundle.titel || '';
    document.getElementById('b-einzelpreis').value   = bundle.einzelpreis ?? '';
    document.getElementById('b-ort').value           = bundle.ort || '';
    document.getElementById('b-beschreibung').value  = bundle.beschreibung || '';
    document.getElementById('b-notizen').value       = bundle.notizen || '';
    document.getElementById('b-externe-techniker').value = bundle.externe_techniker || '';
    if (bundle.service_id) serviceSelect.value = bundle.service_id;
    // v2.25.2: Doku-Block im Bündel-Modal entfernt — Render-Call weg.

    const [teamRows, deps] = await Promise.all([
      db.from('deployment_bundle_technicians').select('user_id').eq('bundle_id', bundleId),
      db.from('deployments').select('id, datum_von, uhrzeit_von, uhrzeit_bis, menge, status')
        .is('deleted_at', null).eq('bundle_id', bundleId).order('datum_von', { ascending: true })
    ]);
    selectedBundleTeamIds = new Set((teamRows.data || []).map(r => r.user_id));
    (deps.data || []).forEach(d => _bundleDayRows.push({
      id: d.id,
      datum_von: d.datum_von || '',
      uhrzeit_von: d.uhrzeit_von ? d.uhrzeit_von.substring(0,5) : '',
      uhrzeit_bis: d.uhrzeit_bis ? d.uhrzeit_bis.substring(0,5) : '',
      menge: d.menge ?? 1,
      status: d.status || DEPLOYMENT_STATUS.GEPLANT
    }));
  } else if (Array.isArray(opts.fromDeploymentIds) && opts.fromDeploymentIds.length > 0) {
    // Konvertier-Flow: bestehende Einsätze in ein neues Bündel ziehen.
    const { data: deps } = await db.from('deployments')
      .select('id, titel, datum_von, uhrzeit_von, uhrzeit_bis, menge, status, einzelpreis, service_id, ort, beschreibung, dokumentation, externe_techniker')
      .is('deleted_at', null)
      .in('id', opts.fromDeploymentIds)
      .order('datum_von', { ascending: true });
    const list = deps || [];
    if (list.length > 0) {
      const first = list[0];
      document.getElementById('b-titel').value         = first.titel || '';
      document.getElementById('b-einzelpreis').value   = first.einzelpreis ?? '';
      document.getElementById('b-ort').value           = first.ort || '';
      document.getElementById('b-beschreibung').value  = first.beschreibung || '';
      document.getElementById('b-externe-techniker').value = first.externe_techniker || '';
      if (first.service_id) serviceSelect.value = first.service_id;
      // v2.25.2: Doku-Block im Bündel-Modal entfernt.
      // Techniker-Vereinigung aus allen Einsätzen
      const { data: techRows } = await db.from('deployment_technicians')
        .select('user_id').in('deployment_id', list.map(d => d.id));
      selectedBundleTeamIds = new Set((techRows || []).map(r => r.user_id));
      list.forEach(d => _bundleDayRows.push({
        id: d.id,
        datum_von: d.datum_von || '',
        uhrzeit_von: d.uhrzeit_von ? d.uhrzeit_von.substring(0,5) : '',
        uhrzeit_bis: d.uhrzeit_bis ? d.uhrzeit_bis.substring(0,5) : '',
        menge: d.menge ?? 1,
        status: d.status || DEPLOYMENT_STATUS.GEPLANT
      }));
    }
  }

  // Wenn weder Edit noch Konvertierung: starte mit einer leeren Zeile
  if (_bundleDayRows.length === 0) addBundleDayRow();

  renderBundleTeamChips();
  renderBundleDayRows();
  updateBundleDaysSummary();

  document.getElementById('modal-deployment-bundle').classList.add('open');
  setTimeout(() => document.getElementById('b-titel')?.focus(), 100);
}

function closeDeploymentBundleModal() {
  document.getElementById('modal-deployment-bundle').classList.remove('open');
  editingBundleId = null;
  selectedBundleTeamIds = new Set();
  _bundleDayRows = [];
  _bundleDeletedDayIds = [];
}

function onBundleServiceChange() {
  const sel = document.getElementById('b-service');
  const opt = sel.options[sel.selectedIndex];
  const preis = opt?.getAttribute('data-preis');
  const aktuell = document.getElementById('b-einzelpreis').value;
  if (preis && (!aktuell || Number(aktuell) === 0)) {
    document.getElementById('b-einzelpreis').value = preis;
  }
}

function renderBundleTeamChips() {
  const wrap = document.getElementById('b-team-list');
  if (!wrap) return;
  if (userProfilesCache.length === 0) {
    wrap.innerHTML = '<span style="font-size:12px;color:var(--muted)">Keine internen Kollegen verfügbar.</span>';
    return;
  }
  wrap.innerHTML = userProfilesCache.map(u => {
    const selected = selectedBundleTeamIds.has(u.id);
    return `
      <div class="techniker-chip${selected ? ' selected' : ''}" data-user-id="${esc(u.id)}"
           onclick="toggleBundleTeamChip('${esc(u.id)}')">
        <span class="techniker-chip-avatar">${esc(ini(u.name))}</span>
        <span>${esc(u.name)}</span>
      </div>`;
  }).join('');
}

function toggleBundleTeamChip(userId) {
  if (selectedBundleTeamIds.has(userId)) selectedBundleTeamIds.delete(userId);
  else selectedBundleTeamIds.add(userId);
  renderBundleTeamChips();
}

function addBundleDayRow() {
  const last = _bundleDayRows[_bundleDayRows.length - 1];
  _bundleDayRows.push({
    id: null,
    datum_von: last?.datum_von ? _addWorkday(last.datum_von) : toISODate(new Date()),
    uhrzeit_von: last?.uhrzeit_von || '',
    uhrzeit_bis: last?.uhrzeit_bis || '',
    menge: last?.menge || 1,
    status: DEPLOYMENT_STATUS.GEPLANT
  });
  renderBundleDayRows();
  updateBundleDaysSummary();
}

function _addWorkday(iso) {
  const d = new Date(iso + 'T00:00:00');
  d.setDate(d.getDate() + 1);
  while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
  return toISODate(d);
}

function removeBundleDayRow(idx) {
  const row = _bundleDayRows[idx];
  if (!row) return;
  if (row.id) _bundleDeletedDayIds.push(row.id);
  _bundleDayRows.splice(idx, 1);
  renderBundleDayRows();
  updateBundleDaysSummary();
}

function renderBundleDayRows() {
  const tbody = document.getElementById('b-days-body');
  if (!tbody) return;
  if (_bundleDayRows.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6"><div class="empty" style="padding:14px">Noch keine Tage. Klicke oben auf „+ Tag hinzufügen".</div></td></tr>';
    return;
  }
  const statusOptions = einsatzStatusCache
    .map(s => `<option value="${esc(s.system_key)}">${esc(s.wert)}</option>`).join('');
  tbody.innerHTML = _bundleDayRows.map((r, i) => `
    <tr data-bundle-day-idx="${i}">
      <td><input type="date" value="${esc(r.datum_von || '')}" onchange="updateBundleDayField(${i},'datum_von',this.value)"></td>
      <td><input type="time" value="${esc(r.uhrzeit_von || '')}" onchange="updateBundleDayField(${i},'uhrzeit_von',this.value)"></td>
      <td><input type="time" value="${esc(r.uhrzeit_bis || '')}" onchange="updateBundleDayField(${i},'uhrzeit_bis',this.value)"></td>
      <td><input type="number" min="0" step="0.5" value="${esc(String(r.menge ?? 1))}" onchange="updateBundleDayField(${i},'menge',this.value)"></td>
      <td><select onchange="updateBundleDayField(${i},'status',this.value)">${statusOptions.replace(`value="${esc(r.status || '')}"`, `value="${esc(r.status || '')}" selected`)}</select></td>
      <td style="text-align:center"><button type="button" class="b-day-remove" title="Tag entfernen" onclick="removeBundleDayRow(${i})">×</button></td>
    </tr>`).join('');
}

function updateBundleDayField(idx, field, value) {
  if (!_bundleDayRows[idx]) return;
  _bundleDayRows[idx][field] = value;
  if (field === 'datum_von' || field === 'menge') updateBundleDaysSummary();
}

// v2.33.23 (von Selcuk gewählt: Option A): Tag-Service-Aufteilung. Bei einer
// pro-Tag-Leistung (Einheit „Tag") bedeutet Menge N = N Tage. Liefert die
// Werktags-Sequenz ab Startdatum (Wochenende Sa/So übersprungen).
function _bundleWorkingDaysFrom(startISO, n) {
  const out = [];
  let d = parseLocalDate(startISO);
  while (out.length < n) {
    const dow = d.getDay();              // 0=So, 6=Sa
    if (dow !== 0 && dow !== 6) out.push(toISODate(d));
    d.setDate(d.getDate() + 1);
  }
  return out;
}
// Tages-Specs ({datum, menge}) einer Bündel-Zeile. Bei Tag-Leistung und Menge>1:
// ceil(N) Werktage — volle Tage Menge 1, letzter ggf. der Rest (z.B. 0,5).
// Sonst: ein Eintrag mit der Original-Menge (unverändertes Verhalten).
function _bundleRowDaySpecs(r, isTagService) {
  const menge = Number(r.menge ?? 1) || 1;
  if (!isTagService || menge <= 1 || !r.datum_von) {
    return [{ datum: r.datum_von, menge }];
  }
  const n = Math.ceil(menge);
  const full = Math.floor(menge);
  return _bundleWorkingDaysFrom(r.datum_von, n)
    .map((datum, i) => ({ datum, menge: i < full ? 1 : +(menge - full).toFixed(4) }));
}

function updateBundleDaysSummary() {
  const el = document.getElementById('b-days-summary');
  if (!el) return;
  // v2.33.23: Bei einer Tag-Leistung zählt die Summe der Mengen als Tage
  // (Menge 5 → „5 Tage", nicht „1 Zeile"); sonst die Anzahl Zeilen. Fraktionale
  // Tage (z.B. 4,5) werden mit deutschem Komma angezeigt.
  const totalMenge = _bundleDayRows.reduce((s, r) => s + (Number(r.menge) || 0), 0);
  const rowsWithDate = _bundleDayRows.filter(r => r.datum_von).length;
  const svc = servicesCache.find(s => s.id === (document.getElementById('b-service')?.value || ''));
  const isTagService = (svc?.einheit || '').trim().toLowerCase() === 'tag';
  const dayCount = isTagService ? totalMenge : rowsWithDate;
  const einzel = Number(document.getElementById('b-einzelpreis')?.value || 0);
  const gesamt = totalMenge * einzel;
  const dcFmt = Number.isInteger(dayCount) ? String(dayCount) : dayCount.toLocaleString('de-DE');
  el.textContent = `${dcFmt} Tag${dayCount === 1 ? '' : 'e'} · Gesamt-Aufwand: ${formatPreis(gesamt)}`;
}

async function saveDeploymentBundle() {
  if (!currentProjectDetailId) return;

  const titel = document.getElementById('b-titel').value.trim();
  if (!titel) { showToast('Bitte Titel eingeben.', true); return; }
  const valid = _bundleDayRows.filter(r => r.datum_von);
  if (valid.length === 0 && _bundleDeletedDayIds.length === 0) {
    showToast('Bitte mindestens einen Tag mit Datum hinzufügen.', true);
    return;
  }

  // Bundle-Projekt-Firma ableiten
  const { data: proj } = await db.from('projects')
    .select('company_id').is('deleted_at', null).eq('id', currentProjectDetailId).single();
  const companyId = proj?.company_id || null;

  // v2.12.1: bestehende Bündel-Doku mit den Modal-Werten mergen, damit
  // Nicht-Schema-Keys nicht verloren gehen, falls jemand sie einmal direkt
  // im JSONB hatte.
  let _existingBundleDoc = null;
  if (editingBundleId) {
    const { data: _existing } = await db.from('deployment_bundles')
      .select('dokumentation').eq('id', editingBundleId).single();
    _existingBundleDoc = _existing?.dokumentation || null;
  }
  const payload = {
    titel,
    beschreibung: document.getElementById('b-beschreibung').value.trim() || null,
    notizen: document.getElementById('b-notizen').value.trim() || null,
    service_id: document.getElementById('b-service').value || null,
    einzelpreis: Number(document.getElementById('b-einzelpreis').value) || 0,
    ort: document.getElementById('b-ort').value.trim() || null,
    externe_techniker: document.getElementById('b-externe-techniker').value.trim() || null,
    company_id: companyId,
    project_id: currentProjectDetailId,
    // v2.25.2: Doku-Block aus UI entfernt — bestehende dokumentation 1:1 erhalten
    dokumentation: _existingBundleDoc || {}
  };
  if (!editingBundleId && currentProfile?.id) payload.erstellt_von = currentProfile.id;

  try {
    let bundle;
    if (editingBundleId) {
      const { data, error } = await db.from('deployment_bundles')
        .update(payload).eq('id', editingBundleId).select().single();
      if (error) throw new Error(error.message);
      bundle = data;
    } else {
      const { data, error } = await db.from('deployment_bundles')
        .insert(payload).select().single();
      if (error) throw new Error(error.message);
      bundle = data;
    }

    // Internes Team syncen (delete-then-insert)
    await db.from('deployment_bundle_technicians').delete().eq('bundle_id', bundle.id);
    if (selectedBundleTeamIds.size > 0) {
      const techRows = [...selectedBundleTeamIds].map(uid => ({ bundle_id: bundle.id, user_id: uid }));
      await db.from('deployment_bundle_technicians').insert(techRows);
    }

    // Tage-Liste syncen — gelöschte Einträge soft-löschen
    if (_bundleDeletedDayIds.length > 0) {
      await db.from('deployments')
        .update({ deleted_at: new Date().toISOString() })
        .in('id', _bundleDeletedDayIds);
    }

    // v2.12.1: Beim Propagieren der Bündel-Doku auf die Mitgliedstage NUR die
    // Schema-Keys ersetzen, Nicht-Schema-Keys bleiben erhalten.
    // v2.12.2: Per-Tag-Override-Schutz — Felder, die in `bundle_overrides`
    // eines Mitglieds stehen, werden NICHT mehr vom Bündel überschrieben.
    const SCHEMA_KEYS = (DOCUMENTATION_SCHEMAS.einsatz || []).map(f => f.key);
    const bundleSchemaSlice = {};
    for (const k of SCHEMA_KEYS) {
      if (payload.dokumentation && Object.prototype.hasOwnProperty.call(payload.dokumentation, k)) {
        bundleSchemaSlice[k] = payload.dokumentation[k];
      }
    }
    // Mapping shared-field-key → Bündel-Wert (das was beim Bundle-Save
    // gespeichert wird). Wird pro Mitglied gefiltert nach bundle_overrides.
    const bundleSharedValues = {
      titel: payload.titel,
      beschreibung: payload.beschreibung,
      service_id: payload.service_id,
      einzelpreis: payload.einzelpreis,
      ort: payload.ort,
      externe_techniker: payload.externe_techniker
    };
    const baseFieldsForNew = {
      bundle_id: bundle.id,
      ...bundleSharedValues,
      company_id: companyId,
      project_id: currentProjectDetailId
    };
    // v2.33.23 (von Selcuk gewählt: Option A): Bei einer pro-Tag-Leistung
    // (Einheit „Tag") wird eine Zeile mit Menge N in N Werktags-Einsätze (je
    // 1 Tag) aufgeteilt, damit Kalender/Auslastung/Umsatz/Briefing alle N Tage
    // als einzelne Einsatztage zeigen. Nicht-Tag-Leistungen + Menge ≤ 1 bleiben
    // ein Einsatz (unverändertes Verhalten).
    const _bundleSvc = servicesCache.find(s => s.id === payload.service_id);
    const _isTagService = (_bundleSvc?.einheit || '').trim().toLowerCase() === 'tag';

    for (const r of valid) {
      const daySpecs = _bundleRowDaySpecs(r, _isTagService);
      for (let di = 0; di < daySpecs.length; di++) {
        const spec = daySpecs[di];
        const perDayFields = {
          datum_von: spec.datum,
          datum_bis: spec.datum,
          uhrzeit_von: r.uhrzeit_von || null,
          uhrzeit_bis: r.uhrzeit_bis || null,
          menge: spec.menge,
          status: r.status || DEPLOYMENT_STATUS.GEPLANT
        };
        // Nur der ERSTE Tag einer Zeile recycelt einen evtl. vorhandenen Einsatz
        // (r.id); die weiteren Tage der Aufteilung sind neue Einsätze.
        const recycleId = (di === 0 && r.id) ? r.id : null;
        if (recycleId) {
          // Bestehender Einsatz — bundle_overrides respektieren.
          const { data: existing } = await db.from('deployments')
            .select('dokumentation, bundle_overrides').eq('id', recycleId).single();
          const overrides = new Set(Array.isArray(existing?.bundle_overrides) ? existing.bundle_overrides : []);

          const updateFields = {
            bundle_id: bundle.id,
            company_id: companyId,
            project_id: currentProjectDetailId,
            ...perDayFields
          };
          // Shared-Felder nur überschreiben, wenn nicht in overrides.
          for (const [key, val] of Object.entries(bundleSharedValues)) {
            if (!overrides.has(key)) updateFields[key] = val;
          }
          // Dokumentation: wenn nicht overridden, Schema-Keys vom Bündel
          // mergen; existierende Nicht-Schema-Keys bleiben erhalten.
          if (!overrides.has('dokumentation')) {
            const memberDoc = { ...(existing?.dokumentation || {}) };
            for (const k of SCHEMA_KEYS) {
              if (Object.prototype.hasOwnProperty.call(bundleSchemaSlice, k)) memberDoc[k] = bundleSchemaSlice[k];
              else delete memberDoc[k];
            }
            updateFields.dokumentation = memberDoc;
          }
          await db.from('deployments').update(updateFields).eq('id', recycleId);
        } else {
          await db.from('deployments').insert({
            ...baseFieldsForNew,
            ...perDayFields,
            dokumentation: bundleSchemaSlice,
            erstellt_von: currentProfile?.id || null,
            bundle_overrides: []
          });
        }
      }
    }

    // Technician-Sync auf alle Bundle-Member: vereinheitlichtes Team aus dem Bundle
    const memberIds = (await db.from('deployments').select('id').is('deleted_at', null).eq('bundle_id', bundle.id)).data?.map(r => r.id) || [];
    if (memberIds.length > 0) {
      await db.from('deployment_technicians').delete().in('deployment_id', memberIds);
      if (selectedBundleTeamIds.size > 0) {
        const rows = [];
        memberIds.forEach(did => selectedBundleTeamIds.forEach(uid => rows.push({ deployment_id: did, user_id: uid })));
        await db.from('deployment_technicians').insert(rows);
      }
    }

    closeDeploymentBundleModal();
    showToast(editingBundleId ? 'Bündel aktualisiert.' : 'Bündel angelegt.');
    await refreshProjectAfterFinanceChange(currentProjectDetailId);
  } catch (e) {
    showToast(e.message, true);
  }
}

async function deleteDeploymentBundle() {
  if (!editingBundleId) return;
  const ok = await confirmDialog({
    title: 'Bündel löschen?',
    message: 'Das Bündel wird soft-gelöscht. Die zugehörigen Einsätze bleiben erhalten — sie werden nur aus dem Bündel gelöst.',
    confirmLabel: 'Bündel auflösen', cancelLabel: 'Abbrechen', danger: true
  });
  if (!ok) return;
  try {
    await db.from('deployments').update({ bundle_id: null }).eq('bundle_id', editingBundleId);
    await db.from('deployment_bundles').update({ deleted_at: new Date().toISOString() }).eq('id', editingBundleId);
    closeDeploymentBundleModal();
    showToast('Bündel aufgelöst — Einsätze sind wieder einzelne Datensätze.');
    if (currentProjectDetailId) await refreshProjectAfterFinanceChange(currentProjectDetailId);
  } catch (e) {
    showToast(e.message, true);
  }
}

// Bündel-Liste am Projekt — wird im Wirtschaftlichkeit-Tab gerendert.
let _projectBundlesCache = [];
let _collapsedBundleIds = new Set();   // UI-State: welche Bündel sind eingeklappt

/** Picker-Dialog: zeigt alle ungebündelten Einsätze des aktuellen Projekts mit
 *  Checkboxen und öffnet das Bündel-Modal mit den ausgewählten als Tagen. */
async function openBundleFromExistingPicker() {
  if (!currentProjectDetailId) return;
  const { data: deps } = await db.from('deployments')
    .select('id, titel, datum_von, datum_bis, einzelpreis, menge, status')
    .is('deleted_at', null).is('bundle_id', null).eq('project_id', currentProjectDetailId)
    .order('datum_von', { ascending: true, nullsFirst: false });
  const list = deps || [];
  if (list.length === 0) {
    showToast('Keine ungebündelten Einsätze in diesem Projekt.', false);
    return;
  }

  const rowsHtml = list.map(d => {
    const date = d.datum_von ? formatDateDE(d.datum_von) : 'Ungeplant';
    const wert = formatPreis((Number(d.menge) || 0) * (Number(d.einzelpreis) || 0));
    return `<label class="bundle-picker-row" style="display:flex;align-items:center;gap:10px;padding:8px 4px;border-bottom:0.5px solid var(--border);cursor:pointer">
      <input type="checkbox" value="${esc(d.id)}" style="width:16px;height:16px;margin:0">
      <span style="font-size:12px;color:var(--muted);min-width:90px">${esc(date)}</span>
      <span style="flex:1;font-size:13px;color:var(--text)">${esc(d.titel || '—')}</span>
      <span style="font-size:12px;color:var(--muted)">${esc(dispStatus(d.status))}</span>
      <span style="font-size:12px;color:var(--text);font-variant-numeric:tabular-nums">${esc(wert)}</span>
    </label>`;
  }).join('');

  const ok = await confirmDialog({
    title: 'Einsätze zu Bündel zusammenfassen',
    message: `<div style="font-size:13px;color:var(--muted);margin-bottom:10px">
        Wähle mindestens zwei Einsätze aus, die als Tage in einem neuen Bündel
        zusammengefasst werden sollen. Die gemeinsamen Werte des ersten Einsatzes
        (Titel, Service, Preis, Ort, Doku, Team) werden ins Bündel übernommen.
      </div>
      <div id="bundle-picker-list" style="max-height:340px;overflow-y:auto;border:1px solid var(--border);border-radius:6px;padding:4px 8px">${rowsHtml}</div>`,
    confirmLabel: 'Bündel anlegen',
    cancelLabel: 'Abbrechen',
    danger: false
  });
  if (!ok) return;

  const checked = Array.from(document.querySelectorAll('#bundle-picker-list input[type=checkbox]:checked'))
    .map(cb => cb.value);
  if (checked.length < 2) {
    showToast('Bitte mindestens zwei Einsätze auswählen.', true);
    return;
  }
  openDeploymentBundleModal('new', null, { fromDeploymentIds: checked });
}

function toggleBundleCollapse(bundleId) {
  if (_collapsedBundleIds.has(bundleId)) _collapsedBundleIds.delete(bundleId);
  else _collapsedBundleIds.add(bundleId);
  if (currentProjectDetailId) loadProjectDeployments(currentProjectDetailId);
}

/**
 * Quick-Toggle für Termin-Status via Checkbox in Projekt-Detail.
 * Togglet zwischen 'geplant' und 'durchgefuehrt' per direktes DOM-Update (kein Page-Reload).
 */
async function toggleAppointmentDone(appointmentId, isChecked, checkboxEl) {
  const newStatus = isChecked ? 'durchgefuehrt' : 'geplant';

  if (checkboxEl) checkboxEl.disabled = true;

  try {
    const { error } = await db.from('appointments')
      .update({ status: newStatus })
      .eq('id', appointmentId);
    if (error) throw new Error(error.message);

    // DOM-Update der betroffenen Zeile (ohne Reload)
    const tr = checkboxEl ? checkboxEl.closest('tr') : null;
    if (tr) {
      tr.setAttribute('data-appt-status', newStatus);
      const statusCell = tr.querySelector('.appt-status-cell');
      if (statusCell) {
        statusCell.innerHTML = `<span class="badge" style="background:${appointmentStatusBg(newStatus)};color:${appointmentStatusColor(newStatus)}">${esc(appointmentStatusLabel(newStatus))}</span>`;
      }
    }

    // Count-Label für Termine aus DOM neu berechnen
    refreshProjectAppointmentsCountLabel();

    // Projekt-Status-Check + evtl. Header-Update, ohne ganze Seite neu zu laden
    if (currentProjectDetailId) {
      await checkAndUpdateProjectStatusSmart(currentProjectDetailId);
    }
  } catch (e) {
    showToast('Status konnte nicht geändert werden: ' + e.message, true);
    if (checkboxEl) checkboxEl.checked = !isChecked;
  } finally {
    if (checkboxEl) checkboxEl.disabled = false;
  }
}

/**
 * Berechnet das Count-Label der Projekt-Termine aus den data-appt-status Attributen im DOM.
 */
function refreshProjectAppointmentsCountLabel() {
  const countEl = document.getElementById('project-appointments-count');
  const body = document.getElementById('project-appointments-body');
  if (!countEl || !body) return;
  const rows = body.querySelectorAll('tr[data-appt-status]');
  const total = rows.length;
  if (total === 0) return;

  const arr = Array.from(rows);
  const anzGeplant       = arr.filter(r => r.getAttribute('data-appt-status') === APPOINTMENT_STATUS.GEPLANT).length;
  const anzDurchgefuehrt = arr.filter(r => r.getAttribute('data-appt-status') === APPOINTMENT_STATUS.DURCHGEFUEHRT).length;
  countEl.textContent = `${total} Termin${total === 1 ? '' : 'e'} · ${anzGeplant} geplant · ${anzDurchgefuehrt} durchgeführt`;
}

/**
 * Wie checkAndUpdateProjectStatus, aber updated das Header-Status-Badge direkt im DOM
 * statt die ganze Projekt-Seite neu zu laden. Für flüssige UX bei Quick-Toggle.
 */
async function checkAndUpdateProjectStatusSmart(projectId) {
  const { data: project, error: pErr } = await db.from('projects')
    .select('id, status').is('deleted_at', null).eq('id', projectId).single();
  if (pErr || !project) return;

  const projektStatusKey = project.status;
  const aktiveStatus = [PROJECT_STATUS.IN_ARBEIT, PROJECT_STATUS.ABSCHLUSSPHASE, PROJECT_STATUS.ABGESCHLOSSEN];
  if (!aktiveStatus.includes(projektStatusKey)) return;

  const { data: deployments } = await db.from('deployments')
    .select('status').is('deleted_at', null).eq('project_id', projectId);
  const allDeps = deployments || [];

  const { data: appointments } = await db.from('appointments')
    .select('status').is('deleted_at', null).eq('project_id', projectId);
  const allAppts = appointments || [];

  // v2.33.2: Storniert ausfiltern — identische Semantik wie in der nicht-Smart-Variante.
  const countsDone = (arr, doneSystemKeys, kategorie) => {
    const active = arr.filter(x => x.status !== 'storniert');
    if (active.length === 0) return { hasAny: false, allDone: true };
    const done = active.filter(x => doneSystemKeys.includes(x.status)).length;
    return { hasAny: true, allDone: done === active.length };
  };

  const depStats  = countsDone(allDeps,  [DEPLOYMENT_STATUS.DURCHGEFUEHRT, DEPLOYMENT_STATUS.ABGERECHNET], 'einsatz_status');
  const apptStats = countsDone(allAppts, [APPOINTMENT_STATUS.DURCHGEFUEHRT],                                'termin_status');

  if (!depStats.hasAny) return;

  let neuerStatusKey = projektStatusKey;
  if (depStats.allDone && apptStats.allDone) {
    neuerStatusKey = PROJECT_STATUS.ABGESCHLOSSEN;
  } else if (depStats.allDone) {
    neuerStatusKey = PROJECT_STATUS.ABSCHLUSSPHASE;
  } else {
    neuerStatusKey = PROJECT_STATUS.IN_ARBEIT;
  }

  if (neuerStatusKey !== projektStatusKey) {
    const { error: updErr } = await db.from('projects')
      .update({ status: neuerStatusKey }).eq('id', projectId);
    if (!updErr) {
      const neuerLabel = getStatusLabel('projekt_status', neuerStatusKey, neuerStatusKey);
      showToast(`Projekt-Status automatisch auf „${neuerLabel}" aktualisiert.`);
      // Header-Badge direkt im DOM updaten (kein Page-Reload)
      updateProjectHeaderStatusBadge(neuerStatusKey);
    }
  }
}

/**
 * Aktualisiert das Status-Badge in der Projekt-Detail-Subline ohne Reload.
 */
function updateProjectHeaderStatusBadge(newStatus) {
  const subline = document.getElementById('project-detail-subline');
  if (!subline) return;
  const badge = subline.querySelector('.badge');
  if (!badge) return;
  const color = projektStatusFarbe(newStatus);
  badge.style.background = color + '22';
  badge.style.color = color;
  badge.textContent = dispStatus(newStatus);  // v2.33.18 (A.1 #7): Label statt system_key
}

