  _currentContactActivityFilter = filter;
  if (filter !== 'notizen') {
    _currentContactNoteContextFilter = null;
    document.querySelectorAll('#page-contact-detail .proj-note-icons .proj-note-icon').forEach(b => b.classList.remove('is-active'));
  }
