let currentDeploymentDetailId = null;
let _currentDeploymentV2Tab = 'bericht';

async function loadDeploymentDetail(deploymentId) {
  currentDeploymentDetailId = deploymentId;
  // v2.23.0: Detail-Page rendert IN der Arbeitsplatz-Stage
  _activateDetailInArbeitsplatz('page-deployment-detail');

  const { data: d, error } = await db.from('deployments')
    .select('*, company:companies(id, name, abc_klassifizierung, strasse, plz, stadt, land), project:projects(id, name, status), service:services(id, name)')
    .is('deleted_at', null).eq('id', deploymentId).single();
  if (error || !d) {
    showToast(friendlyFetchError(error, 'Einsatz'), true);
    return;
  }

  // Header
  document.getElementById('dep-detail-name').textContent = d.titel || '—';
  document.getElementById('dep-detail-title').textContent = d.titel || '—';

  // Subline: Projekt-Link + Firma + Ort
  const sublineParts = [];
  if (d.project) sublineParts.push(`<a class="proj-link" onclick="navigateTo('projekt','${esc(d.project.id)}')">${esc(d.project.name)}</a>`);
  if (d.company) sublineParts.push(`<a class="proj-link" onclick="navigateTo('firma','${esc(d.company.id)}')">${esc(d.company.name)}</a>`);
  if (d.ort) sublineParts.push(esc(d.ort));
  document.getElementById('dep-detail-subline').innerHTML = sublineParts.join(' · ') || '—';

  // Status-Pille
  const statusPill = document.getElementById('dep-status-pill');
  if (d.status) {
    const cls = d.status.toLowerCase().replace(/[^a-z]/g, '');
    statusPill.innerHTML = `${esc(dispStatus(d.status))}<span class="status-pill-caret">▾</span>`;
    statusPill.className = `status-pill status-pill-clickable status-pill-${cls}`;
    statusPill.dataset.currentStatus = d.status;
    statusPill.dataset.entityId = deploymentId;
  }
  // v2.15.2: Status-Weiterbringen-Aktion im Aktionen-Sidebar rendern
  renderStatusAdvanceAction('deployment', deploymentId, d.status, 'dep-status-action');

  // Hero-Metriken
  const datum = d.datum_von ? formatDateDE(d.datum_von) : '—';
  const datumSub = d.datum_bis && d.datum_bis !== d.datum_von ? `bis ${formatDateDE(d.datum_bis)}` : (d.uhrzeit_von ? `${formatTime(d.uhrzeit_von)}${d.uhrzeit_bis ? '–' + formatTime(d.uhrzeit_bis) : ''}` : '');
  document.getElementById('dep-hero-datum').textContent = datum;
  document.getElementById('dep-hero-datum-sub').textContent = datumSub || ' ';

  const honorar = (Number(d.einzelpreis) || 0) * Number(d.menge ?? 1);
  document.getElementById('dep-hero-honorar').textContent = formatPreis(honorar);
  document.getElementById('dep-hero-honorar-sub').textContent = `${Number(d.menge || 1)} × ${formatPreis(d.einzelpreis || 0)}`;

  document.getElementById('dep-hero-leistung').textContent = d.service?.name || '—';
  document.getElementById('dep-hero-leistung-sub').textContent = d.ganztag ? 'Ganztag' : ' ';

  // v2.17.0: Bericht / Plan&Logistik / Abrechnung Tabs entfernt.
  // Daten (dokumentation, rechnungsnummer, …) bleiben in der DB; nur die
  // Felder werden temporär nicht mehr im DOM gerendert (Karteikarte folgt).
  // Capture-Stream-Liste laden (jetzt unter Aktivitäten-Tab)
  await renderDeploymentCaptureStream(deploymentId);

  // Sidepanel
  const projSide = document.getElementById('dep-side-projekt');
  if (d.project) {
    const projStatus = d.project.status || '—';
    projSide.innerHTML = `
      <a class="proj-side-firma-name" onclick="navigateTo('projekt','${esc(d.project.id)}')">${esc(d.project.name)}</a>
      <div class="proj-side-firma-meta">${esc(projStatus)}</div>`;
  } else {
    projSide.innerHTML = '<div class="info-card-empty">Kein Projekt verknüpft.</div>';
  }

  const firmaSide = document.getElementById('dep-side-firma');
  if (d.company) {
    firmaSide.innerHTML = `
      <a class="proj-side-firma-name" onclick="navigateTo('firma','${esc(d.company.id)}')">${esc(d.company.name)}</a>
      <div class="proj-side-firma-meta">${d.company.abc_klassifizierung ? `Kunde · ${esc(d.company.abc_klassifizierung)}` : 'Kunde'}${d.company.stadt ? ' · ' + esc(d.company.stadt) : ''}</div>`;
  }

  document.getElementById('dep-meta').innerHTML = `
    <div>ID · ${esc(deploymentId.substring(0, 8))}</div>
    <div>Erstellt · ${d.created_at ? esc(formatDateDE(d.created_at.substring(0, 10))) : '—'}</div>`;

  // v2.17.0: Abrechnung-Summary + Workflow-Checkliste + Attachments-Zone
  // entfernt — Tabs sind weg. Daten bleiben in der DB, kommen in der
  // Karteikarten-Phase zurück.

  trackVisit('einsatz', deploymentId, d.titel || '—', d.company?.name || '');

  // v2.17.1: Anhänge-Zone laden
  renderAttachmentZone('deployment', deploymentId, 'dep-attachments');

  // Default-Tab ist Aktivitäten — v2.27.8: respektiert jetzt _pendingDetailTab,
  // sodass „Fortführen → Einsatz vorbereiten" direkt im Doku-Tab landet.
  let depTab = 'aktivitaeten';
  if (_pendingDetailTab) {
    depTab = _pendingDetailTab;
    _pendingDetailTab = null;
  }
  _currentDeploymentV2Tab = depTab;
  switchDeploymentV2Tab(depTab);
}

function switchDeploymentV2Tab(tab) {
  _currentDeploymentV2Tab = tab;
  document.querySelectorAll('#page-deployment-detail .proj-tab').forEach(t =>
    t.classList.toggle('active', t.dataset.tab === tab));
  document.querySelectorAll('#page-deployment-detail .proj-tab-panel').forEach(p =>
    p.style.display = p.dataset.tab === tab ? '' : 'none');
  if (tab === 'doku' && currentDeploymentDetailId) renderDocSections('deployment', currentDeploymentDetailId, 'dep-doku-sections');
}

async function renderDeploymentReportThemes(d) {
  const wrap = document.getElementById('dep-themes-area');
  const hint = document.getElementById('dep-themes-hint');
  if (!wrap) return;
  // v2.16.0: Themen leben firmenweit — Einsätze ohne Projekt taggen
  // trotzdem aus dem Firmen-Pool. Wenn keine Firma gesetzt: Hinweis.
  if (!d.company_id) {
    wrap.innerHTML = '<div class="info-card-empty">Keine Firma am Einsatz — Themen brauchen einen Firmen-Bezug.</div>';
    if (hint) hint.style.display = 'none';
    return;
  }
  const themes = await loadCompanyThemesData(d.company_id);
  // Bei Projekt-Einsätzen heben wir die Curriculum-Themen visuell hervor
  let curriculumIds = new Set();
  if (d.project_id) {
    const { data: ass } = await db.from('project_theme_assignments')
      .select('theme_id').is('deleted_at', null).eq('project_id', d.project_id);
    (ass || []).forEach(r => curriculumIds.add(r.theme_id));
  }

  if (themes.length === 0) {
    // Aktionsorientierter Empty-State: bei Projekt-Einsätzen direkt zum
    // Projekt-Planung-Tab springen; bei freien Einsätzen Hinweis auf Firma.
    if (d.project_id) {
      wrap.innerHTML = `
        <div class="empty-state-card empty-state-card-compact">
          <div class="empty-state-hint">Diese Firma hat noch keine Themen.</div>
          <button class="btn btn-sm btn-primary" onclick="_jumpToProjectPlanFromEinsatz('${esc(d.project_id)}')">Themen am Projekt anlegen →</button>
        </div>`;
    } else {
      wrap.innerHTML = '<div class="info-card-empty">Diese Firma hat noch keine Themen — am Projekt der Firma definieren oder per Themen-Modal anlegen.</div>';
    }
    if (hint) hint.style.display = 'none';
    return;
  }
  const { data: assigned } = await db.from('deployment_themes').select('theme_id').eq('deployment_id', d.id);
  const assignedIds = new Set((assigned || []).map(r => r.theme_id));

  if (hint) {
    hint.style.display = '';
    hint.textContent = d.project_id
      ? 'Aus dem Firmen-Pool — Projekt-Curriculum mit ★ markiert.'
      : 'Aus dem Firmen-Pool.';
  }

  wrap.innerHTML = `<div class="theme-picker-list">${themes.map(t => `
    <label class="theme-pick-item ${curriculumIds.has(t.id) ? 'is-curriculum' : ''}">
      <input type="checkbox" data-theme-id="${esc(t.id)}" ${assignedIds.has(t.id) ? 'checked' : ''}
             onchange="toggleDeploymentReportTheme('${esc(d.id)}','${esc(t.id)}', this.checked)">
      <span class="theme-color-dot" style="background:${esc(t.farbe || '#E6F1FB')}"></span>
      <span class="theme-pick-name">${esc(t.name)}${curriculumIds.has(t.id) ? ' <span class="theme-pick-star" title="Im Projekt-Curriculum">★</span>' : ''}</span>
    </label>`).join('')}</div>`;
}

/** v2.13.6 → v2.15.0: vom Einsatz aus zum Projekt-Brief springen. Die
 *  Themen-CRUD lebt seit v2.15.0 im Planung-Tab; deshalb landet der
 *  Sprung jetzt dort. Der alte Funktionsname bleibt für Backwards-Compat. */
function _jumpToProjectBriefFromEinsatz(projectId) {
  _pendingDetailTab = 'planung';
  navigateTo('projekt', projectId);
}
/** v2.16.0: expliziter Aliasname — bei Themen-Anlage aus dem Einsatz
 *  springt der User direkt in den Planung-Tab des Projekts. */
function _jumpToProjectPlanFromEinsatz(projectId) {
  _pendingDetailTab = 'planung';
  navigateTo('projekt', projectId);
}

