let _currentCaptureKategorie = 'was_gemacht';

const _CAPTURE_KATEGORIEN = {
  was_gemacht: { label: 'Erledigt',   emoji: '📝', color: '#1d4ed8' },
  erkenntnis:  { label: 'Erkenntnis', emoji: '💡', color: '#b45309' },
  folge:       { label: 'Folge',      emoji: '🎯', color: '#7c3aed' },
  log:         { label: 'Log',        emoji: '📋', color: '#16a34a' }
};

function setCaptureKategorie(kat) {
  if (!_CAPTURE_KATEGORIEN[kat]) return;
  _currentCaptureKategorie = kat;
  document.querySelectorAll('.capture-stream-chip').forEach(c => {
    c.classList.toggle('is-active', c.dataset.kategorie === kat);
  });
}

async function postDeploymentLogEntry() {
  if (!currentDeploymentDetailId) return;
  const input = document.getElementById('dep-capture-input');
  if (!input) return;
  const inhalt = (input.value || '').trim();
  if (!inhalt) { showToast('Bitte Inhalt eingeben.', true); return; }
  const { error } = await db.from('deployment_log').insert({
    deployment_id: currentDeploymentDetailId,
    kategorie: _currentCaptureKategorie,
    inhalt,
    erstellt_von: currentProfile?.id || null
  });
  if (error) { showToast(error.message, true); return; }
  input.value = '';
  await renderDeploymentCaptureStream(currentDeploymentDetailId);
}

async function renderDeploymentCaptureStream(deploymentId) {
  const list = document.getElementById('dep-capture-stream-list');
  if (!list) return;

  // Initial-Chip-State setzen (was_gemacht aktiv)
  document.querySelectorAll('.capture-stream-chip').forEach(c => {
    c.classList.toggle('is-active', c.dataset.kategorie === _currentCaptureKategorie);
  });

  const { data, error } = await db.from('deployment_log')
    .select('id, kategorie, inhalt, created_at, user:user_profiles(name)')
    .is('deleted_at', null).eq('deployment_id', deploymentId)
    .order('created_at', { ascending: false });
  if (error) {
    list.innerHTML = `<div class="empty-state-mini">Fehler beim Laden: ${esc(error.message)}</div>`;
    return;
  }
  const items = data || [];
  if (items.length === 0) {
    list.innerHTML = '<div class="empty-state-mini">Noch nichts protokolliert — wähle eine Kategorie und tippe los.</div>';
    return;
  }
  list.innerHTML = items.map(it => {
    const kat = _CAPTURE_KATEGORIEN[it.kategorie] || { label: it.kategorie, emoji: '·', color: 'var(--muted)' };
    const when = formatDateTimeCompact(it.created_at);
    return `
      <div class="capture-stream-item" data-id="${esc(it.id)}">
        <span class="capture-stream-item-chip" style="background:${esc(kat.color)}22;color:${esc(kat.color)}">${kat.emoji} ${esc(kat.label)}</span>
        <div class="capture-stream-item-body">
          <div class="capture-stream-item-text">${esc(it.inhalt)}</div>
          <div class="capture-stream-item-meta">${esc(when)}${it.user?.name ? ' · ' + esc(it.user.name) : ''}</div>
        </div>
        <button type="button" class="capture-stream-item-delete" title="Eintrag löschen"
                onclick="deleteDeploymentLogEntry('${esc(it.id)}')">×</button>
      </div>`;
  }).join('');
}

async function deleteDeploymentLogEntry(id) {
  if (!confirm('Eintrag wirklich löschen?')) return;
  const { error } = await db.from('deployment_log')
    .update({ deleted_at: new Date().toISOString() }).eq('id', id);
  if (error) { showToast(error.message, true); return; }
  if (currentDeploymentDetailId) await renderDeploymentCaptureStream(currentDeploymentDetailId);
}

// Helper: kompakter Zeitstempel — „heute 14:32", „gestern 09:15", „13.05. 14:32"
function formatDateTimeCompact(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  const now = new Date();
  const startToday = new Date(now); startToday.setHours(0,0,0,0);
  const diffDays = Math.round((startToday - new Date(d.getFullYear(), d.getMonth(), d.getDate())) / 86400000);
  const hhmm = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  if (diffDays === 0) return `heute ${hhmm}`;
  if (diffDays === 1) return `gestern ${hhmm}`;
  if (diffDays <= 7)  return `vor ${diffDays} Tagen`;
  const dd = String(d.getDate()).padStart(2,'0');
  const mm = String(d.getMonth() + 1).padStart(2,'0');
  return `${dd}.${mm}. ${hhmm}`;
}

/** v2.14.2: Status-Briefing am Einsatz — Card am Anfang des Bericht-Tabs,
 *  die je nach `einsatz_status` einen anderen Schwerpunkt zeigt:
 *    • geplant       → Vor-Einsatz-Briefing mit 3 Prompts (klick = füllt
 *                      die Capture-Eingabe vor)
 *    • durchgefuehrt → Pulse-Card mit Eintrags-Zähler + Aufruf
 *                      „Workflow abschließen"
 *    • Abgerechnet   → kompakte Read-only-Zusammenfassung
 *  Bei unbekanntem Status wird die Karte ausgeblendet. */
function renderDeploymentStatusBriefing(d) {
  const el = document.getElementById('dep-status-briefing');
  if (!el) return;
  const status = (d?.status || '').toString();

  // STATUS „Geplant" — Vor-Einsatz-Briefing
  if (status === DEPLOYMENT_STATUS.GEPLANT) {
    const datum = d.datum_von ? formatDateDE(d.datum_von) : '—';
    el.innerHTML = `
      <div class="dep-briefing-card dep-briefing-planned">
        <div class="dep-briefing-head">
          <div class="dep-briefing-title">VOR DEM EINSATZ · ${esc(datum)}</div>
          <div class="dep-briefing-hint">Klick auf einen Vorschlag — die Capture-Zeile wird vorbefüllt.</div>
        </div>
        <div class="dep-briefing-grid">
          <button type="button" class="dep-briefing-tile" onclick="prefillCaptureFromBriefing('was_gemacht','Vorbereitung:\\n- ')">
            <span class="dep-briefing-emoji">📦</span>
            <span class="dep-briefing-tile-title">Was bringe ich mit?</span>
            <span class="dep-briefing-tile-sub">Unterlagen, Hardware, Beispiele</span>
          </button>
          <button type="button" class="dep-briefing-tile" onclick="prefillCaptureFromBriefing('folge','Ziel des Einsatzes:\\n- ')">
            <span class="dep-briefing-emoji">🎯</span>
            <span class="dep-briefing-tile-title">Was erwarte ich?</span>
            <span class="dep-briefing-tile-sub">Ziel, Erfolgskriterium</span>
          </button>
          <button type="button" class="dep-briefing-tile" onclick="prefillCaptureFromBriefing('erkenntnis','Risiken / offene Punkte:\\n- ')">
            <span class="dep-briefing-emoji">⚠️</span>
            <span class="dep-briefing-tile-title">Risiken &amp; Checks</span>
            <span class="dep-briefing-tile-sub">Was könnte schief gehen?</span>
          </button>
        </div>
      </div>`;
    return;
  }

  // STATUS „Durchgeführt" — Pulse-Card mit Eintrags-Zähler
  if (status === DEPLOYMENT_STATUS.DURCHGEFUEHRT) {
    const entryCountEl = document.getElementById('dep-capture-stream-list');
    const entryCount = entryCountEl
      ? entryCountEl.querySelectorAll('.capture-stream-item').length
      : 0;
    el.innerHTML = `
      <div class="dep-briefing-card dep-briefing-done">
        <div class="dep-briefing-head">
          <div class="dep-briefing-title">EINSATZ DURCHGEFÜHRT</div>
          <div class="dep-briefing-hint">${entryCount === 0
            ? 'Noch nichts protokolliert — wenigstens einen Stream-Eintrag erfassen.'
            : `${entryCount} Eintrag${entryCount === 1 ? '' : 'e'} im Stream. Action Items nicht vergessen.`}</div>
        </div>
        <div class="dep-briefing-actions">
          <button type="button" class="dep-briefing-action" onclick="document.getElementById('dep-capture-input')?.focus()">+ Stream-Eintrag</button>
          <button type="button" class="dep-briefing-action dep-briefing-action-ghost" onclick="addDeploymentActionItem()">+ Action Item</button>
        </div>
      </div>`;
    return;
  }

  // STATUS „Abgerechnet" — kompakte Read-only-Zusammenfassung
  if (status === DEPLOYMENT_STATUS.ABGERECHNET) {
    const datum  = d.datum_von ? formatDateDE(d.datum_von) : '—';
    const honor  = (d.menge != null && d.einzelpreis != null)
      ? formatPreis(Number(d.menge) * Number(d.einzelpreis))
      : '—';
    const rNr    = d.dokumentation?.rechnungsnummer || '—';
    el.innerHTML = `
      <div class="dep-briefing-card dep-briefing-billed">
        <div class="dep-briefing-head">
          <div class="dep-briefing-title">ABGERECHNET · ${esc(datum)}</div>
          <div class="dep-briefing-hint">Honorar ${esc(honor)} · Rechnung ${esc(rNr)}</div>
        </div>
      </div>`;
    return;
  }

  // Unbekannter / leerer Status — Karte verstecken
  el.innerHTML = '';
}

/** v2.14.2: Briefing-Tile-Klick — füllt Capture-Eingabe vor und setzt
 *  die passende Kategorie. */
function prefillCaptureFromBriefing(kategorie, text) {
  const input = document.getElementById('dep-capture-input');
  if (!input) return;
  // Inhalt nur ersetzen, wenn das Feld leer ist — sonst anhängen
  const existing = (input.value || '').trim();
  input.value = existing ? `${existing}\n\n${text}` : text;
  setCaptureKategorie(kategorie);
  input.focus();
  // Cursor ans Ende
  input.setSelectionRange(input.value.length, input.value.length);
}

async function toggleDeploymentReportTheme(deploymentId, themeId, checked) {
  if (checked) {
    await db.from('deployment_themes').insert({ deployment_id: deploymentId, theme_id: themeId });
  } else {
    await db.from('deployment_themes').delete()
      .eq('deployment_id', deploymentId).eq('theme_id', themeId);
  }
}

// ═══════════════════════════════════════════════════════════
//  v2.16.1 — THEMEN-QUICK-ADD am Einsatz-Bericht
// ═══════════════════════════════════════════════════════════
//
//  Spiegelt die Mechanik aus dem Projekt-Planung-Tab, ist aber
//  firmen-scoped: Suggestion-Quellen sind die Bibliothek UND
//  Firmen-Themen, die noch nicht im Einsatz getaggt sind.

let _depThemeQuickAddDebounce = null;

function onDeploymentThemeQuickInput(value) {
  if (_depThemeQuickAddDebounce) clearTimeout(_depThemeQuickAddDebounce);
  _depThemeQuickAddDebounce = setTimeout(() => _renderDepThemeQuickSuggestions(value || ''), 120);
}

async function _renderDepThemeQuickSuggestions(value) {
  const sugBox = document.getElementById('dep-theme-quickadd-suggestions');
  if (!sugBox) return;
  const q = (value || '').trim();
  if (q.length < 1) { sugBox.style.display = 'none'; sugBox.innerHTML = ''; return; }

  // Aktuellen Einsatz inkl. company_id holen + bereits getaggte Themen
  const depId = currentDeploymentDetailId;
  if (!depId) return;
  const { data: dep } = await db.from('deployments')
    .select('id, company_id').eq('id', depId).single();
  if (!dep?.company_id) {
    sugBox.innerHTML = '<div class="theme-suggestion-empty">Einsatz hat keine Firma — Quick-Add nicht möglich.</div>';
    sugBox.style.display = '';
    return;
  }
  const { data: tagged } = await db.from('deployment_themes')
    .select('theme_id').eq('deployment_id', depId);
  const taggedIds = new Set((tagged || []).map(r => r.theme_id));

  // 1) Firmen-Pool (project_themes der Firma, die noch nicht getaggt sind und Name matcht)
  const { data: companyRows } = await db.from('project_themes')
    .select('id, name, beschreibung, farbe, library_theme_id')
    .is('deleted_at', null).eq('company_id', dep.company_id)
    .ilike('name', `%${q}%`).limit(8);
  const companyHits = (companyRows || []).filter(t => !taggedIds.has(t.id)).slice(0, 4);

  // 2) Library-Pool (theme_library, die NICHT bereits als Firmen-Thema existieren)
  const companyLibIds = new Set((companyRows || []).map(r => r.library_theme_id).filter(Boolean));
  const { data: libRows } = await db.from('theme_library')
    .select('id, name, beschreibung, kategorie, farbe')
    .is('deleted_at', null).eq('ist_aktiv', true)
    .ilike('name', `%${q}%`).limit(8);
  const libHits = (libRows || []).filter(r => !companyLibIds.has(r.id)).slice(0, 4);

  if (companyHits.length === 0 && libHits.length === 0) {
    sugBox.innerHTML = `<div class="theme-suggestion-empty">Kein Treffer für „${esc(q)}" — Enter legt es als neues Firmen-Thema an.</div>`;
    sugBox.style.display = '';
    return;
  }
  // v2.33.5: data-* + Delegation statt String-Argumente im onclick (Phase A.3 #3).
  // r.name ist user-controlled (jeder darf Themen anlegen), Apostroph im Namen
  // brach das JS-String-Literal nach dem esc()→&#39;-Attribut-Decoding-Roundtrip.
  const companyHTML = companyHits.map(r => `
    <button type="button" class="theme-suggestion-item js-theme-sugg-company"
            data-theme-id="${esc(r.id)}"
            data-theme-name="${esc(r.name)}">
      <span class="theme-color-dot" style="background:${esc(r.farbe || '#1d4ed8')}"></span>
      <span class="theme-suggestion-body">
        <span class="theme-suggestion-name">${esc(r.name)}</span>
        <span class="theme-suggestion-cat">Firmen-Pool</span>
        ${r.beschreibung ? `<span class="theme-suggestion-desc">${esc(r.beschreibung)}</span>` : ''}
      </span>
    </button>`).join('');
  const libHTML = libHits.map(r => `
    <button type="button" class="theme-suggestion-item"
            onclick="addDeploymentThemeFromLibrary('${esc(r.id)}')">
      <span class="theme-color-dot" style="background:${esc(r.farbe || '#1d4ed8')}"></span>
      <span class="theme-suggestion-body">
        <span class="theme-suggestion-name">${esc(r.name)}</span>
        ${r.kategorie ? `<span class="theme-suggestion-cat">${esc(r.kategorie)} · Bibliothek</span>` : '<span class="theme-suggestion-cat">Bibliothek</span>'}
        ${r.beschreibung ? `<span class="theme-suggestion-desc">${esc(r.beschreibung)}</span>` : ''}
      </span>
    </button>`).join('');
  sugBox.innerHTML = companyHTML + libHTML;
  sugBox.style.display = '';
}

/** Firmen-Thema markieren (bereits vorhanden — nur deployment_themes-Junction). */
async function addDeploymentThemeFromCompany(themeId, name) {
  if (!currentDeploymentDetailId) return;
  const { error } = await db.from('deployment_themes')
    .insert({ deployment_id: currentDeploymentDetailId, theme_id: themeId });
  if (error && !/duplicate/i.test(error.message)) { showToast(error.message, true); return; }
  showToast(`„${name}" markiert.`);
  _clearDepThemeQuickInput();
  // Aktuelle Einsatz-Themen-Liste neu rendern
  const { data: d } = await db.from('deployments').select('id, company_id, project_id').eq('id', currentDeploymentDetailId).single();
  await renderDeploymentReportThemes(d);
}

/** Bibliotheks-Thema übernehmen: erst als Firmen-Thema anlegen (oder vorhandenes
 *  finden), dann am Einsatz markieren. */
async function addDeploymentThemeFromLibrary(libraryId) {
  if (!currentDeploymentDetailId) return;
  const { data: dep } = await db.from('deployments')
    .select('id, company_id, project_id').eq('id', currentDeploymentDetailId).single();
  if (!dep?.company_id) { showToast('Einsatz hat keine Firma.', true); return; }
  const { data: lib } = await db.from('theme_library')
    .select('id, name, beschreibung, farbe').eq('id', libraryId).single();
  if (!lib) { showToast('Bibliotheks-Thema nicht gefunden.', true); return; }

  // Firmen-Thema mit dieser library_theme_id schon vorhanden?
  const { data: exists } = await db.from('project_themes')
    .select('id').is('deleted_at', null)
    .eq('company_id', dep.company_id).eq('library_theme_id', lib.id).limit(1);
  let themeId = exists?.[0]?.id;
  if (!themeId) {
    const { data: ins, error } = await db.from('project_themes').insert({
      company_id:       dep.company_id,
      project_id:       dep.project_id || null,
      name:             lib.name,
      beschreibung:     lib.beschreibung,
      farbe:            lib.farbe,
      library_theme_id: lib.id,
      owner_id:         currentProfile?.id || null,
      reihenfolge:      100,
      status:           'offen'
    }).select('id').single();
    if (error) { showToast(error.message, true); return; }
    themeId = ins.id;
    // Falls Einsatz ein Projekt hat: auch ins Curriculum
    if (dep.project_id) {
      await db.from('project_theme_assignments').insert({
        project_id: dep.project_id, theme_id: themeId, reihenfolge: 100
      });
    }
  }
  await db.from('deployment_themes').insert({ deployment_id: dep.id, theme_id: themeId });
  showToast(`„${esc(lib.name)}" übernommen.`);
  _clearDepThemeQuickInput();
  invalidateThemesCache?.(dep.project_id);
  await renderDeploymentReportThemes(dep);
}

/** Ad-hoc-Thema anlegen — wird Firmen-Thema und sofort am Einsatz markiert. */
async function addDeploymentThemeAdHoc(value) {
  if (!currentDeploymentDetailId) return;
  const name = (value || '').trim();
  if (!name) { showToast('Bitte Thema-Namen eingeben.', true); return; }
  const { data: dep } = await db.from('deployments')
    .select('id, company_id, project_id').eq('id', currentDeploymentDetailId).single();
  if (!dep?.company_id) { showToast('Einsatz hat keine Firma — zuerst Firma zuweisen.', true); return; }
  // Dupe-Check innerhalb der Firma
  const { data: existing } = await db.from('project_themes')
    .select('id').is('deleted_at', null)
    .eq('company_id', dep.company_id).ilike('name', name);
  let themeId = existing?.[0]?.id;
  if (!themeId) {
    const { data: ins, error } = await db.from('project_themes').insert({
      company_id:  dep.company_id,
      project_id:  dep.project_id || null,
      name,
      owner_id:    currentProfile?.id || null,
      reihenfolge: 100,
      status:      'offen'
    }).select('id').single();
    if (error) { showToast(error.message, true); return; }
    themeId = ins.id;
    if (dep.project_id) {
      await db.from('project_theme_assignments').insert({
        project_id: dep.project_id, theme_id: themeId, reihenfolge: 100
      });
    }
  }
  await db.from('deployment_themes').insert({ deployment_id: dep.id, theme_id: themeId });
  showToast(`„${name}" angelegt und markiert.`);
  _clearDepThemeQuickInput();
  invalidateThemesCache?.(dep.project_id);
  await renderDeploymentReportThemes(dep);
}

function _clearDepThemeQuickInput() {
  const inp = document.getElementById('dep-theme-quickadd-input');
  if (inp) inp.value = '';
  const sug = document.getElementById('dep-theme-quickadd-suggestions');
  if (sug) { sug.style.display = 'none'; sug.innerHTML = ''; }
}

async function saveDeploymentDokuField(key, value) {
  if (!currentDeploymentDetailId) return;
  // v2.33.9: über _serializeDocUpdate (Race-Schutz, Phase A.2 #4).
  const id = currentDeploymentDetailId;
  try {
    await _serializeDocUpdate('deployments', id, (dok) => {
      dok[key] = (value || '').trim();
    });
  } catch (err) {
    showToast('Speichern fehlgeschlagen: ' + err.message, true);
  }
}

async function renderDeploymentActionItems(deploymentId) {
  const wrap = document.getElementById('dep-action-items');
  const counter = document.getElementById('dep-action-count');
  if (!wrap) return;
  const { data, error } = await db.from('tasks')
    .select('id, titel, status, faelligkeit, assigned_to, user:user_profiles!tasks_assigned_to_fkey(name)')
    .is('deleted_at', null).eq('deployment_id', deploymentId)
    .order('created_at', { ascending: true });
  if (error) { wrap.innerHTML = `<div class="info-card-empty">Fehler: ${esc(error.message)}</div>`; return; }
  if (counter) counter.textContent = (data || []).length;
  if (!data || data.length === 0) {
    wrap.innerHTML = '<div class="info-card-empty">Keine Action Items. „+ Aufgabe" oben fügt eine hinzu — wird in der Aufgaben-Liste mit Verknüpfung zu diesem Einsatz sichtbar.</div>';
    return;
  }
  wrap.innerHTML = data.map(t => `
    <label class="proj-criterion ${t.status === 'erledigt' ? 'is-done' : ''}">
      <input type="checkbox" ${t.status === 'erledigt' ? 'checked' : ''}
             onchange="toggleDeploymentActionItem('${esc(t.id)}', this.checked)">
      <span class="proj-criterion-text">${esc(t.titel)}</span>
      <span class="proj-criterion-meta">
        ${t.faelligkeit ? esc(formatDateCompact(t.faelligkeit)) : ''}
        ${t.user?.name ? '· ' + esc(t.user.name) : ''}
      </span>
    </label>`).join('');
}

/** v2.0.2: Öffnet das Aufgabe-Drawer mit deployment_id vorbelegt (Action Item).
 *  project_id und company_id werden aus dem aktuellen Einsatz geerbt, damit der
 *  Bezug konsistent bleibt. Nach dem Speichern aktualisiert _refreshTaskContext
 *  die Action-Items-Liste automatisch (siehe Hash-Branch für #/einsatz/). */
async function addDeploymentActionItem() {
  if (!currentDeploymentDetailId) return;
  // Bezüge aus dem aktuellen Einsatz übernehmen
  const { data: d } = await db.from('deployments')
    .select('project_id, company_id')
    .eq('id', currentDeploymentDetailId).single();

  taskModalPrefillDeploymentId = currentDeploymentDetailId;
  if (d?.company_id) taskModalPrefillCompanyId = d.company_id;
  if (d?.project_id) taskModalPrefillProjectId = d.project_id;

  await openTaskModal('new');
}

async function toggleDeploymentActionItem(taskId, done) {
  const payload = done
    ? { status: 'erledigt', erledigt_am: new Date().toISOString() }
    : { status: 'offen', erledigt_am: null };
  await db.from('tasks').update(payload).eq('id', taskId);
  await renderDeploymentActionItems(currentDeploymentDetailId);
}

function uploadDeploymentAttachment(files) {
  if (!files || files.length === 0) return;
  showToast('Datei-Anhänge kommen in Phase 9 (Storage-Sub-Spec). Bis dahin: extern speichern und in der Notiz verlinken.', false);
}

// ═══════════════════════════════════════════════════════════
//  v2.15.2 — STATUS-WEITERBRINGEN (Primary Action je Detail-Seite)
// ═══════════════════════════════════════════════════════════

/** Status-Flow je Entität. `current → next` als geordnete Kette.
 *  Werte müssen 1:1 mit `lookup_values` und mit den im Code referenzierten
 *  Strings übereinstimmen. */
const _STATUS_FLOW = {
  project: {
    table: 'projects',
    kategorie: 'projekt_status',
    order:    [PROJECT_STATUS.LEAD, PROJECT_STATUS.ANGEBOT, PROJECT_STATUS.IN_ARBEIT, PROJECT_STATUS.ABSCHLUSSPHASE, PROJECT_STATUS.ABGESCHLOSSEN],
    terminal: [PROJECT_STATUS.ABGESCHLOSSEN, PROJECT_STATUS.VERLOREN]
  },
  deployment: {
    table: 'deployments',
    kategorie: 'einsatz_status',
    order:    [DEPLOYMENT_STATUS.GEPLANT, DEPLOYMENT_STATUS.DURCHGEFUEHRT, DEPLOYMENT_STATUS.ABGERECHNET],
    terminal: [DEPLOYMENT_STATUS.ABGERECHNET, DEPLOYMENT_STATUS.STORNIERT]
  },
  appointment: {
    table: 'appointments',
    kategorie: 'termin_status',
    order:    [APPOINTMENT_STATUS.GEPLANT, APPOINTMENT_STATUS.DURCHGEFUEHRT],
    terminal: [APPOINTMENT_STATUS.DURCHGEFUEHRT]
  }
};

function _statusFlowNext(entityType, currentStatus) {
  const flow = _STATUS_FLOW[entityType];
  if (!flow) return null;
  const sysKey = currentStatus;
  const idx = flow.order.indexOf(sysKey);
  if (idx < 0 || idx === flow.order.length - 1) return null;
  return flow.order[idx + 1];
}

/** Rendert den „→ {NächsterStatus}"-Button in den passenden Container im
 *  Aktionen-Bereich. Bei Terminal-Status: kompakte Anzeige (kein Button).
 *  Bei abweichendem Status (z. B. Verloren / Storniert): ebenfalls ohne
 *  Button — der Pfad ist abgeschlossen. */
function renderStatusAdvanceAction(entityType, entityId, currentStatus, containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const flow = _STATUS_FLOW[entityType];
  if (!flow) { el.innerHTML = ''; return; }

  const next = _statusFlowNext(entityType, currentStatus);
  const currentLabel = getStatusLabel(flow.kategorie, currentStatus, currentStatus);
  if (!next) {
    const isTerminal = flow.terminal.includes(currentStatus);
    el.innerHTML = isTerminal
      ? `<div class="proj-status-action-done">Status: <strong>${esc(currentLabel)}</strong></div>`
      : '';
    return;
  }
  const nextLabel = getStatusLabel(flow.kategorie, next, next);
  el.innerHTML = `
    <button class="proj-action proj-action-primary"
            onclick="advanceEntityStatus('${esc(entityType)}','${esc(entityId)}','${esc(currentStatus)}','${esc(next)}')"
            title="Aktueller Status: ${esc(currentLabel)} — Klick setzt auf „${esc(nextLabel)}".">
      → ${esc(nextLabel)}
    </button>`;
}

/** Setzt den Status der Entität auf den nächsten Wert und löst ein Refresh
 *  der jeweiligen Detail-Page aus. Die `from`-Bedingung verhindert Race-
 *  Conditions bei Doppelklick / parallelen Tabs.
 *
 *  v2.33.1: ruft `checkAndUpdateProjectStatus` für deployment/appointment,
 *  damit das Eltern-Projekt nach einem Status-Vorrück-Klick mitwandert
 *  (Phase-A.4-Trigger-Lücke #2). */
async function advanceEntityStatus(entityType, entityId, fromStatus, toStatus) {
  const flow = _STATUS_FLOW[entityType];
  if (!flow || !entityId || !toStatus) return;
  const fromLabel = getStatusLabel(flow.kategorie, fromStatus, fromStatus);
  const toLabel   = getStatusLabel(flow.kategorie, toStatus,   toStatus);
  if (!confirm(`Status weiterbringen?\n\n${fromLabel}  →  ${toLabel}`)) return;

  let projectId = null;
  if (entityType === 'deployment' || entityType === 'appointment') {
    const sel = entityType === 'deployment' ? 'project_id, datum_von, datum_bis' : 'project_id';
    const { data: row } = await db.from(flow.table).select(sel).eq('id', entityId).maybeSingle();
    projectId = row?.project_id || null;
    // v2.33.14: Einsatz nur mit Datum auf durchgeführt/abgerechnet (Phase B #2)
    if (entityType === 'deployment'
        && !ensureDeploymentDatumForStatus(toStatus, !!(row?.datum_von || row?.datum_bis))) return;
  }

  const { error } = await db.from(flow.table)
    .update({ status: toStatus }).in('status', [fromStatus]).eq('id', entityId);
  if (error) { showToast(error.message, true); return; }
  // v2.33.17 (Phase A.1 #5): gekoppelten Termin mitziehen (nur Einsatz)
  if (entityType === 'deployment') await syncCoupledAppointmentStatus(entityId, toStatus);
  showToast(`Status: ${toLabel}.`);
  if (projectId) await checkAndUpdateProjectStatus(projectId);
  if (entityType === 'project'    && currentProjectDetailId)    loadProjectDetail(currentProjectDetailId);
  if (entityType === 'deployment' && currentDeploymentDetailId) loadDeploymentDetail(currentDeploymentDetailId);
  if (entityType === 'appointment'&& currentAppointmentDetailId) loadAppointmentDetail(currentAppointmentDetailId);
}

// ═══════════════════════════════════════════════════════════
//  v2.15.3 — STATUS-PICKER (Klick auf Status-Pille)
// ═══════════════════════════════════════════════════════════

/** Lookup-Kategorie je Entitäts-Typ */
const _STATUS_LOOKUP_CAT = {
  project:     'projekt_status',
  deployment:  'einsatz_status',
  appointment: 'termin_status'
};

const _statusOptionsCache = {};

async function _loadStatusOptions(entityType) {
  if (_statusOptionsCache[entityType]) return _statusOptionsCache[entityType];
  const cat = _STATUS_LOOKUP_CAT[entityType];
  if (!cat) return [];
  // v2.33.1: system_key MUSS mit selectiert werden — er ist seit v2.31 die
  // Identitäts-Spalte für Status, `wert` ist nur das Anzeige-Label.
  const { data, error } = await db.from('lookup_values')
    .select('id, system_key, wert, farbe, reihenfolge')
    .eq('kategorie', cat).eq('ist_aktiv', true).order('reihenfolge');
  if (error) return [];
  // Defensive: nur Optionen mit system_key durchlassen — alte Mandanten-Daten
  // ohne system_key würden sonst NULL als Status in die DB schreiben.
  _statusOptionsCache[entityType] = (data || []).filter(o => o.system_key);
  return _statusOptionsCache[entityType];
}

/** Click-Handler für die Status-Pille: öffnet (oder schließt) das Popup
 *  mit allen erlaubten Status-Werten direkt unter der Pille. */
async function toggleStatusPicker(entityType, anchorEl) {
  // Schließe alle anderen offenen Picker
  document.querySelectorAll('.status-pill-popup').forEach(p => {
    if (!p.id.startsWith(_statusPopupIdFromAnchor(anchorEl))) p.style.display = 'none';
  });

  const popupId = anchorEl.id.replace('-pill', '-popup');
  const popup = document.getElementById(popupId);
  if (!popup) return;
  if (popup.style.display !== 'none' && popup.dataset.openFor === anchorEl.id) {
    popup.style.display = 'none'; popup.dataset.openFor = ''; return;
  }

  const entityId      = anchorEl.dataset.entityId;
  const currentStatus = anchorEl.dataset.currentStatus;
  const options = await _loadStatusOptions(entityType);
  if (options.length === 0) {
    popup.innerHTML = '<div class="status-pill-popup-empty">Keine Status-Werte hinterlegt.</div>';
  } else {
    // v2.33.5: data-* + Delegation statt String-Argumenten im onclick
    // (Phase A.3 #2 — Status-Pillen sind in jeder Liste der App präsent,
    // war der breiteste XSS-Vektor). v2.33.1 hatte schon system_key statt
    // wert als Argument — jetzt zusätzlich der Bypass-Pfad geschlossen.
    // Anzeige-Label bleibt o.wert (mandantenfähig umbenennbar).
    popup.innerHTML = options.map(o => {
      const isCurrent = o.system_key === currentStatus;
      const farbe = o.farbe || 'var(--muted)';
      return `
        <button type="button" class="status-pill-popup-item ${isCurrent ? 'is-current' : ''}"
                data-entity-type="${esc(entityType)}"
                data-entity-id="${esc(entityId)}"
                data-new-status="${esc(o.system_key)}"
                data-current-status="${esc(currentStatus)}">
          <span class="status-pill-popup-dot" style="background:${esc(farbe)}"></span>
          <span class="status-pill-popup-label">${esc(o.wert)}</span>
          ${isCurrent ? '<span class="status-pill-popup-check">✓</span>' : ''}
        </button>`;
    }).join('');
  }
  popup.style.display = '';
  popup.dataset.openFor = anchorEl.id;
}

function _statusPopupIdFromAnchor(anchorEl) {
  return (anchorEl?.id || '').replace('-pill', '-popup').split('-')[0];
}

/** Schließt alle Status-Picker, wenn außerhalb geklickt wird. */
document.addEventListener('click', (ev) => {
  if (ev.target.closest('.status-pill-clickable, .status-pill-popup')) return;
  document.querySelectorAll('.status-pill-popup').forEach(p => {
    p.style.display = 'none'; p.dataset.openFor = '';
  });
}, true);

/** Wählt einen Status aus dem Picker — gleicher Update-Pfad wie
 *  advanceEntityStatus, aber freie Wahl (auch Rückwärts / Storniert /
 *  Verloren). Confirm bestätigt den Sprung; Race-Schutz via from-Status.
 *
 *  v2.33.1: `newStatus` ist jetzt ein system_key (vorher Label) — der Picker
 *  reicht in `toggleStatusPicker` `o.system_key` durch. Außerdem: bei
 *  deployment/appointment wird die `project_id` vor dem Update geholt und
 *  nach erfolgreicher Persistierung `checkAndUpdateProjectStatus(...)`
 *  aufgerufen, damit das Eltern-Projekt mitwandert (Cluster-1-Trigger-Lücke
 *  aus Phase A.4 #2). */
async function selectEntityStatus(entityType, entityId, newStatus, currentStatus) {
  if (!entityType || !entityId || !newStatus) return;
  // Picker schließen
  const popup = document.getElementById(entityType === 'project' ? 'project-status-popup'
                                     : entityType === 'deployment' ? 'dep-status-popup'
                                     : 'appt-status-popup');
  if (popup) { popup.style.display = 'none'; popup.dataset.openFor = ''; }

  if (newStatus === currentStatus) return; // No-op
  const flow = _STATUS_FLOW[entityType];
  const table = flow?.table;
  if (!table) return;
  const currentLabel = getStatusLabel(flow.kategorie, currentStatus, currentStatus);
  const newLabel     = getStatusLabel(flow.kategorie, newStatus,     newStatus);
  if (!confirm(`Status ändern?\n\n${currentLabel}  →  ${newLabel}`)) return;

  // Vor dem Update project_id holen — wird nach Save für Auto-Projektstatus
  // gebraucht. Project-Entity selbst hat kein Eltern-Projekt.
  let projectId = null;
  if (entityType === 'deployment' || entityType === 'appointment') {
    const sel = entityType === 'deployment' ? 'project_id, datum_von, datum_bis' : 'project_id';
    const { data: row } = await db.from(table).select(sel).eq('id', entityId).maybeSingle();
    projectId = row?.project_id || null;
    // v2.33.14: Einsatz nur mit Datum auf durchgeführt/abgerechnet (Phase B #2)
    if (entityType === 'deployment'
        && !ensureDeploymentDatumForStatus(newStatus, !!(row?.datum_von || row?.datum_bis))) return;
  }

  // Race-Schutz: from-Bedingung als Status-Filter, damit Doppelklicks /
  // parallele Tabs nicht doppelt schreiben.
  const { error } = await db.from(table)
    .update({ status: newStatus }).in('status', [currentStatus]).eq('id', entityId);
  if (error) { showToast(error.message, true); return; }
  // v2.33.17 (Phase A.1 #5): gekoppelten Termin mitziehen (nur Einsatz)
  if (entityType === 'deployment') await syncCoupledAppointmentStatus(entityId, newStatus);
  showToast(`Status: ${newLabel}.`);
  if (projectId) await checkAndUpdateProjectStatus(projectId);
  if (entityType === 'project'    && currentProjectDetailId)    loadProjectDetail(currentProjectDetailId);
  if (entityType === 'deployment' && currentDeploymentDetailId) loadDeploymentDetail(currentDeploymentDetailId);
  if (entityType === 'appointment'&& currentAppointmentDetailId) loadAppointmentDetail(currentAppointmentDetailId);
}

// ═══════════════════════════════════════════════════════════
//  v2.0.3 — WORKFLOW-CHECKLISTEN (Punkt 9)
//  Vorbereitung / Dokumentation als Schritt-für-Schritt-Tab pro Detail-Page.
//  State liegt in der jsonb-Spalte workflow_state (Migration v2.0.3) der
//  jeweiligen Tabelle, Definition der Schritte ist hier hartcodiert — sie
//  ändern sich selten und sind eng an die UI-Texte gekoppelt.
// ═══════════════════════════════════════════════════════════

const WORKFLOW_STEPS = {
  appointment_prepare: {
    title: 'Termin vorbereiten',
    completedLabel: 'Vorbereitet',
    intro: 'Vor dem Termin abhaken, was bereits erledigt ist.',
    steps: [
      { id: 'anfahrt',     label: 'Anfahrt / Zugangsdaten geprüft' },
      { id: 'teilnehmer',  label: 'Teilnehmer bestätigt (Antwort liegt vor)' },
      { id: 'unterlagen',  label: 'Unterlagen versendet' },
      { id: 'agenda',      label: 'Agenda gesetzt' }
    ]
  },
  deployment_document: {
    title: 'Einsatz dokumentieren',
    completedLabel: 'Dokumentiert',
    intro: 'Nach dem Einsatz abhaken, was im Bericht festgehalten ist.',
    steps: [
      { id: 'themen',          label: 'Behandelte Themen erfasst' },
      { id: 'teilnehmer',      label: 'Teilnehmer notiert' },
      { id: 'erkenntnisse',    label: 'Erkenntnisse festgehalten' },
      { id: 'folgemassnahmen', label: 'Folgemaßnahmen abgeleitet' },
      { id: 'status_done',     label: 'Status auf „Durchgeführt" gesetzt' }
    ]
  },
  project_prepare: {
    title: 'Projekt vorbereiten',
    completedLabel: 'Vorbereitet',
    intro: 'Beim Anlegen / vor dem Kickoff abhaken, was geklärt ist.',
    steps: [
      { id: 'ziel',             label: 'Ziel / Kundenherausforderung formuliert' },
      { id: 'erfolgskriterien', label: 'Erfolgskriterien definiert' },
      { id: 'themen',           label: 'Themen festgelegt' },
      { id: 'aktivitaeten',     label: 'Erste Termine / Einsätze eingeplant' }
    ]
  }
};

const WORKFLOW_TABLE_MAP = {
  appointment: 'appointments',
  deployment:  'deployments',
  project:     'projects'
};

/** v2.13.0: Welche Entity-Typen haben eine eigene `workflow_steps`-Spalte?
 *  Projekt und Einsatz dürfen ihre Checklisten projekt-/einsatz-spezifisch
 *  pflegen; Termin nutzt weiterhin die WORKFLOW_STEPS-Konstante als
 *  Default (kann später nachgezogen werden). */
const WORKFLOW_HAS_STEPS_COLUMN = { project: true, deployment: true, appointment: false };

/** v2.13.0: Holt die Schritt-Liste für eine konkrete Entität. Bei Projekt/
 *  Einsatz aus der `workflow_steps`-Spalte; bei Termin (oder fehlenden Daten)
 *  Fallback auf WORKFLOW_STEPS[workflowKey].steps. */
async function _loadWorkflowSteps(workflowKey, entityType, entityId, prefetchedSteps) {
  const fallback = WORKFLOW_STEPS[workflowKey]?.steps || [];
  if (!WORKFLOW_HAS_STEPS_COLUMN[entityType]) return fallback;
  if (Array.isArray(prefetchedSteps) && prefetchedSteps.length > 0) return prefetchedSteps;
  const table = WORKFLOW_TABLE_MAP[entityType];
  if (!table || !entityId) return fallback;
  const { data, error } = await db.from(table)
    .select('workflow_steps').eq('id', entityId).single();
  if (error) return fallback;
  const stored = data?.workflow_steps;
  if (Array.isArray(stored) && stored.length > 0) return stored;
  return fallback;
}

/** Ist die Workflow-Checkliste vollständig? — v2.13.0 nimmt die Schritt-
 *  Definition als Parameter, da sie pro Entität variieren kann. */
function _isWorkflowCompleteForSteps(steps, state) {
  if (!Array.isArray(steps) || steps.length === 0 || !state) return false;
  return steps.every(s => !!state[s.id]);
}
function _isWorkflowComplete(workflowKey, state) {
  const def = WORKFLOW_STEPS[workflowKey];
  if (!def || !state) return false;
  return def.steps.every(s => !!state[s.id]);
}

/** Lädt den workflow_state aus der DB für eine Entität. */
async function _loadWorkflowState(entityType, entityId) {
  const table = WORKFLOW_TABLE_MAP[entityType];
  if (!table || !entityId) return {};
  const { data, error } = await db.from(table)
    .select('workflow_state').eq('id', entityId).single();
  if (error) return {};
  return data?.workflow_state || {};
}

/** Schreibt eine Step-Änderung in den jsonb-State zurück. */
async function _saveWorkflowStep(entityType, entityId, workflowKey, stepId, checked) {
  const table = WORKFLOW_TABLE_MAP[entityType];
  if (!table || !entityId) return;
  const state = await _loadWorkflowState(entityType, entityId);
  if (!state[workflowKey]) state[workflowKey] = {};
  state[workflowKey][stepId] = !!checked;
  const { error } = await db.from(table).update({ workflow_state: state }).eq('id', entityId);
  if (error) { showToast('Fehler: ' + error.message, true); return null; }
  return state;
}

/** v2.13.0: Persistiert ein neues Schritt-Array in workflow_steps. */
async function _saveWorkflowSteps(entityType, entityId, steps) {
  const table = WORKFLOW_TABLE_MAP[entityType];
  if (!table || !entityId || !WORKFLOW_HAS_STEPS_COLUMN[entityType]) return false;
  const clean = (Array.isArray(steps) ? steps : []).map((s, i) => ({
    id: (s.id || `step_${i}_${Date.now().toString(36)}`).toString(),
    label: (s.label || '').toString().trim(),
    required: s.required !== false
  })).filter(s => s.label);
  const { error } = await db.from(table).update({ workflow_steps: clean }).eq('id', entityId);
  if (error) { showToast('Fehler: ' + error.message, true); return false; }
  return true;
}

/** Edit-State pro Container: ist der Editor offen? Workflow-Bearbeitungs-Buffer. */
const _workflowEditState = new Map(); // containerId → { steps, workflowKey, entityType, entityId, pillId }

/** Rendert die Checkliste in `containerId` und befüllt die Hero-Pille
 *  `pillId` (optional), wenn alle Schritte abgehakt sind.
 *  v2.0.4: `prefetchedState` (optional) erlaubt es dem Caller, den schon
 *  geladenen workflow_state aus dem Detail-Page-SELECT durchzureichen, um
 *  einen extra Roundtrip beim Hero-Pre-Render zu sparen.
 *  v2.13.0: Schritt-Liste kommt nicht mehr aus der WORKFLOW_STEPS-Konstante,
 *  sondern aus der `workflow_steps`-Spalte der Entität (mit Fallback). */
async function renderWorkflowChecklist(workflowKey, entityType, entityId, containerId, pillId, prefetchedState, prefetchedSteps) {
  const container = document.getElementById(containerId);
  if (!container) return;
  const def = WORKFLOW_STEPS[workflowKey];
  if (!def) { container.innerHTML = ''; return; }

  const state = prefetchedState !== undefined
    ? (prefetchedState || {})
    : await _loadWorkflowState(entityType, entityId);
  const wfState = state[workflowKey] || {};

  const steps = await _loadWorkflowSteps(workflowKey, entityType, entityId, prefetchedSteps);
  const done = steps.filter(s => wfState[s.id]).length;
  const total = steps.length;
  const allDone = total > 0 && done === total;
  const canEdit = WORKFLOW_HAS_STEPS_COLUMN[entityType];

  const isEditing = _workflowEditState.has(containerId);
  if (isEditing) {
    container.innerHTML = _renderWorkflowEditor(containerId);
    return;
  }

  container.innerHTML = `
    <div class="workflow-checklist">
      <div class="workflow-head">
        <div class="workflow-title">${esc(def.title)}</div>
        <div class="workflow-head-meta">
          <span class="workflow-progress">${done} / ${total}${allDone ? ` · <strong>${esc(def.completedLabel)}</strong>` : ''}</span>
          ${canEdit ? `<button type="button" class="workflow-edit-btn"
                          onclick="openWorkflowEditor('${esc(workflowKey)}','${esc(entityType)}','${esc(entityId)}','${esc(containerId)}','${esc(pillId || '')}')"
                          title="Schritte bearbeiten">Schritte bearbeiten</button>` : ''}
        </div>
      </div>
      <div class="workflow-intro">${esc(def.intro)}</div>
      <div class="workflow-steps">
        ${steps.map(s => `
          <label class="workflow-step ${wfState[s.id] ? 'is-done' : ''}">
            <input type="checkbox" ${wfState[s.id] ? 'checked' : ''}
                   onchange="onWorkflowStepToggle('${esc(workflowKey)}','${esc(entityType)}','${esc(entityId)}','${esc(s.id)}',this.checked,'${esc(containerId)}','${esc(pillId || '')}')">
            <span class="workflow-step-label">${esc(s.label)}</span>
          </label>`).join('')}
        ${steps.length === 0 ? '<div class="info-card-empty" style="padding:10px">Noch keine Schritte. Klicke oben auf „Schritte bearbeiten".</div>' : ''}
      </div>
    </div>`;

  // Hero-Pille toggeln (wenn vorhanden)
  if (pillId) {
    const pill = document.getElementById(pillId);
    if (pill) {
      pill.style.display = allDone ? '' : 'none';
      pill.textContent = '✓ ' + def.completedLabel;
    }
  }
}

/** Handler für ⏰ Klick auf Step-Checkbox. */
async function onWorkflowStepToggle(workflowKey, entityType, entityId, stepId, checked, containerId, pillId) {
  await _saveWorkflowStep(entityType, entityId, workflowKey, stepId, checked);
  // Re-render mit aktualisiertem State (für Progress-Counter und Hero-Pille)
  await renderWorkflowChecklist(workflowKey, entityType, entityId, containerId, pillId);
}

// ───────── v2.13.0: Inline-Editor für Workflow-Schritte ─────────

async function openWorkflowEditor(workflowKey, entityType, entityId, containerId, pillId) {
  if (!WORKFLOW_HAS_STEPS_COLUMN[entityType]) return;
  const steps = await _loadWorkflowSteps(workflowKey, entityType, entityId);
  _workflowEditState.set(containerId, {
    workflowKey, entityType, entityId, pillId,
    steps: steps.map(s => ({ ...s }))   // deep-ish copy
  });
  await renderWorkflowChecklist(workflowKey, entityType, entityId, containerId, pillId);
}

function _renderWorkflowEditor(containerId) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx) return '';
  const def = WORKFLOW_STEPS[ctx.workflowKey];
  return `
    <div class="workflow-checklist workflow-checklist-edit">
      <div class="workflow-head">
        <div class="workflow-title">${esc(def?.title || 'Schritte')} · Bearbeiten</div>
        <div class="workflow-head-meta">
          <button type="button" class="workflow-edit-btn workflow-edit-btn-secondary"
                  onclick="cancelWorkflowEditor('${esc(containerId)}')">Abbrechen</button>
          <button type="button" class="workflow-edit-btn workflow-edit-btn-primary"
                  onclick="saveWorkflowEditor('${esc(containerId)}')">Speichern</button>
        </div>
      </div>
      <div class="workflow-intro">${esc(def?.intro || '')}</div>
      <div class="workflow-edit-list">
        ${ctx.steps.map((s, i) => `
          <div class="workflow-edit-row" data-step-idx="${i}">
            <button type="button" class="workflow-edit-move" title="Nach oben"
                    onclick="moveWorkflowStep('${esc(containerId)}',${i},-1)" ${i === 0 ? 'disabled' : ''}>↑</button>
            <button type="button" class="workflow-edit-move" title="Nach unten"
                    onclick="moveWorkflowStep('${esc(containerId)}',${i},1)" ${i === ctx.steps.length - 1 ? 'disabled' : ''}>↓</button>
            <input type="text" class="workflow-edit-label" value="${esc(s.label || '')}"
                   placeholder="Schritt-Beschreibung"
                   oninput="updateWorkflowStepField('${esc(containerId)}',${i},'label',this.value)">
            <label class="workflow-edit-required" title="Erforderlich">
              <input type="checkbox" ${s.required !== false ? 'checked' : ''}
                     onchange="updateWorkflowStepField('${esc(containerId)}',${i},'required',this.checked)"> Pflicht
            </label>
            <button type="button" class="workflow-edit-remove" title="Entfernen"
                    onclick="removeWorkflowStep('${esc(containerId)}',${i})">×</button>
          </div>`).join('')}
      </div>
      <button type="button" class="workflow-edit-add"
              onclick="addWorkflowStep('${esc(containerId)}')">+ Schritt hinzufügen</button>
    </div>`;
}

function addWorkflowStep(containerId) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx) return;
  ctx.steps.push({ id: `step_${Date.now().toString(36)}_${ctx.steps.length}`, label: '', required: true });
  document.getElementById(containerId).innerHTML = _renderWorkflowEditor(containerId);
}

function removeWorkflowStep(containerId, idx) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx) return;
  ctx.steps.splice(idx, 1);
  document.getElementById(containerId).innerHTML = _renderWorkflowEditor(containerId);
}

function moveWorkflowStep(containerId, idx, delta) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx) return;
  const target = idx + delta;
  if (target < 0 || target >= ctx.steps.length) return;
  const tmp = ctx.steps[idx];
  ctx.steps[idx] = ctx.steps[target];
  ctx.steps[target] = tmp;
  document.getElementById(containerId).innerHTML = _renderWorkflowEditor(containerId);
}

function updateWorkflowStepField(containerId, idx, field, value) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx || !ctx.steps[idx]) return;
  ctx.steps[idx][field] = value;
}

async function saveWorkflowEditor(containerId) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx) return;
  const ok = await _saveWorkflowSteps(ctx.entityType, ctx.entityId, ctx.steps);
  if (!ok) return;
  showToast('Schritte aktualisiert.');
  _workflowEditState.delete(containerId);
  await renderWorkflowChecklist(ctx.workflowKey, ctx.entityType, ctx.entityId, containerId, ctx.pillId);
}

function cancelWorkflowEditor(containerId) {
  const ctx = _workflowEditState.get(containerId);
  if (!ctx) return;
  _workflowEditState.delete(containerId);
  renderWorkflowChecklist(ctx.workflowKey, ctx.entityType, ctx.entityId, containerId, ctx.pillId);
}

