// v2.4.1: Encoding-Erkennung. Reihenfolge: BOM-Check → UTF-8 versuchen →
// Heuristik Win-1252 vs. Mac-Roman anhand typischer deutscher Umlaut-Bytes.
// v2.4.3: Mac-Roman-Heuristik ergänzt — Excel-Mac speichert CSV oft so,
// und Win-1252 als Fallback war zu pauschal: ä in Mac-Roman ist 0x8A
// (in Win-1252 = Š), ü ist 0x9F (Ÿ), ß ist 0xA7 (§).
const _DE_UMLAUT_BYTES_WIN1252 = new Set([0xE4, 0xF6, 0xFC, 0xDF, 0xC4, 0xD6, 0xDC]);
const _DE_UMLAUT_BYTES_MACROMAN = new Set([0x8A, 0x9A, 0x9F, 0xA7, 0x80, 0x85, 0x86]);

function _detectEncoding(bytes) {
  if (bytes.length >= 3 && bytes[0] === 0xEF && bytes[1] === 0xBB && bytes[2] === 0xBF) return 'utf-8';
  if (bytes.length >= 2 && bytes[0] === 0xFF && bytes[1] === 0xFE) return 'utf-16le';
  if (bytes.length >= 2 && bytes[0] === 0xFE && bytes[1] === 0xFF) return 'utf-16be';
  // Probe als UTF-8 — wenn das Replacement-Char (U+FFFD) auftaucht,
  // war's keine UTF-8.
  try {
    const utf8 = new TextDecoder('utf-8', { fatal: false }).decode(bytes);
    if (utf8.indexOf('�') === -1) return 'utf-8';
  } catch {}
  // Heuristik: zähle typische deutsche Umlaut-Bytes für beide Encodings.
  // Wer mehr hat, wird gewählt. Bei Gleichstand: Win-1252 (häufiger).
  let win = 0, mac = 0;
  for (let i = 0; i < bytes.length; i++) {
    if (_DE_UMLAUT_BYTES_WIN1252.has(bytes[i])) win++;
    else if (_DE_UMLAUT_BYTES_MACROMAN.has(bytes[i])) mac++;
  }
  if (mac > win) return 'macintosh';
  return 'windows-1252';
}

function _decodeBuffer(buffer, encoding) {
  let bytes = new Uint8Array(buffer);
  // BOM bei UTF-8 abschneiden, sonst landet sie als unsichtbares Zeichen am Anfang
  if (encoding === 'utf-8' && bytes.length >= 3 && bytes[0] === 0xEF && bytes[1] === 0xBB && bytes[2] === 0xBF) {
    bytes = bytes.subarray(3);
  }
  return new TextDecoder(encoding).decode(bytes);
}

function _detectSeparator(firstLine) {
  const cands = [';', ',', '\t', '|'];
  let best = ',', bestCount = 0;
  cands.forEach(c => {
    const re = c === '\t' ? /\t/g : new RegExp('\\' + c, 'g');
    const count = (firstLine.match(re) || []).length;
    if (count > bestCount) { bestCount = count; best = c; }
  });
  return best;
}

// Mini-RFC4180-konformer CSV-Parser (Quotes mit Doppel-Quote-Escape).
// v2.4.2: Newline-Normalisierung vorab — `\r\n` und einzelnes `\r`
// (Mac-Classic / alte Excel-Mac-Exporte) werden zu `\n`. Sonst landet
// die ganze Datei als eine lange Zeile.
function _parseCSV(text, sep) {
  text = text.replace(/\r\n?/g, '\n');
  const rows = [];
  let cur = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i+1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else {
      if (c === '"' && field === '') inQuotes = true;
      else if (c === sep) { cur.push(field); field = ''; }
      else if (c === '\n') { cur.push(field); rows.push(cur); cur = []; field = ''; }
      else field += c;
    }
  }
  if (field !== '' || cur.length > 0) { cur.push(field); rows.push(cur); }
  // letzte leere Zeile entfernen wenn nur ein leeres Feld
  while (rows.length > 0 && rows[rows.length-1].length === 1 && rows[rows.length-1][0] === '') rows.pop();
  return rows;
}

function _normalizeHeader(h) {
  return (h || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '');
}

// v2.6.5: returnt Array<string[]> — bei Auto-Map wird pro Spalte 0 oder 1 Match gefunden,
// User kann manuell weitere hinzufügen.
function _autoMapHeaders(headers, fields) {
  return headers.map(h => {
    const norm = _normalizeHeader(h);
    if (!norm) return [];
    for (const f of fields) {
      if (_normalizeHeader(f.key) === norm) return [f.key];
      if (_normalizeHeader(f.label) === norm) return [f.key];
      for (const a of (f.aliases || [])) {
        if (_normalizeHeader(a) === norm) return [f.key];
      }
    }
    return [];
  });
}

async function onImportFileChosen(ev) {
  const file = ev.target.files?.[0];
  if (!file) return;
  _importState.file = file;
  _importState.buffer = await file.arrayBuffer();  // v2.4.1: behält Bytes für Encoding-Wechsel
  _decodeAndParse();
}

function reparseImportFile() {
  if (!_importState.buffer) return;
  _decodeAndParse();
}

function _decodeAndParse() {
  const encChoice = document.getElementById('import-encoding').value;
  const bytes = new Uint8Array(_importState.buffer);
  const enc = encChoice === 'auto' ? _detectEncoding(bytes) : encChoice;
  _importState.encoding = enc;
  _importState.rawText = _decodeBuffer(_importState.buffer, enc);
  _parseCurrentImportFile();
}

function _parseCurrentImportFile() {
  const sepChoice = document.getElementById('import-separator').value;
  const text = _importState.rawText;
  const firstLine = text.split('\n')[0] || '';
  const sep = sepChoice === 'auto' ? _detectSeparator(firstLine) : (sepChoice === '\\t' ? '\t' : sepChoice);
  _importState.separator = sep;

  const rows = _parseCSV(text, sep);
  if (rows.length === 0) {
    document.getElementById('import-meta').textContent = 'Datei ist leer.';
    return;
  }
  _importState.headers = rows[0].map(h => h.trim());
  _importState.rows = rows.slice(1).filter(r => r.some(v => (v || '').trim() !== ''));
  _importState.mapping = _autoMapHeaders(_importState.headers, IMPORT_FIELDS[_importState.type]);

  // v2.4.1/2: Encoding mit anzeigen, plus Replacement-Char-Warnung
  const replCount = (_importState.rawText.match(/�/g) || []).length;
  const encLabel = { 'utf-8': 'UTF-8', 'windows-1252': 'Windows-1252', 'iso-8859-1': 'ISO-8859-1', 'macintosh': 'Mac-Roman', 'utf-16le': 'UTF-16 LE', 'utf-16be': 'UTF-16 BE' }[_importState.encoding] || _importState.encoding;
  const warn = replCount > 0
    ? ` · <span style="color:var(--danger)">⚠ ${replCount} unleserliche Zeichen — Zeichensatz manuell wählen (z.B. Windows-1252)</span>`
    : '';
  document.getElementById('import-meta').innerHTML =
    `${_importState.rows.length} Datensätze · ${_importState.headers.length} Spalten · Trenner: „${sep === '\t' ? 'Tab' : sep}" · Zeichensatz: ${esc(encLabel)}${warn}`;
  renderImportMapping();
  renderImportPreview();
  document.getElementById('import-mapping-card').style.display = '';
  document.getElementById('import-preview-card').style.display = '';
  document.getElementById('import-run-card').style.display = '';
}

function onImportTypeChange() {
  _importState.type = document.getElementById('import-type').value;
  if (_importState.headers.length > 0) {
    _importState.mapping = _autoMapHeaders(_importState.headers, IMPORT_FIELDS[_importState.type]);
    renderImportMapping();
    renderImportPreview();
  }
  // v2.9.9: Update-Modus-Box nur für Produkt-Import zeigen.
  const updateBox = document.getElementById('import-product-update-mode');
  if (updateBox) {
    updateBox.style.display = _importState.type === 'product' ? 'block' : 'none';
    if (_importState.type !== 'product') {
      const cb = document.getElementById('import-update-existing');
      if (cb) cb.checked = false;
    }
  }
}

function renderImportMapping() {
  const wrap = document.getElementById('import-mapping');
  if (!wrap) return;
  const fields = IMPORT_FIELDS[_importState.type];
  const sample = _importState.rows[0] || [];

  // v2.4.4: optgroup wenn Felder gruppiert sind (z.B. Firma/Kontakt)
  const optionsForSelected = (selected) => {
    const opts = [`<option value=""${selected ? '' : ' selected'}>— Ignorieren —</option>`];
    const grouped = fields.some(f => f.group);
    if (grouped) {
      const groups = {};
      fields.forEach(f => { (groups[f.group || ''] = groups[f.group || ''] || []).push(f); });
      Object.entries(groups).forEach(([gname, gfields]) => {
        opts.push(`<optgroup label="${esc(gname)}">`);
        gfields.forEach(f => {
          const req = f.required ? ' *' : '';
          const sel = selected === f.key ? ' selected' : '';
          opts.push(`<option value="${esc(f.key)}"${sel}>${esc(f.label)}${req}</option>`);
        });
        opts.push('</optgroup>');
      });
    } else {
      fields.forEach(f => {
        const req = f.required ? ' *' : '';
        const sel = selected === f.key ? ' selected' : '';
        opts.push(`<option value="${esc(f.key)}"${sel}>${esc(f.label)}${req}</option>`);
      });
    }
    return opts.join('');
  };

  wrap.innerHTML = `
    <table class="import-mapping-table">
      <thead><tr><th>CSV-Spalte</th><th>Beispiel-Wert</th><th>→ Zielfeld(er)</th></tr></thead>
      <tbody>
      ${_importState.headers.map((h, i) => {
        const mappings = _importState.mapping[i] || [];
        // v2.6.5: bei leerem Mapping einen "leeren" Slot zum Auswählen rendern;
        // bei mehreren Mappings jeweils ein Dropdown + ×-Button + ein "+ weitere"-Button.
        const slots = mappings.length === 0 ? [null] : mappings;
        return `
        <tr>
          <td><strong>${esc(h)}</strong></td>
          <td class="muted">${esc((sample[i] || '').substring(0, 60))}</td>
          <td>
            <div class="import-mapping-slots">
              ${slots.map((sel, mIdx) => `
                <div class="import-mapping-slot">
                  <select onchange="updateImportMapping(${i}, ${mIdx}, this.value)">
                    ${optionsForSelected(sel)}
                  </select>
                  ${mappings.length > 0 ? `<button type="button" class="import-mapping-x" onclick="removeImportMapping(${i}, ${mIdx})" title="Entfernen">×</button>` : ''}
                </div>`).join('')}
              ${mappings.length > 0 ? `<button type="button" class="import-mapping-add" onclick="addImportMapping(${i})">+ weitere Zuordnung</button>` : ''}
            </div>
          </td>
        </tr>`;
      }).join('')}
      </tbody>
    </table>`;
}

// v2.6.5: Multi-Mapping-Helpers — eine Spalte kann auf mehrere Zielfelder mappen.
function updateImportMapping(colIdx, slotIdx, value) {
  if (!_importState.mapping[colIdx]) _importState.mapping[colIdx] = [];
  if (!value) {
    // leerer Wert = diesen Slot entfernen
    _importState.mapping[colIdx].splice(slotIdx, 1);
  } else {
    _importState.mapping[colIdx][slotIdx] = value;
  }
  renderImportMapping();
  renderImportPreview();
}

function addImportMapping(colIdx) {
  if (!_importState.mapping[colIdx]) _importState.mapping[colIdx] = [];
  // leerer String als Platzhalter — User wählt im Dropdown; wir filtern leere bei Insert.
  _importState.mapping[colIdx].push('');
  renderImportMapping();
}

function removeImportMapping(colIdx, slotIdx) {
  if (!_importState.mapping[colIdx]) return;
  _importState.mapping[colIdx].splice(slotIdx, 1);
  renderImportMapping();
  renderImportPreview();
}

// Backward-compat: legacy setImportMapping (single-target) ruft die neue Logik
function setImportMapping(colIdx, value) {
  _importState.mapping[colIdx] = value ? [value] : [];
  renderImportMapping();
  renderImportPreview();
}

function renderImportPreview() {
  const table = document.getElementById('import-preview-table');
  if (!table) return;
  const fields = IMPORT_FIELDS[_importState.type];
  const fieldByKey = Object.fromEntries(fields.map(f => [f.key, f]));
  // v2.6.5: pro CSV-Spalte können mehrere Zielfelder gemappt sein.
  // Preview zeigt jede (Spalte → Zielfeld)-Kombination als eigene Spalte.
  const previewCols = [];  // [{ colIdx, key, label }]
  _importState.mapping.forEach((keys, colIdx) => {
    (keys || []).forEach(key => {
      if (!key) return;
      previewCols.push({ colIdx, key, label: fieldByKey[key]?.label || key });
    });
  });

  if (previewCols.length === 0) {
    table.innerHTML = '<thead><tr><th>—</th></tr></thead><tbody><tr><td>Mapping fehlt — keine Spalten zugeordnet.</td></tr></tbody>';
    return;
  }
  const sample = _importState.rows.slice(0, 5);
  const headHtml = `<thead><tr>${previewCols.map(c => `<th>${esc(c.label)}</th>`).join('')}</tr></thead>`;
  const bodyHtml = `<tbody>${sample.map(r => {
    const cells = previewCols.map(c => `<td>${esc((r[c.colIdx] || '').substring(0, 80))}</td>`).join('');
    return `<tr>${cells}</tr>`;
  }).join('')}</tbody>`;
  table.innerHTML = headHtml + bodyHtml;
}

// v2.4.4: "Herr Martin Bollwinkel" / "Frau Dr. Anna Müller" → vor/nachname.
// Heuristik: erste Anrede-Worte abschneiden, Rest splitten — letztes Wort
// ist Nachname, Rest sind Vornamen. Reicht für 95 % der Fälle.
const _ANREDE_TOKENS = new Set(['herr','frau','hr.','fr.','dr.','prof.','prof','dr','dipl.-ing.','dipl.','ing.']);
function _splitFullName(input) {
  const tokens = (input || '').trim().split(/\s+/).filter(Boolean);
  while (tokens.length > 0 && _ANREDE_TOKENS.has(tokens[0].toLowerCase())) tokens.shift();
  if (tokens.length === 0) return { vorname: '', nachname: '' };
  if (tokens.length === 1) return { vorname: '', nachname: tokens[0] };
  const nachname = tokens.pop();
  return { vorname: tokens.join(' '), nachname };
}

async function runImport() {
  const btn = document.getElementById('import-run-btn');
  const statusEl = document.getElementById('import-status');
  const errorsEl = document.getElementById('import-errors');
  errorsEl.innerHTML = '';

  // Validierung: alle required-Felder gemappt?
  // v2.4.4/5: für company_contact und contact reicht entweder vor+nachname
  // ODER eine kombinierte "Anrede + Name"-Spalte
  // v2.6.5: mapping ist Array<string[]>, alle Keys aus allen Slots sammeln
  const fields = IMPORT_FIELDS[_importState.type];
  const mappedKeys = new Set();
  _importState.mapping.forEach(arr => (arr || []).forEach(k => k && mappedKeys.add(k)));
  let missing = fields.filter(f => f.required && !mappedKeys.has(f.key));
  if (_importState.type === 'company_contact' && mappedKeys.has('kontakt_anrede')) {
    missing = missing.filter(f => f.key !== 'kontakt_vorname' && f.key !== 'kontakt_nachname');
  }
  if (_importState.type === 'contact' && mappedKeys.has('__full_name')) {
    missing = missing.filter(f => f.key !== 'vorname' && f.key !== 'nachname');
  }
  if (missing.length > 0) {
    showToast('Pflichtfelder fehlen: ' + missing.map(f => f.label).join(', '), true);
    return;
  }
  if (_importState.rows.length === 0) {
    showToast('Keine Datensätze.', true);
    return;
  }

  btn.disabled = true;
  statusEl.textContent = 'Import läuft …';

  // ── Modus 1: Firma + Kontakt zusammen ──────────────────────────────────
  if (_importState.type === 'company_contact') {
    await _runCompanyContactImport(statusEl, errorsEl, btn);
    return;
  }

  // ── Modus 2: Nur Firmen ODER nur Kontakte ODER Produkte ────────────────
  // Für Kontakte: Firmenname → company_id auflösen
  // Für Produkte: Lieferantenname → lieferant_id auflösen
  let companyNameToId = {};
  if ((_importState.type === 'contact' && mappedKeys.has('__company_name'))
      || (_importState.type === 'product' && mappedKeys.has('__lieferant_name'))) {
    const { data: allCompanies } = await db.from('companies').select('id, name, ist_lieferant').is('deleted_at', null);
    (allCompanies || []).forEach(c => { companyNameToId[c.name.toLowerCase().trim()] = c.id; });
  }

  // Rows zu Payloads transformieren
  // v2.6.5: pro Spalte können mehrere Zielfelder gemappt sein → nested loop
  const payloads = [];
  const errors = [];
  _importState.rows.forEach((row, rowIdx) => {
    const obj = {};
    _importState.mapping.forEach((keys, colIdx) => {
      if (!keys || keys.length === 0) return;
      const val = (row[colIdx] || '').trim();
      if (val === '') return;
      for (const key of keys) {
        if (!key) continue;
        if (_importState.type === 'contact' && key === '__company_name') {
          const cid = companyNameToId[val.toLowerCase()];
          if (cid) obj.company_id = cid;
          else errors.push({ row: rowIdx + 2, msg: `Firma „${val}" nicht gefunden — Kontakt ohne Firma angelegt` });
        } else if (_importState.type === 'contact' && key === '__full_name') {
          // v2.4.5: Anrede abschneiden, Rest in vorname + nachname zerlegen
          const split = _splitFullName(val);
          if (split.vorname && !obj.vorname) obj.vorname = split.vorname;
          if (split.nachname && !obj.nachname) obj.nachname = split.nachname;
        } else if (_importState.type === 'product' && key === '__lieferant_name') {
          // v2.6.1: Lieferantenname → lieferant_id (companies) auflösen
          const cid = companyNameToId[val.toLowerCase().trim()];
          if (cid) obj.lieferant_id = cid;
          else errors.push({ row: rowIdx + 2, msg: `Lieferant „${val}" nicht gefunden — Produkt ohne Lieferant angelegt` });
        } else if (_importState.type === 'product' && (key === 'einkaufspreis' || key === 'verkaufspreis')) {
          // v2.6.1: Preis-Strings tolerant parsen — "1.234,56 €" / "1234,56" / "1234.56"
          const cleaned = val.replace(/[^\d,.\-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
          const num = Number(cleaned);
          obj[key] = Number.isFinite(num) ? num : 0;
        } else {
          obj[key] = val;
        }
      }
    });
    obj.erstellt_von = currentProfile?.id || null;
    payloads.push(obj);
  });

  // Batch-Insert (in Chunks von 100)
  const table = _importState.type === 'company' ? 'companies'
              : _importState.type === 'product' ? 'products'
              : 'contacts';

  // v2.9.9: Update-Modus für Produkte — bestehende per artikelnummer matchen.
  const updateMode = _importState.type === 'product'
    && document.getElementById('import-update-existing')?.checked;

  let inserted = 0;
  let updated = 0;

  if (updateMode) {
    // Bestehende Produkte einmal laden (artikelnummer → id)
    const { data: existing, error: existErr } = await db.from('products')
      .select('id, artikelnummer').is('deleted_at', null);
    if (existErr) {
      errors.push({ row: '—', msg: 'Lese-Fehler beim Update-Match: ' + existErr.message });
    }
    const artNoToId = {};
    (existing || []).forEach(p => {
      if (p.artikelnummer) artNoToId[String(p.artikelnummer).trim().toLowerCase()] = p.id;
    });

    for (let i = 0; i < payloads.length; i++) {
      const p = payloads[i];
      const art = (p.artikelnummer || '').trim().toLowerCase();
      const matchId = art ? artNoToId[art] : null;
      if (matchId) {
        // Update — `erstellt_von` und `artikelnummer` nicht überschreiben.
        const { erstellt_von, artikelnummer, ...patch } = p;
        const { error: e } = await db.from(table).update(patch).eq('id', matchId);
        if (e) errors.push({ row: i + 2, msg: 'Update-Fehler: ' + e.message });
        else updated++;
      } else {
        // Insert
        const { error: e } = await db.from(table).insert(p);
        if (e) errors.push({ row: i + 2, msg: 'Insert-Fehler: ' + e.message });
        else inserted++;
      }
    }
  } else {
    for (let i = 0; i < payloads.length; i += 100) {
      const chunk = payloads.slice(i, i + 100);
      const { error } = await db.from(table).insert(chunk);
      if (error) {
        errors.push({ row: i + 2, msg: 'DB-Fehler: ' + error.message });
        // Bei Batch-Fehler einzeln retry, damit der Rest durchgeht
        for (const single of chunk) {
          const { error: e2 } = await db.from(table).insert(single);
          if (!e2) inserted++;
          else errors.push({ row: '?', msg: 'Datensatz übersprungen: ' + e2.message + ' · ' + JSON.stringify(single).substring(0, 120) });
        }
      } else {
        inserted += chunk.length;
      }
    }
  }

  statusEl.textContent = updateMode
    ? `${updated} aktualisiert, ${inserted} neu angelegt (von ${payloads.length} Zeilen).`
    : `${inserted} von ${payloads.length} importiert.`;
  if (errors.length > 0) {
    errorsEl.innerHTML = `
      <div style="font-size:13px;font-weight:600;color:var(--warning);margin-bottom:8px">${errors.length} Hinweise/Fehler:</div>
      <div style="max-height:240px;overflow-y:auto;font-size:12px;color:var(--muted);background:var(--bg-soft);padding:10px;border-radius:6px;font-family:monospace">
        ${errors.map(e => `Zeile ${esc(String(e.row))}: ${esc(e.msg)}`).join('<br>')}
      </div>`;
  }
  const label = _importState.type === 'company' ? 'Firmen'
              : _importState.type === 'product' ? 'Produkte'
              : 'Kontakte';
  showToast(`${inserted} ${label} importiert.`);
  btn.disabled = false;
}

// v2.4.4 — Combined-Import: jede Zeile = Firma + Kontakt.
// Algorithmus:
//   1. Bestehende Firmen aus DB cachen (Name → ID)
//   2. Pro Zeile: Firma upserten (find by name, sonst anlegen mit Firma-Feldern)
//   3. Kontakt anlegen mit company_id
async function _runCompanyContactImport(statusEl, errorsEl, btn) {
  const errors = [];
  // Vorhandene Firmen laden
  const { data: allCompanies } = await db.from('companies').select('id, name').is('deleted_at', null);
  const companyNameToId = new Map((allCompanies || []).map(c => [c.name.toLowerCase().trim(), c.id]));

  // Pro Zeile: Firmenname extrahieren + ggf. anlegen
  let companiesCreated = 0, contactsCreated = 0;
  for (let rowIdx = 0; rowIdx < _importState.rows.length; rowIdx++) {
    const row = _importState.rows[rowIdx];
    const firmaPayload = {};
    const kontaktPayload = {};
    // v2.6.5: pro Spalte mehrere Zielfelder möglich → nested loop
    _importState.mapping.forEach((keys, colIdx) => {
      if (!keys || keys.length === 0) return;
      const val = (row[colIdx] || '').trim();
      if (val === '') return;
      for (const key of keys) {
        if (!key) continue;
        if (key.startsWith('firma_')) firmaPayload[key.replace('firma_', '')] = val;
        else if (key === 'kontakt_anrede') {
          const split = _splitFullName(val);
          if (split.vorname && !kontaktPayload.vorname) kontaktPayload.vorname = split.vorname;
          if (split.nachname && !kontaktPayload.nachname) kontaktPayload.nachname = split.nachname;
        }
        else if (key.startsWith('kontakt_')) kontaktPayload[key.replace('kontakt_', '')] = val;
      }
    });

    const firmaName = (firmaPayload.name || '').trim();
    if (!firmaName) {
      errors.push({ row: rowIdx + 2, msg: 'Firmenname fehlt — Zeile übersprungen' });
      continue;
    }

    let companyId = companyNameToId.get(firmaName.toLowerCase());
    if (!companyId) {
      // Firma anlegen
      firmaPayload.erstellt_von = currentProfile?.id || null;
      const { data: newC, error: cErr } = await db.from('companies').insert(firmaPayload).select('id').single();
      if (cErr) {
        errors.push({ row: rowIdx + 2, msg: `Firma „${firmaName}" konnte nicht angelegt werden: ${esc(cErr.message)}` });
        continue;
      }
      companyId = newC.id;
      companyNameToId.set(firmaName.toLowerCase(), companyId);
      companiesCreated++;
    }

    // Kontakt anlegen, wenn überhaupt Vor- oder Nachname da
    if (!kontaktPayload.vorname && !kontaktPayload.nachname) continue;
    kontaktPayload.company_id = companyId;
    kontaktPayload.erstellt_von = currentProfile?.id || null;
    const { error: kErr } = await db.from('contacts').insert(kontaktPayload);
    if (kErr) {
      errors.push({ row: rowIdx + 2, msg: `Kontakt nicht angelegt: ${esc(kErr.message)}` });
      continue;
    }
    contactsCreated++;
  }

  statusEl.textContent = `${companiesCreated} neue Firmen · ${contactsCreated} Kontakte angelegt`;
  if (errors.length > 0) {
    errorsEl.innerHTML = `
      <div style="font-size:13px;font-weight:600;color:var(--warning);margin-bottom:8px">${errors.length} Hinweise/Fehler:</div>
      <div style="max-height:240px;overflow-y:auto;font-size:12px;color:var(--muted);background:var(--bg-soft);padding:10px;border-radius:6px;font-family:monospace">
        ${errors.map(e => `Zeile ${esc(String(e.row))}: ${esc(e.msg)}`).join('<br>')}
      </div>`;
  }
  showToast(`${companiesCreated} Firmen + ${contactsCreated} Kontakte importiert.`);
  btn.disabled = false;
}

// ═══════════════════════════════════════════════════════════
//  v2.5.0 — TAGS (Cross-Entity-Labels für Firma/Kontakt/Projekt)
// ═══════════════════════════════════════════════════════════

const TAG_FARBEN = ['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#ec4899','#14b8a6','#6366f1','#84cc16','#f97316','#64748b','#0ea5e9'];
let _tagsCache = null;            // [{id,name,farbe,beschreibung,...}]
let _entityTagsCache = new Map(); // key="entityType:entityId" → tag-Array

function invalidateTagsCache() { _tagsCache = null; _entityTagsCache.clear(); }

async function loadTagsCache() {
  if (_tagsCache) return _tagsCache;
  const { data, error } = await db.from('tags').select('*').order('name');
  if (error) return [];
  _tagsCache = data || [];
  return _tagsCache;
}

async function loadTagsForEntity(entityType, entityId) {
  const key = `${entityType}:${entityId}`;
  if (_entityTagsCache.has(key)) return _entityTagsCache.get(key);
  const { data, error } = await db.from('entity_tags')
    .select('tag_id, tags(id, name, farbe, beschreibung)')
    .eq('entity_type', entityType).eq('entity_id', entityId);
  if (error) return [];
  const tags = (data || []).map(r => r.tags).filter(Boolean);
  _entityTagsCache.set(key, tags);
  return tags;
}

// ── Tag-Verwaltung-Page ───────────────────────────────────────

async function loadTagsPage() {
  invalidateTagsCache();
  const tags = await loadTagsCache();

  // Verknüpfungs-Counts pro Tag
  const counts = {};
  if (tags.length > 0) {
    const { data: ets } = await db.from('entity_tags').select('tag_id').in('tag_id', tags.map(t => t.id));
    (ets || []).forEach(r => { counts[r.tag_id] = (counts[r.tag_id] || 0) + 1; });
  }

  const tbody = document.getElementById('tags-table-body');
  if (!tbody) return;
  if (tags.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5"><div class="empty">Noch keine Tags. Klicke oben auf „+ Neuer Tag".</div></td></tr>';
    return;
  }
  tbody.innerHTML = tags.map(t => `
    <tr>
      <td><span class="tag-pill" style="background:${esc(t.farbe || '#3b82f6')}22;color:${esc(t.farbe || '#3b82f6')};border:1px solid ${esc(t.farbe || '#3b82f6')}55">${esc(t.name)}</span></td>
      <td class="col-tablet"><span style="display:inline-block;width:18px;height:18px;border-radius:4px;background:${esc(t.farbe || '#3b82f6')};vertical-align:middle"></span> <code style="font-size:11px;color:var(--muted)">${esc(t.farbe || '—')}</code></td>
      <td class="col-tablet" style="color:var(--muted);font-size:13px">${esc(t.beschreibung || '—')}</td>
      <td>${counts[t.id] || 0}×</td>
      <td class="col-action">
        <button class="btn btn-sm" onclick="openTagModal('edit','${esc(t.id)}')">Bearbeiten</button>
      </td>
    </tr>`).join('');
}

let _editingTagId = null;
function openTagModal(mode, tagId = null) {
  _editingTagId = mode === 'edit' ? tagId : null;
  document.getElementById('tag-modal-title').textContent = mode === 'edit' ? 'Tag bearbeiten' : 'Neuer Tag';
  document.getElementById('tg-delete-btn').style.display = mode === 'edit' ? '' : 'none';

  // Farben-Picker rendern
  const picker = document.getElementById('tg-farbe-picker');
  if (picker) {
    picker.innerHTML = TAG_FARBEN.map(f =>
      `<button type="button" class="tag-farbe-swatch" data-farbe="${esc(f)}" style="background:${esc(f)}" onclick="selectTagFarbe('${esc(f)}')"></button>`
    ).join('');
  }

  if (mode === 'edit' && tagId) {
    const tag = (_tagsCache || []).find(t => t.id === tagId);
    if (tag) {
      document.getElementById('tg-name').value = tag.name || '';
      document.getElementById('tg-farbe').value = tag.farbe || '#3b82f6';
      document.getElementById('tg-beschreibung').value = tag.beschreibung || '';
      _markSelectedFarbe(tag.farbe || '#3b82f6');
    }
  } else {
    document.getElementById('tg-name').value = '';
    document.getElementById('tg-farbe').value = TAG_FARBEN[0];
    document.getElementById('tg-beschreibung').value = '';
    _markSelectedFarbe(TAG_FARBEN[0]);
  }
  document.getElementById('modal-tag').classList.add('open');
}

function closeTagModal() {
  document.getElementById('modal-tag').classList.remove('open');
  _editingTagId = null;
}

function selectTagFarbe(farbe) {
  document.getElementById('tg-farbe').value = farbe;
  _markSelectedFarbe(farbe);
}
function _markSelectedFarbe(farbe) {
  document.querySelectorAll('.tag-farbe-swatch').forEach(s => {
    s.classList.toggle('is-selected', s.dataset.farbe === farbe);
  });
}

async function saveTag() {
  const name = document.getElementById('tg-name').value.trim();
  if (!name) { showToast('Name ist Pflicht.', true); return; }
  const payload = {
    name,
    farbe: document.getElementById('tg-farbe').value || '#3b82f6',
    beschreibung: document.getElementById('tg-beschreibung').value.trim() || null
  };
  let res;
  if (_editingTagId) {
    res = await db.from('tags').update(payload).eq('id', _editingTagId);
  } else {
    payload.erstellt_von = currentProfile?.id || null;
    res = await db.from('tags').insert(payload);
  }
  if (res.error) {
    showToast('Fehler: ' + res.error.message, true);
    return;
  }
  invalidateTagsCache();
  closeTagModal();
  showToast(_editingTagId ? 'Tag aktualisiert.' : 'Tag angelegt.');
  loadTagsPage();
}

async function deleteTag() {
  if (!_editingTagId) return;
  const ok = await confirmDialog({ title: 'Tag löschen?', message: 'Alle Verknüpfungen zu Firmen/Kontakten/Projekten gehen mit verloren.', okLabel: 'Löschen', isDanger: true });
  if (!ok) return;
  const { error } = await db.from('tags').delete().eq('id', _editingTagId);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  invalidateTagsCache();
  closeTagModal();
  showToast('Tag gelöscht.');
  loadTagsPage();
}

// ── Tag-Picker-Komponente für Detail-Pages ──────────────────────

async function renderEntityTagZone(containerId, entityType, entityId) {
  const wrap = document.getElementById(containerId);
  if (!wrap || !entityId) return;
  const [allTags, currentTags] = await Promise.all([
    loadTagsCache(),
    loadTagsForEntity(entityType, entityId)
  ]);
  const currentIds = new Set(currentTags.map(t => t.id));
  const availableTags = allTags.filter(t => !currentIds.has(t.id));

  const pills = currentTags.map(t => `
    <span class="tag-pill tag-pill-removable" style="background:${esc(t.farbe || '#3b82f6')}22;color:${esc(t.farbe || '#3b82f6')};border:1px solid ${esc(t.farbe || '#3b82f6')}55">
      ${esc(t.name)}
      <button class="tag-pill-x" onclick="removeTagFromEntity('${esc(t.id)}','${esc(entityType)}','${esc(entityId)}','${esc(containerId)}')" title="Tag entfernen">×</button>
    </span>`).join('');

  const adderId = `tag-adder-${containerId}`;
  const addOptions = availableTags.length > 0
    ? availableTags.map(t => `<option value="${esc(t.id)}" data-farbe="${esc(t.farbe || '#3b82f6')}">${esc(t.name)}</option>`).join('')
    : '<option value="">— Alle Tags zugewiesen —</option>';

  wrap.innerHTML = `
    <div class="tag-list">${pills || '<span class="info-card-empty" style="font-size:12px">Noch keine Tags.</span>'}</div>
    <div class="tag-adder">
      <select id="${adderId}" onchange="addTagToEntity(this.value,'${esc(entityType)}','${esc(entityId)}','${esc(containerId)}'); this.value='';" ${availableTags.length === 0 ? 'disabled' : ''}>
        <option value="">+ Tag hinzufügen …</option>
        ${addOptions}
      </select>
      <button type="button" class="tag-create-btn" onclick="openTagModal('new')" title="Neuen Tag anlegen">+ Neu</button>
    </div>`;
}

async function addTagToEntity(tagId, entityType, entityId, containerId) {
  if (!tagId) return;
  const { error } = await db.from('entity_tags').insert({ tag_id: tagId, entity_type: entityType, entity_id: entityId });
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  _entityTagsCache.delete(`${entityType}:${entityId}`);
  await renderEntityTagZone(containerId, entityType, entityId);
}

async function removeTagFromEntity(tagId, entityType, entityId, containerId) {
  const { error } = await db.from('entity_tags').delete()
    .eq('tag_id', tagId).eq('entity_type', entityType).eq('entity_id', entityId);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  _entityTagsCache.delete(`${entityType}:${entityId}`);
  await renderEntityTagZone(containerId, entityType, entityId);
}

// Modal-Closer-Map erweitern
if (typeof MODAL_CLOSERS !== 'undefined') {
  MODAL_CLOSERS['modal-tag'] = () => closeTagModal();
  MODAL_CLOSERS['modal-product'] = () => closeProductModal();
  MODAL_CLOSERS['modal-merge']   = () => closeMergeModal();
  MODAL_CLOSERS['modal-project-product'] = () => closeProjectProductModal();
  MODAL_CLOSERS['modal-deployment-bundle'] = () => closeDeploymentBundleModal();
  MODAL_CLOSERS['modal-theme-library']     = () => closeThemeLibraryModal();
  MODAL_CLOSERS['modal-theme-picker']      = () => closeThemePickerModal();
}

// ═══════════════════════════════════════════════════════════
//  v2.9.0 — ATTACHMENTS (Datei-Anhänge an Firma/Projekt/Einsatz/
//  Termin/Kontakt). Storage-Bucket: "attachments" (privat).
//  Pfad: <entity_type>/<entity_id>/<uuid>-<original-filename>
// ═══════════════════════════════════════════════════════════

// v2.9.2: Trigger via Aktionen-Sidebar / Arbeitsplatz-Tile.
// Der eingegebene Text wird zum sichtbaren Dateinamen (mit Original-
// Endung); leerer Text → Original-Filename bleibt. Bezug = aktuelle
// Detail-Page bzw. Arbeitsplatz-Kontext.
function _sanitizeFilenamePart(s) {
  return (s || '').replace(/[\/\\:*?"<>|\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function _getExt(name) {
  const dot = (name || '').lastIndexOf('.');
  return dot > 0 ? name.substring(dot) : '';
}

async function _uploadOneAttachment(entityType, entityId, file, displayName, beschreibung) {
  if (file.size > 50 * 1024 * 1024) {
    showToast(`„${esc(file.name)}" ist größer als 50 MB — übersprungen.`, true);
    return false;
  }
  const safeFilename = (displayName || file.name).replace(/[^\w.\-]/g, '_');
  const id = (crypto.randomUUID && crypto.randomUUID()) || (Date.now() + '-' + Math.random().toString(36).slice(2));
  const storagePath = `${entityType}/${entityId}/${id}-${safeFilename}`;
  const { error: upErr } = await db.storage.from(ATTACHMENT_BUCKET).upload(storagePath, file, {
    contentType: file.type || 'application/octet-stream',
    upsert: false
  });
  if (upErr) { showToast(`Upload fehlgeschlagen: ${esc(upErr.message)}`, true); return false; }
  const { error: dbErr } = await db.from('attachments').insert({
    entity_type: entityType,
    entity_id: entityId,
    filename: displayName || file.name,
    storage_path: storagePath,
    mime_type: file.type || null,
    size_bytes: file.size,
    beschreibung: beschreibung || null,
    uploaded_by: currentProfile?.id || null
  });
  if (dbErr) {
    showToast(`Metadaten-Eintrag fehlgeschlagen: ${esc(dbErr.message)}`, true);
    await db.storage.from(ATTACHMENT_BUCKET).remove([storagePath]);
    return false;
  }
  return true;
}

// Öffnet einen Datei-Picker und lädt die Auswahl an die aktive Detail-Entity
// hoch. prefixText (z.B. aus dem Note-Input) wird zum sichtbaren Filename.
function attachFileFromActions(entityType, entityId, prefixText) {
  if (!entityId) { showToast('Kein Bezug.', true); return; }
  const prefix = _sanitizeFilenamePart(prefixText);
  const input = document.createElement('input');
  input.type = 'file';
  input.multiple = true;
  input.style.display = 'none';
  document.body.appendChild(input);
  input.onchange = async () => {
    const files = [...(input.files || [])];
    if (files.length === 0) { input.remove(); return; }
    showToast(`Lade ${files.length} Datei${files.length === 1 ? '' : 'en'} hoch …`);
    let ok = 0;
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      let displayName;
      if (prefix) {
        displayName = files.length === 1 ? `${prefix}${_getExt(file.name)}` : `${prefix} (${i + 1})${_getExt(file.name)}`;
      } else {
        displayName = file.name;
      }
      const success = await _uploadOneAttachment(entityType, entityId, file, displayName, prefix || null);
      if (success) ok++;
    }
    showToast(`${ok} von ${files.length} hochgeladen.`);
    // Note-Input leeren (war als Filename verbraucht)
    if (prefix) {
      const noteInputId = entityType === 'company' ? 'company-note-input'
        : entityType === 'project' ? 'project-note-input'
        : entityType === 'contact' ? 'contact-note-input' : null;
      if (noteInputId) {
        const ni = document.getElementById(noteInputId);
        if (ni) ni.value = '';
      }
    }
    // Anhang-Zone refreshen (richtige Container-ID je Entity)
    const containerMap = { company: 'company-attachments', project: 'project-attachments', contact: 'contact-attachments', deployment: 'dep-attachments', appointment: 'appt-attachments' };
    const cont = containerMap[entityType];
    if (cont && document.getElementById(cont)) await renderAttachmentZone(entityType, entityId, cont);
    _refreshActivityStreamFor(entityType, entityId);
    input.remove();
  };
  input.click();
}

const ATTACHMENT_BUCKET = 'attachments';

function _formatBytes(b) {
  if (!b || b < 1024) return `${b || 0} B`;
  if (b < 1024*1024) return `${(b/1024).toFixed(1)} KB`;
  if (b < 1024*1024*1024) return `${(b/1024/1024).toFixed(1)} MB`;
  return `${(b/1024/1024/1024).toFixed(2)} GB`;
}

function _attachmentIcon(mimeType, filename) {
  const ext = (filename || '').split('.').pop()?.toLowerCase() || '';
  if (mimeType?.startsWith('image/'))            return '🖼';
  if (mimeType?.startsWith('video/'))            return '🎬';
  if (mimeType?.startsWith('audio/'))            return '🎵';
  if (mimeType === 'application/pdf' || ext === 'pdf') return '📄';
  if (['doc','docx','rtf'].includes(ext))        return '📝';
  if (['xls','xlsx','csv'].includes(ext))        return '📊';
  if (['ppt','pptx','key'].includes(ext))        return '📈';
  if (['zip','rar','7z','tar','gz'].includes(ext)) return '🗜';
  return '📎';
}

async function loadAttachmentsFor(entityType, entityId) {
  const { data, error } = await db.from('attachments')
    .select('*, uploaded_by_user:user_profiles!attachments_uploaded_by_fkey(name)')
    .is('deleted_at', null)
    .eq('entity_type', entityType).eq('entity_id', entityId)
    .order('created_at', { ascending: false });
  if (error) return [];
  return data || [];
}

async function renderAttachmentZone(entityType, entityId, containerId) {
  const wrap = document.getElementById(containerId);
  if (!wrap || !entityId) return;
  const items = await loadAttachmentsFor(entityType, entityId);

  const inputId = `${containerId}-file-input`;
  const list = items.length === 0
    ? '<div class="info-card-empty" style="font-size:12px">Noch keine Dateien.</div>'
    : `<div class="attachment-list">${items.map(a => `
        <div class="attachment-row">
          <span class="attachment-icon">${esc(_attachmentIcon(a.mime_type, a.filename))}</span>
          <a class="attachment-name" onclick="downloadAttachment('${esc(a.id)}')">${esc(a.filename)}</a>
          <span class="attachment-meta">${esc(_formatBytes(a.size_bytes))} · ${esc(formatDateCompact((a.created_at||'').substring(0,10)))}${a.uploaded_by_user?.name ? ' · ' + esc(a.uploaded_by_user.name) : ''}</span>
          <button class="attachment-delete" onclick="deleteAttachment('${esc(a.id)}','${esc(entityType)}','${esc(entityId)}','${esc(containerId)}')" title="Löschen">×</button>
        </div>`).join('')}</div>`;

  wrap.innerHTML = `
    ${list}
    <div class="attachment-upload">
      <input type="file" id="${inputId}" multiple style="display:none"
             onchange="onAttachmentFileChosen('${esc(entityType)}','${esc(entityId)}','${esc(containerId)}',this)">
      <button type="button" class="btn btn-sm" onclick="document.getElementById('${inputId}').click()">+ Datei hochladen</button>
      <span class="attachment-hint">max 50 MB pro Datei</span>
    </div>`;
}

async function onAttachmentFileChosen(entityType, entityId, containerId, input) {
  const files = [...(input.files || [])];
  if (files.length === 0) return;
  const wrap = document.getElementById(containerId);
  for (const file of files) {
    if (file.size > 50 * 1024 * 1024) {
      showToast(`„${esc(file.name)}" ist größer als 50 MB — übersprungen.`, true);
      continue;
    }
    // Pfad: entity_type/entity_id/<uuid>-<filename>
    const safeFilename = file.name.replace(/[^\w.\-]/g, '_');
    const id = (crypto.randomUUID && crypto.randomUUID()) || (Date.now() + '-' + Math.random().toString(36).slice(2));
    const storagePath = `${entityType}/${entityId}/${id}-${safeFilename}`;
    showToast(`Lade „${esc(file.name)}" hoch …`);
    const { error: upErr } = await db.storage.from(ATTACHMENT_BUCKET).upload(storagePath, file, {
      contentType: file.type || 'application/octet-stream',
      upsert: false
    });
    if (upErr) { showToast(`Upload fehlgeschlagen: ${esc(upErr.message)}`, true); continue; }
    // Metadaten in DB
    const { error: dbErr } = await db.from('attachments').insert({
      entity_type: entityType,
      entity_id: entityId,
      filename: file.name,
      storage_path: storagePath,
      mime_type: file.type || null,
      size_bytes: file.size,
      uploaded_by: currentProfile?.id || null
    });
    if (dbErr) {
      showToast(`Metadaten-Eintrag fehlgeschlagen: ${esc(dbErr.message)}`, true);
      // Storage-Datei aufräumen
      await db.storage.from(ATTACHMENT_BUCKET).remove([storagePath]);
      continue;
    }
  }
  input.value = '';
  showToast(`${files.length} Datei${files.length === 1 ? '' : 'en'} hochgeladen.`);
  await renderAttachmentZone(entityType, entityId, containerId);
  _refreshActivityStreamFor(entityType, entityId);
}

async function downloadAttachment(attachmentId) {
  const { data: att } = await db.from('attachments').select('storage_path, filename').eq('id', attachmentId).single();
  if (!att) { showToast('Datei nicht gefunden.', true); return; }
  // Signed URL für 1h
  const { data: urlData, error } = await db.storage.from(ATTACHMENT_BUCKET).createSignedUrl(att.storage_path, 3600);
  if (error) { showToast('Download fehlgeschlagen: ' + error.message, true); return; }
  // Browser-Download triggern
  const a = document.createElement('a');
  a.href = urlData.signedUrl;
  a.download = att.filename;
  a.target = '_blank';
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

async function deleteAttachment(attachmentId, entityType, entityId, containerId) {
  const ok = await confirmDialog({ title: 'Datei löschen?', message: 'Die Datei wird soft-gelöscht (deleted_at gesetzt). Storage bleibt erhalten — kontaktiere den Admin für endgültige Bereinigung.', okLabel: 'Löschen', isDanger: true });
  if (!ok) return;
  const { error } = await db.from('attachments')
    .update({ deleted_at: new Date().toISOString() }).eq('id', attachmentId);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  showToast('Datei gelöscht.');
  await renderAttachmentZone(entityType, entityId, containerId);
  _refreshActivityStreamFor(entityType, entityId);
}

// v2.9.1: Activity-Stream nach Anhang-Änderung neu laden, wenn passende
// Detail-Page aktiv ist. Termin/Einsatz haben keinen Aktivitäten-Stream.
function _refreshActivityStreamFor(entityType, entityId) {
  if (entityType === 'company'  && currentCompanyDetailId === entityId) loadCompanyActivityStream(entityId);
  if (entityType === 'project'  && currentProjectDetailId === entityId) loadProjectActivityStream(entityId);
  if (entityType === 'contact'  && currentContactDetailId === entityId) loadContactActivityStream(entityId);
}

// ═══════════════════════════════════════════════════════════
//  v2.8.0 — SHORTCUTS (Quick-Links auf dem Arbeitsplatz)
// ═══════════════════════════════════════════════════════════

let _shortcutsCache = [];
let _editingShortcutId = null;

async function loadShortcutsCache(force = false) {
  if (!force && _shortcutsCache.length > 0) return _shortcutsCache;
  const { data, error } = await db.from('shortcuts').select('*')
    .order('reihenfolge', { ascending: true }).order('label');
  if (error) return [];
  _shortcutsCache = data || [];
  return _shortcutsCache;
}

async function loadShortcutsPage() {
  await loadShortcutsCache(true);
  const tbody = document.getElementById('shortcuts-table-body');
  const countEl = document.getElementById('shortcuts-count');
  if (!tbody) return;
  countEl.textContent = `${_shortcutsCache.length} Shortcut${_shortcutsCache.length === 1 ? '' : 's'}`;
  if (_shortcutsCache.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7"><div class="empty">Noch keine Shortcuts. Klicke oben auf „+ Neuer Shortcut".</div></td></tr>';
    return;
  }
  tbody.innerHTML = _shortcutsCache.map(s => `
    <tr style="${s.ist_aktiv ? '' : 'opacity:0.55'}">
      <td style="font-size:18px;text-align:center">${esc(s.icon || '🔗')}</td>
      <td><span class="cell-link" onclick="openShortcutModal('edit','${esc(s.id)}')">${esc(s.label)}</span></td>
      <td class="col-tablet">${s.kategorie ? `<span class="badge" style="background:#eef2ff;color:#4338ca">${esc(s.kategorie)}</span>` : '—'}</td>
      <td class="col-desktop"><a href="${esc(s.url)}" target="_blank" rel="noopener" style="color:var(--link);font-size:12px;font-family:monospace">${esc(s.url.length > 60 ? s.url.substring(0,60) + '…' : s.url)}</a></td>
      <td>${s.reihenfolge}</td>
      <td>${s.ist_aktiv ? '<span class="badge" style="background:#dcfce7;color:#166534">Aktiv</span>' : '<span style="color:var(--muted)">inaktiv</span>'}</td>
      <td class="col-action"><button class="btn btn-sm" onclick="openShortcutModal('edit','${esc(s.id)}')">Bearbeiten</button></td>
    </tr>`).join('');
}

async function openShortcutModal(mode, shortcutId = null) {
  _editingShortcutId = mode === 'edit' ? shortcutId : null;
  document.getElementById('shortcut-modal-title').textContent = mode === 'edit' ? 'Shortcut bearbeiten' : 'Neuer Shortcut';
  document.getElementById('sc-delete-btn').style.display = mode === 'edit' ? '' : 'none';

  ['sc-icon','sc-label','sc-url','sc-kategorie','sc-beschreibung'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  document.getElementById('sc-reihenfolge').value = '0';
  document.getElementById('sc-aktiv').value = 'true';

  // Kategorie-Datalist mit existierenden Werten
  await loadShortcutsCache();
  const kategorien = [...new Set(_shortcutsCache.map(s => s.kategorie).filter(Boolean))].sort();
  document.getElementById('sc-kategorie-list').innerHTML = kategorien.map(k => `<option value="${esc(k)}">`).join('');

  if (mode === 'edit' && shortcutId) {
    const s = _shortcutsCache.find(x => x.id === shortcutId);
    if (s) {
      document.getElementById('sc-icon').value = s.icon || '';
      document.getElementById('sc-label').value = s.label || '';
      document.getElementById('sc-url').value = s.url || '';
      document.getElementById('sc-kategorie').value = s.kategorie || '';
      document.getElementById('sc-beschreibung').value = s.beschreibung || '';
      document.getElementById('sc-reihenfolge').value = s.reihenfolge ?? 0;
      document.getElementById('sc-aktiv').value = s.ist_aktiv ? 'true' : 'false';
    }
  }
  document.getElementById('modal-shortcut').classList.add('open');
  setTimeout(() => document.getElementById('sc-label')?.focus(), 100);
}

function closeShortcutModal() {
  document.getElementById('modal-shortcut').classList.remove('open');
  _editingShortcutId = null;
}

async function saveShortcut() {
  const label = document.getElementById('sc-label').value.trim();
  const url = document.getElementById('sc-url').value.trim();
  if (!label) { showToast('Label ist Pflicht.', true); return; }
  if (!url)   { showToast('URL ist Pflicht.', true); return; }
  // v2.33.3: URL-Scheme-Whitelist gegen XSS-Vektor (Phase A.3 #4).
  // `javascript:`-URIs würden im Origin der App ausgeführt → Token-Hijack.
  // Erlaubt: http(s), mailto, tel. Andere Schemes oder Scheme-lose Werte
  // (die der Browser als relative URL zur App auflöst) werden abgelehnt.
  if (!/^(https?|mailto|tel):/i.test(url)) {
    showToast('URL muss mit http://, https://, mailto: oder tel: beginnen.', true);
    return;
  }
  const payload = {
    label, url,
    icon: document.getElementById('sc-icon').value.trim() || null,
    kategorie: document.getElementById('sc-kategorie').value.trim() || null,
    beschreibung: document.getElementById('sc-beschreibung').value.trim() || null,
    reihenfolge: parseInt(document.getElementById('sc-reihenfolge').value, 10) || 0,
    ist_aktiv: document.getElementById('sc-aktiv').value === 'true'
  };
  let res;
  if (_editingShortcutId) {
    res = await db.from('shortcuts').update(payload).eq('id', _editingShortcutId);
  } else {
    payload.erstellt_von = currentProfile?.id || null;
    res = await db.from('shortcuts').insert(payload);
  }
  if (res.error) { showToast('Fehler: ' + res.error.message, true); return; }
  closeShortcutModal();
  showToast(_editingShortcutId ? 'Shortcut aktualisiert.' : 'Shortcut angelegt.');
  await loadShortcutsCache(true);
  loadShortcutsPage();
}

async function deleteShortcut() {
  if (!_editingShortcutId) return;
  const ok = await confirmDialog({ title: 'Shortcut löschen?', message: 'Hard-Delete — kann nicht rückgängig gemacht werden.', okLabel: 'Löschen', isDanger: true });
  if (!ok) return;
  const { error } = await db.from('shortcuts').delete().eq('id', _editingShortcutId);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  closeShortcutModal();
  showToast('Shortcut gelöscht.');
  await loadShortcutsCache(true);
  loadShortcutsPage();
}

async function renderArbeitsplatzShortcuts() {
  const block = document.getElementById('arbeitsplatz-shortcuts-block');
  const wrap = document.getElementById('arbeitsplatz-shortcuts');
  if (!wrap) return;
  if (block) block.style.display = '';
  await loadShortcutsCache(true);
  const active = _shortcutsCache.filter(s => s.ist_aktiv);
  if (active.length === 0) {
    // v2.26.0: Empty-State statt Block verstecken — im Flyout sonst leeres Panel.
    wrap.innerHTML = '<div class="info-card-empty">Noch keine Quick-Links angelegt. Admins können diese in den Einstellungen pflegen.</div>';
    return;
  }

  // Nach Kategorie gruppieren — innerhalb sortiert nach reihenfolge/label
  const byKat = {};
  active.forEach(s => {
    const k = s.kategorie || 'Sonstiges';
    (byKat[k] = byKat[k] || []).push(s);
  });

  const renderCard = s => `
    <a class="arbeitsplatz-shortcut-card" href="${esc(s.url)}" target="_blank" rel="noopener" title="${esc(s.beschreibung || s.label)}">
      <span class="arbeitsplatz-shortcut-icon">${esc(s.icon || '🔗')}</span>
      <span class="arbeitsplatz-shortcut-label">${esc(s.label)}</span>
    </a>`;

  // v2.8.1: bei nur einer Kategorie wird der Gruppen-Title weggelassen (redundant
  // zum übergeordneten "QUICK-LINKS"-Header)
  const kategorien = Object.keys(byKat);
  if (kategorien.length === 1) {
    wrap.innerHTML = `<div class="arbeitsplatz-shortcut-cards">${byKat[kategorien[0]].map(renderCard).join('')}</div>`;
  } else {
    wrap.innerHTML = kategorien.map(kat => `
      <div class="arbeitsplatz-shortcut-group">
        <div class="arbeitsplatz-shortcut-group-title">${esc(kat)}</div>
        <div class="arbeitsplatz-shortcut-cards">${byKat[kat].map(renderCard).join('')}</div>
      </div>`).join('');
  }
}

if (typeof MODAL_CLOSERS !== 'undefined') {
  MODAL_CLOSERS['modal-shortcut'] = () => closeShortcutModal();
}

// ═══════════════════════════════════════════════════════════
//  v2.6.1 — DUBLETTEN (Firma-Doppelungen finden + zusammenführen)
// ═══════════════════════════════════════════════════════════

let _dublettenGroups = [];   // [{ key, items: [{...company}], masterId }]
let _mergeContext = null;    // { masterId, dupIds, masterName }

// Normalisiert einen Firmennamen für Vergleich:
// Lowercase, getrimmt, häufige Rechtsform-Suffixe entfernt, Sonderzeichen weg.
function _normalizeCompanyName(name) {
  if (!name) return '';
  let s = name.toLowerCase().trim();
  // Rechtsform-Suffixe und Trenner abschneiden
  s = s.replace(/\b(gmbh\s*&\s*co\.?\s*kg|gmbh|ag|kg|ohg|gbr|e\.?\s*v\.?|ug|ltd\.?|inc\.?|corp\.?|co\.?)\b/g, '');
  s = s.replace(/[\.\,\-\&]/g, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

async function loadDublettenPage() {
  const wrap = document.getElementById('dubletten-content');
  const wrapK = document.getElementById('dubletten-contacts');
  if (!wrap) return;
  wrap.innerHTML = '<div class="info-card-empty">Lade …</div>';
  if (wrapK) wrapK.innerHTML = '<div class="info-card-empty">Lade …</div>';

  // Firmen + Kontakte + Produkte parallel laden
  const [companiesRes, contactsRes, productsRes] = await Promise.all([
    db.from('companies').select('*').is('deleted_at', null).order('name'),
    db.from('contacts').select('*, company:companies(id, name)').is('deleted_at', null).order('nachname'),
    db.from('products').select('*, lieferant:companies!products_lieferant_id_fkey(id, name)').is('deleted_at', null).order('name')
  ]);
  const { data: companies, error } = companiesRes;
  if (error) {
    wrap.innerHTML = `<div class="info-card-empty">Fehler: ${esc(error.message)}</div>`;
    return;
  }
  // Kontakt + Produkt-Dubletten parallel rendern
  _renderContactDubletten(contactsRes.data || []);
  _renderProductDubletten(productsRes.data || []);

  // Gruppieren nach normalisiertem Namen
  const groups = {};
  (companies || []).forEach(c => {
    const key = _normalizeCompanyName(c.name);
    if (!key) return;
    (groups[key] = groups[key] || []).push(c);
  });
  // Nur Gruppen mit ≥2 Einträgen
  _dublettenGroups = Object.entries(groups)
    .filter(([k, items]) => items.length >= 2)
    .map(([key, items]) => ({ key, items }))
    .sort((a, b) => b.items.length - a.items.length);

  if (_dublettenGroups.length === 0) {
    wrap.innerHTML = '<div class="info-card-empty">Keine Dubletten gefunden — alle Firmennamen sind eindeutig.</div>';
    return;
  }

  // Pro Gruppe: Verknüpfungs-Counts holen (für Master-Empfehlung)
  const allIds = _dublettenGroups.flatMap(g => g.items.map(i => i.id));
  const counts = await _getCompanyLinkCounts(allIds);

  wrap.innerHTML = _dublettenGroups.map((g, gi) => {
    const items = g.items.map(c => ({
      ...c,
      _count: counts[c.id] || { contacts:0, projects:0, deployments:0, appointments:0, total:0 }
    }));
    // Master-Empfehlung: der mit den meisten Verknüpfungen
    const recommendedMaster = items.slice().sort((a, b) => b._count.total - a._count.total)[0];
    return `
      <div class="dublette-group">
        <div class="dublette-group-head">
          <span class="dublette-group-name">${esc(items[0].name)}</span>
          <span class="dublette-group-meta">${items.length} Einträge mit identischem normalisiertem Namen</span>
        </div>
        <table class="dublette-table">
          <thead><tr>
            <th style="width:36px">Master</th>
            <th>Name</th>
            <th>Stadt</th>
            <th>Kontakte</th>
            <th>Projekte</th>
            <th>Termine</th>
            <th>Einsätze</th>
            <th>Erstellt</th>
            <th></th>
          </tr></thead>
          <tbody>
          ${items.map(c => `
            <tr>
              <td><input type="radio" name="dublette-master-${gi}" value="${esc(c.id)}" ${c.id === recommendedMaster.id ? 'checked' : ''}></td>
              <td><span class="cell-link" onclick="navigateTo('firma','${esc(c.id)}')">${esc(c.name)}</span>${c.ist_lieferant ? ' <span style="font-size:10px;color:var(--muted)">(Lieferant)</span>' : ''}</td>
              <td>${esc(c.stadt || '—')}</td>
              <td>${c._count.contacts}</td>
              <td>${c._count.projects}</td>
              <td>${c._count.appointments}</td>
              <td>${c._count.deployments}</td>
              <td style="font-size:11px;color:var(--muted)">${c.created_at ? esc(formatDateCompact(c.created_at.substring(0,10))) : '—'}</td>
              <td></td>
            </tr>`).join('')}
          </tbody>
        </table>
        <div class="dublette-group-actions">
          <button class="btn btn-primary btn-sm" onclick="startMerge(${gi})">Diese ${items.length} Einträge zusammenführen</button>
        </div>
      </div>`;
  }).join('');
}

// Verknüpfungs-Counts pro Firma — für Master-Empfehlung und UI-Anzeige
async function _getCompanyLinkCounts(companyIds) {
  if (companyIds.length === 0) return {};
  const counts = {};
  companyIds.forEach(id => { counts[id] = { contacts:0, projects:0, deployments:0, appointments:0, total:0 }; });

  const queries = await Promise.all([
    db.from('contacts').select('company_id').is('deleted_at', null).in('company_id', companyIds),
    db.from('projects').select('company_id').is('deleted_at', null).in('company_id', companyIds),
    db.from('deployments').select('company_id').is('deleted_at', null).in('company_id', companyIds),
    db.from('appointments').select('company_id').is('deleted_at', null).in('company_id', companyIds)
  ]);
  const [c, p, d, a] = queries.map(r => r.data || []);
  c.forEach(r => { if (counts[r.company_id]) counts[r.company_id].contacts++; });
  p.forEach(r => { if (counts[r.company_id]) counts[r.company_id].projects++; });
  d.forEach(r => { if (counts[r.company_id]) counts[r.company_id].deployments++; });
  a.forEach(r => { if (counts[r.company_id]) counts[r.company_id].appointments++; });
  Object.values(counts).forEach(c => { c.total = c.contacts + c.projects + c.deployments + c.appointments; });
  return counts;
}

function startMerge(groupIdx) {
  const group = _dublettenGroups[groupIdx];
  if (!group) return;
  const masterRadio = document.querySelector(`input[name="dublette-master-${groupIdx}"]:checked`);
  if (!masterRadio) { showToast('Bitte einen Master wählen.', true); return; }
  const masterId = masterRadio.value;
  const dupIds = group.items.filter(c => c.id !== masterId).map(c => c.id);
  const masterName = group.items.find(c => c.id === masterId)?.name || '?';

  _mergeContext = { masterId, dupIds, masterName };
  document.getElementById('merge-summary').innerHTML = `
    <strong>Master (Firma):</strong> ${esc(masterName)}<br>
    <strong>Dubletten (${dupIds.length}):</strong> ${esc(group.items.filter(c => c.id !== masterId).map(c => `${c.name}${c.stadt ? ' (' + c.stadt + ')' : ''}`).join(', '))}`;
  // Confirm-Handler explizit auf Firma-Variante setzen (kann durch Kontakt-Merge umgesetzt sein)
  const btn = document.getElementById('merge-confirm-btn');
  if (btn) btn.onclick = confirmMerge;
  document.getElementById('modal-merge').classList.add('open');
}

function closeMergeModal() {
  document.getElementById('modal-merge').classList.remove('open');
  _mergeContext = null;
}

async function confirmMerge() {
  if (!_mergeContext) return;
  const { masterId, dupIds } = _mergeContext;
  const btn = document.getElementById('merge-confirm-btn');
  btn.disabled = true;
  btn.textContent = 'Wird zusammengeführt …';

  let totalMoved = 0;
  const errors = [];

  // v2.6.2: Pro Dublette zwei Wellen statt 15 sequenzielle Roundtrips —
  // alle FK-Updates + Tag/Pin-Reads parallel; danach Tag/Pin-Resolve + Soft-Delete parallel.
  const fkSpec = [
    { table: 'contacts',     col: 'company_id' },
    { table: 'appointments', col: 'company_id' },
    { table: 'projects',     col: 'company_id' },
    { table: 'deployments',  col: 'company_id' },
    { table: 'tasks',        col: 'company_id' },
    { table: 'notes',        col: 'company_id' },
    { table: 'memberships',  col: 'company_id' },
    { table: 'products',     col: 'lieferant_id' }
  ];

  for (const dupId of dupIds) {
    // Welle 1: alle FK-Updates + Tag/Pin-Reads parallel
    const fkPromises = fkSpec.map(({ table, col }) =>
      db.from(table).update({ [col]: masterId }).eq(col, dupId)
        .then(res => ({ table, col, error: res.error }))
    );
    const [fkResults, dupTagsRes, masterTagsRes, dupPinsRes, masterPinsRes] = await Promise.all([
      Promise.all(fkPromises),
      db.from('entity_tags').select('id, tag_id').eq('entity_type', 'company').eq('entity_id', dupId),
      db.from('entity_tags').select('tag_id').eq('entity_type', 'company').eq('entity_id', masterId),
      db.from('pins').select('id, user_id').eq('entity_type', 'company').eq('entity_id', dupId),
      db.from('pins').select('user_id').eq('entity_type', 'company').eq('entity_id', masterId)
    ]);
    fkResults.forEach(r => {
      if (r.error) errors.push({ table: r.table, msg: r.error.message });
      else totalMoved++;
    });

    // Tag/Pin-Konflikte aufräumen — bei Master-Match: DELETE statt UPDATE.
    const masterTagSet  = new Set((masterTagsRes.data  || []).map(t => t.tag_id));
    const masterPinUsrs = new Set((masterPinsRes.data || []).map(p => p.user_id));
    const tagOps = (dupTagsRes.data || []).map(dt =>
      masterTagSet.has(dt.tag_id)
        ? db.from('entity_tags').delete().eq('id', dt.id)
        : db.from('entity_tags').update({ entity_id: masterId }).eq('id', dt.id)
    );
    const pinOps = (dupPinsRes.data || []).map(dp =>
      masterPinUsrs.has(dp.user_id)
        ? db.from('pins').delete().eq('id', dp.id)
        : db.from('pins').update({ entity_id: masterId }).eq('id', dp.id)
    );

    // Welle 2: Tag/Pin-Resolve + Soft-Delete parallel
    const finalResults = await Promise.all([
      ...tagOps,
      ...pinOps,
      db.from('companies').update({ deleted_at: new Date().toISOString() }).eq('id', dupId)
    ]);
    const softDeleteRes = finalResults[finalResults.length - 1];
    if (softDeleteRes?.error) errors.push({ table: 'companies (soft-delete)', msg: softDeleteRes.error.message });
  }

  closeMergeModal();
  if (errors.length > 0) {
    showToast(`Zusammengeführt mit ${errors.length} Hinweisen — siehe Browser-Konsole.`, true);
    console.warn('Merge-Hinweise:', errors);
  } else {
    showToast(`Zusammengeführt: ${dupIds.length} Dublette${dupIds.length === 1 ? '' : 'n'} → 1 Master.`);
  }
  invalidateTagsCache();
  // v2.6.3: kein Full-Reload aller 247 Firmen + Counts. Stattdessen
  // die fertige Gruppe lokal aus dem State entfernen und das Block-DOM rauszupfen.
  // Erst nach Klick auf "Neu prüfen" wird komplett neu gescannt.
  _removeMergedGroupFromUI(masterId, dupIds);
}

// ── v2.6.4: Kontakt-Dubletten — Match per Name + E-Mail ───────────────

let _contactDublettenGroups = [];
let _mergeContactContext = null;

// Normalisierter Schlüssel: lowercase Vor+Nachname zusammen + ":" + lowercase email.
// Match nur wenn beide Seiten Email haben — verhindert "Thomas Müller"-False-Positives.
function _contactDuplicateKey(k) {
  const fullName = [(k.vorname || '').trim(), (k.nachname || '').trim()].filter(Boolean).join(' ').toLowerCase();
  const email = (k.email || '').trim().toLowerCase();
  if (!fullName || !email) return null;     // Ohne E-Mail nicht gruppieren
  return `${fullName}|${email}`;
}

function _renderContactDubletten(contacts) {
  const wrap = document.getElementById('dubletten-contacts');
  if (!wrap) return;

  const groups = {};
  contacts.forEach(k => {
    const key = _contactDuplicateKey(k);
    if (!key) return;
    (groups[key] = groups[key] || []).push(k);
  });
  _contactDublettenGroups = Object.entries(groups)
    .filter(([, items]) => items.length >= 2)
    .map(([key, items]) => ({ key, items }))
    .sort((a, b) => b.items.length - a.items.length);

  if (_contactDublettenGroups.length === 0) {
    wrap.innerHTML = '<div class="info-card-empty">Keine Kontakt-Dubletten gefunden — alle Kontakte mit gleichem Namen + E-Mail sind eindeutig. Kontakte ohne E-Mail werden bewusst nicht zusammengeführt (zu viele „Thomas Müller").</div>';
    return;
  }

  wrap.innerHTML = _contactDublettenGroups.map((g, gi) => {
    const items = g.items;
    const fullName = [items[0].vorname, items[0].nachname].filter(Boolean).join(' ');
    return `
      <div class="dublette-group">
        <div class="dublette-group-head">
          <span class="dublette-group-name">${esc(fullName)} · ${esc(items[0].email || '')}</span>
          <span class="dublette-group-meta">${items.length} Einträge mit gleichem Namen + E-Mail</span>
        </div>
        <table class="dublette-table">
          <thead><tr>
            <th style="width:36px">Master</th>
            <th>Name</th>
            <th>Position</th>
            <th>Telefon</th>
            <th>Firma</th>
            <th>Erstellt</th>
            <th></th>
          </tr></thead>
          <tbody>
          ${items.map((k, i) => {
            const fn = [k.vorname, k.nachname].filter(Boolean).join(' ');
            const firma = k.company?.name || (k.company_id ? '(Firma gelöscht)' : '—');
            return `
              <tr>
                <td><input type="radio" name="dublette-contact-master-${gi}" value="${esc(k.id)}" ${i === 0 ? 'checked' : ''}></td>
                <td><span class="cell-link" onclick="navigateTo('kontakt','${esc(k.id)}')">${esc(fn)}</span></td>
                <td>${esc(k.position || '—')}</td>
                <td>${esc(k.telefon || '—')}</td>
                <td>${esc(firma)}</td>
                <td style="font-size:11px;color:var(--muted)">${k.created_at ? esc(formatDateCompact(k.created_at.substring(0,10))) : '—'}</td>
                <td></td>
              </tr>`;
          }).join('')}
          </tbody>
        </table>
        <div class="dublette-group-actions">
          <button class="btn btn-primary btn-sm" onclick="startContactMerge(${gi})">Diese ${items.length} Einträge zusammenführen</button>
        </div>
      </div>`;
  }).join('');
}

function startContactMerge(groupIdx) {
  const group = _contactDublettenGroups[groupIdx];
  if (!group) return;
  const masterRadio = document.querySelector(`input[name="dublette-contact-master-${groupIdx}"]:checked`);
  if (!masterRadio) { showToast('Bitte einen Master wählen.', true); return; }
  const masterId = masterRadio.value;
  const dupIds = group.items.filter(k => k.id !== masterId).map(k => k.id);
  const masterK = group.items.find(k => k.id === masterId);
  const masterName = masterK ? [masterK.vorname, masterK.nachname].filter(Boolean).join(' ') : '?';

  _mergeContactContext = { masterId, dupIds, masterName };
  document.getElementById('merge-summary').innerHTML = `
    <strong>Master (Kontakt):</strong> ${esc(masterName)} · ${esc(masterK?.email || '')}<br>
    <strong>Dubletten (${dupIds.length}):</strong> ${esc(group.items.filter(k => k.id !== masterId).map(k => `${esc(k.vorname || '')} ${esc(k.nachname || '')}`.trim()).join(', '))}<br>
    <em style="color:var(--muted);font-size:12px">Verknüpfungen (Termine, Aufgaben, Notizen, Projekt-Hauptkontakt, Tags, Pins) wandern zum Master.</em>`;
  // Merge-Confirm-Button auf Kontakt-Variante umbiegen
  const btn = document.getElementById('merge-confirm-btn');
  btn.onclick = confirmContactMerge;
  document.getElementById('modal-merge').classList.add('open');
}

async function confirmContactMerge() {
  if (!_mergeContactContext) return;
  const { masterId, dupIds } = _mergeContactContext;
  const btn = document.getElementById('merge-confirm-btn');
  btn.disabled = true; btn.textContent = 'Wird zusammengeführt …';

  const fkSpec = [
    { table: 'appointments', col: 'contact_id' },
    { table: 'projects',     col: 'hauptkontakt_id' },
    { table: 'tasks',        col: 'contact_id' },
    { table: 'notes',        col: 'contact_id' }
  ];

  const errors = [];
  for (const dupId of dupIds) {
    // Welle 1: FK-Updates + Tag/Pin-Reads parallel
    const fkPromises = fkSpec.map(({ table, col }) =>
      db.from(table).update({ [col]: masterId }).eq(col, dupId)
        .then(res => ({ table, col, error: res.error }))
    );
    const [, dupTagsRes, masterTagsRes, dupPinsRes, masterPinsRes] = await Promise.all([
      Promise.all(fkPromises),
      db.from('entity_tags').select('id, tag_id').eq('entity_type', 'contact').eq('entity_id', dupId),
      db.from('entity_tags').select('tag_id').eq('entity_type', 'contact').eq('entity_id', masterId),
      db.from('pins').select('id, user_id').eq('entity_type', 'contact').eq('entity_id', dupId),
      db.from('pins').select('user_id').eq('entity_type', 'contact').eq('entity_id', masterId)
    ]);

    const masterTagSet = new Set((masterTagsRes.data || []).map(t => t.tag_id));
    const masterPinUsrs = new Set((masterPinsRes.data || []).map(p => p.user_id));
    const tagOps = (dupTagsRes.data || []).map(dt =>
      masterTagSet.has(dt.tag_id)
        ? db.from('entity_tags').delete().eq('id', dt.id)
        : db.from('entity_tags').update({ entity_id: masterId }).eq('id', dt.id)
    );
    const pinOps = (dupPinsRes.data || []).map(dp =>
      masterPinUsrs.has(dp.user_id)
        ? db.from('pins').delete().eq('id', dp.id)
        : db.from('pins').update({ entity_id: masterId }).eq('id', dp.id)
    );
    // Welle 2: Tag/Pin-Resolve + Soft-Delete
    const finalResults = await Promise.all([
      ...tagOps,
      ...pinOps,
      db.from('contacts').update({ deleted_at: new Date().toISOString() }).eq('id', dupId)
    ]);
    const sd = finalResults[finalResults.length - 1];
    if (sd?.error) errors.push({ msg: sd.error.message });
  }

  closeMergeModal();
  if (errors.length > 0) {
    showToast(`Zusammengeführt mit ${errors.length} Hinweisen — Konsole prüfen.`, true);
    console.warn('Kontakt-Merge-Hinweise:', errors);
  } else {
    showToast(`Zusammengeführt: ${dupIds.length} Kontakt-Dublette${dupIds.length === 1 ? '' : 'n'} → 1 Master.`);
  }
  // Confirm-Button auf Default-Firma-Variante zurück
  const cbtn = document.getElementById('merge-confirm-btn');
  if (cbtn) cbtn.onclick = confirmMerge;
  _mergeContactContext = null;
  // Lokal aus Liste entfernen
  _removeMergedContactGroupFromUI(masterId, dupIds);
}

function _removeMergedContactGroupFromUI(masterId, dupIds) {
  const removeAt = _contactDublettenGroups.findIndex(g =>
    g.items.some(k => k.id === masterId) && dupIds.every(d => g.items.some(k => k.id === d))
  );
  if (removeAt < 0) return;
  _contactDublettenGroups.splice(removeAt, 1);
  const wrap = document.getElementById('dubletten-contacts');
  if (!wrap) return;
  if (_contactDublettenGroups.length === 0) {
    wrap.innerHTML = '<div class="info-card-empty">Alle Kontakt-Dubletten aufgeräumt.</div>';
    return;
  }
  const blocks = wrap.querySelectorAll('.dublette-group');
  if (blocks[removeAt]) blocks[removeAt].remove();
}

// ── v2.7.0: Produkt-Dubletten — Match per Artikelnummer ODER Name ──────

let _productDublettenGroups = [];
let _mergeProductContext = null;

function _normalizeProductKey(p) {
  // Zwei Match-Schlüssel: artikelnummer (sehr eindeutig) und name (normalisiert).
  // Heuristik: wenn artikelnummer gleich → sicher dieselbe Position (lacht selten zufällig).
  // Wenn nur name gleich → wahrscheinlich Dublette, aber User soll prüfen.
  return {
    artNr: (p.artikelnummer || '').trim().toLowerCase(),
    name: (p.name || '').trim().toLowerCase().replace(/\s+/g, ' ')
  };
}

function _renderProductDubletten(products) {
  const wrap = document.getElementById('dubletten-products');
  if (!wrap) return;

  // Gruppieren — Union-Find: zwei Produkte sind verbunden wenn artNr ODER name match.
  // Pragmatisch: zwei separate Indexe bilden, dann Cluster zusammenführen.
  const byArtNr = {};
  const byName = {};
  products.forEach(p => {
    const k = _normalizeProductKey(p);
    if (k.artNr) (byArtNr[k.artNr] = byArtNr[k.artNr] || []).push(p);
    if (k.name)  (byName[k.name]   = byName[k.name]   || []).push(p);
  });

  // Cluster bilden — Union-Find auf Produkt-IDs
  const parent = {};
  const find = id => parent[id] === id ? id : (parent[id] = find(parent[id]));
  const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent[ra] = rb; };
  products.forEach(p => { parent[p.id] = p.id; });

  Object.values(byArtNr).forEach(items => {
    if (items.length >= 2) for (let i = 1; i < items.length; i++) union(items[0].id, items[i].id);
  });
  Object.values(byName).forEach(items => {
    if (items.length >= 2) for (let i = 1; i < items.length; i++) union(items[0].id, items[i].id);
  });

  const clusters = {};
  products.forEach(p => {
    const root = find(p.id);
    (clusters[root] = clusters[root] || []).push(p);
  });
  _productDublettenGroups = Object.values(clusters)
    .filter(items => items.length >= 2)
    .map(items => ({ items }))
    .sort((a, b) => b.items.length - a.items.length);

  if (_productDublettenGroups.length === 0) {
    wrap.innerHTML = '<div class="info-card-empty">Keine Produkt-Dubletten gefunden — alle Artikel sind eindeutig.</div>';
    return;
  }

  wrap.innerHTML = _productDublettenGroups.map((g, gi) => {
    const items = g.items;
    return `
      <div class="dublette-group">
        <div class="dublette-group-head">
          <span class="dublette-group-name">${esc(items[0].name)}</span>
          <span class="dublette-group-meta">${items.length} Einträge mit gleicher Artikelnummer ODER gleichem Namen</span>
        </div>
        <table class="dublette-table">
          <thead><tr>
            <th style="width:36px">Master</th>
            <th>Name</th>
            <th>Art.-Nr.</th>
            <th>Hersteller-Nr.</th>
            <th>Kategorie</th>
            <th>Lieferant</th>
            <th>EK / VK</th>
            <th>Erstellt</th>
            <th></th>
          </tr></thead>
          <tbody>
          ${items.map((p, i) => `
            <tr>
              <td><input type="radio" name="dublette-product-master-${gi}" value="${esc(p.id)}" ${i === 0 ? 'checked' : ''}></td>
              <td><span class="cell-link" onclick="openProductModal('edit','${esc(p.id)}')">${esc(p.name)}</span></td>
              <td>${esc(p.artikelnummer || '—')}</td>
              <td>${esc(p.hersteller_artikelnr || '—')}</td>
              <td>${esc(p.kategorie || '—')}</td>
              <td>${p.lieferant ? esc(p.lieferant.name) : '<span class="muted">—</span>'}</td>
              <td>${esc(formatPreis(Number(p.einkaufspreis) || 0))} / ${esc(formatPreis(Number(p.verkaufspreis) || 0))}</td>
              <td style="font-size:11px;color:var(--muted)">${p.created_at ? esc(formatDateCompact(p.created_at.substring(0,10))) : '—'}</td>
              <td></td>
            </tr>`).join('')}
          </tbody>
        </table>
        <div class="dublette-group-actions">
          <button class="btn btn-primary btn-sm" onclick="startProductMerge(${gi})">Diese ${items.length} Einträge zusammenführen</button>
        </div>
      </div>`;
  }).join('');
}

function startProductMerge(groupIdx) {
  const group = _productDublettenGroups[groupIdx];
  if (!group) return;
  const masterRadio = document.querySelector(`input[name="dublette-product-master-${groupIdx}"]:checked`);
  if (!masterRadio) { showToast('Bitte einen Master wählen.', true); return; }
  const masterId = masterRadio.value;
  const dupIds = group.items.filter(p => p.id !== masterId).map(p => p.id);
  const masterP = group.items.find(p => p.id === masterId);

  _mergeProductContext = { masterId, dupIds };
  document.getElementById('merge-summary').innerHTML = `
    <strong>Master (Produkt):</strong> ${esc(masterP?.name || '')}${masterP?.artikelnummer ? ' · ' + esc(masterP.artikelnummer) : ''}<br>
    <strong>Dubletten (${dupIds.length}):</strong> ${esc(group.items.filter(p => p.id !== masterId).map(p => p.name).join(', '))}<br>
    <em style="color:var(--muted);font-size:12px">Produkte werden soft-gelöscht — Master bleibt unverändert. Hinweis: Verkaufspositionen kommen erst in v2.6.x Phase 2 — bisher referenziert nichts auf Produkte, daher kein FK-Transfer nötig.</em>`;
  const btn = document.getElementById('merge-confirm-btn');
  btn.onclick = confirmProductMerge;
  document.getElementById('modal-merge').classList.add('open');
}

async function confirmProductMerge() {
  if (!_mergeProductContext) return;
  const { masterId, dupIds } = _mergeProductContext;
  const btn = document.getElementById('merge-confirm-btn');
  btn.disabled = true; btn.textContent = 'Wird zusammengeführt …';

  const errors = [];
  // Aktuell referenziert keine Tabelle products (außer products selbst über lieferant_id,
  // das aber product → company zeigt). Daher reicht: Dubletten soft-deleten, parallel.
  const results = await Promise.all(
    dupIds.map(id => db.from('products').update({ deleted_at: new Date().toISOString() }).eq('id', id))
  );
  results.forEach((r, i) => { if (r.error) errors.push({ id: dupIds[i], msg: r.error.message }); });

  closeMergeModal();
  if (errors.length > 0) {
    showToast(`Zusammengeführt mit ${errors.length} Hinweisen — Konsole prüfen.`, true);
    console.warn('Produkt-Merge-Hinweise:', errors);
  } else {
    showToast(`Zusammengeführt: ${dupIds.length} Produkt-Dublette${dupIds.length === 1 ? '' : 'n'} → 1 Master.`);
  }
  // Reset Confirm-Button auf Default-Firma-Variante
  const cbtn = document.getElementById('merge-confirm-btn');
  if (cbtn) cbtn.onclick = confirmMerge;
  _mergeProductContext = null;
  _removeMergedProductGroupFromUI(masterId, dupIds);
}

// ── v2.7.1: Bulk-Edit für Listen ──────────────────────────────────────

const _bulkSelected = {
  company: new Set(),
  contact: new Set(),
  product: new Set()
};

function bulkToggleRow(entityType, id, checked) {
  if (checked) _bulkSelected[entityType].add(id);
  else _bulkSelected[entityType].delete(id);
  _updateBulkToolbar(entityType);
}

function bulkToggleAll(entityType, checked) {
  // Alle aktuell sichtbaren Zeilen togglen — ID kommt aus data-bulk-id-Attribut
  const tbodyId = entityType === 'company' ? 'companies-table-body'
                : entityType === 'product' ? 'products-table-body'
                : 'contacts-table-body';
  const tbody = document.getElementById(tbodyId);
  if (!tbody) return;
  const checkboxes = tbody.querySelectorAll('input[type="checkbox"][data-bulk-id]');
  checkboxes.forEach(cb => {
    cb.checked = checked;
    const id = cb.dataset.bulkId;
    if (!id) return;
    if (checked) _bulkSelected[entityType].add(id);
    else _bulkSelected[entityType].delete(id);
  });
  _updateBulkToolbar(entityType);
}

function clearBulkSelection(entityType) {
  _bulkSelected[entityType].clear();
  // Visuell: alle Checkboxen entwählen
  const tbodyId = entityType === 'company' ? 'companies-table-body'
                : entityType === 'product' ? 'products-table-body'
                : 'contacts-table-body';
  document.querySelectorAll(`#${tbodyId} input[type="checkbox"]`).forEach(cb => cb.checked = false);
  const sel = entityType === 'company' ? 'companies-select-all'
            : entityType === 'product' ? 'products-select-all'
            : 'contacts-select-all';
  const all = document.getElementById(sel);
  if (all) all.checked = false;
  _updateBulkToolbar(entityType);
}

function _updateBulkToolbar(entityType) {
  const toolbarId = entityType === 'company' ? 'companies-bulk-toolbar'
                  : entityType === 'product' ? 'products-bulk-toolbar'
                  : 'contacts-bulk-toolbar';
  const countId = entityType === 'company' ? 'companies-bulk-count'
                : entityType === 'product' ? 'products-bulk-count'
                : 'contacts-bulk-count';
  const tb = document.getElementById(toolbarId);
  const cnt = document.getElementById(countId);
  if (!tb || !cnt) return;
  const n = _bulkSelected[entityType].size;
  if (n === 0) {
    tb.style.display = 'none';
  } else {
    tb.style.display = '';
    const labelMap = { company: 'Firmen', product: 'Produkte', contact: 'Kontakte' };
    cnt.textContent = `${n} ${labelMap[entityType]} ausgewählt`;
  }
}

// Tag-Dropdown im Bulk-Toolbar mit aktuellen Tags füllen.
// v2.7.1: für beliebigen Entitätstyp (company/contact) nutzbar.
async function _populateBulkTagDropdown(entityType = 'company') {
  const selId = entityType === 'company' ? 'companies-bulk-tag'
              : entityType === 'contact' ? 'contacts-bulk-tag'
              : null;
  const sel = selId && document.getElementById(selId);
  if (!sel) return;
  const tags = await loadTagsCache();
  sel.innerHTML = '<option value="">— Tag wählen —</option>'
    + tags.map(t => `<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
}

// Lieferanten-Dropdown im Produkt-Bulk-Toolbar
async function _populateBulkLieferantDropdown() {
  const sel = document.getElementById('products-bulk-lieferant');
  if (!sel) return;
  if (companiesCache.length === 0) {
    const { data: cs } = await db.from('companies').select('*').is('deleted_at', null).order('name');
    companiesCache = cs || [];
  }
  const lieferanten = companiesCache.filter(c => c.ist_lieferant);
  sel.innerHTML = '<option value="">— Lieferant wählen —</option>'
    + '<option value="__clear__">— Lieferant entfernen —</option>'
    + lieferanten.map(l => `<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');
}

async function bulkAddTag(entityType) {
  const tagId = document.getElementById(`${entityType === 'company' ? 'companies' : entityType + 's'}-bulk-tag`).value;
  if (!tagId) { showToast('Bitte einen Tag wählen.', true); return; }
  const ids = [...(_bulkSelected[entityType] || [])];
  if (ids.length === 0) return;
  // Insert pro ID (UNIQUE-Constraint fängt schon getaggte ab)
  const rows = ids.map(id => ({ tag_id: tagId, entity_type: entityType, entity_id: id }));
  let added = 0, skipped = 0;
  for (const row of rows) {
    const { error } = await db.from('entity_tags').insert(row);
    if (!error) added++;
    else if (error.code === '23505') skipped++;  // unique violation = schon getaggt
    else skipped++;
  }
  showToast(`Tag gesetzt: ${added} hinzugefügt${skipped > 0 ? `, ${skipped} übersprungen (schon getaggt)` : ''}.`);
  invalidateTagsCache();
}

async function bulkRemoveTag(entityType) {
  const tagId = document.getElementById(`${entityType === 'company' ? 'companies' : entityType + 's'}-bulk-tag`).value;
  if (!tagId) { showToast('Bitte einen Tag wählen.', true); return; }
  const ids = [...(_bulkSelected[entityType] || [])];
  if (ids.length === 0) return;
  // v2.7.1-fix: count-Option im delete()-Call ist supabase-js-supported, gibt count im Result zurück
  const { error, count } = await db.from('entity_tags')
    .delete({ count: 'exact' })
    .eq('tag_id', tagId).eq('entity_type', entityType).in('entity_id', ids);
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  showToast(`Tag entfernt von ${count != null ? count : ids.length} Einträgen.`);
  invalidateTagsCache();
}

// v2.9.9: Bulk-Preisanpassung für Produkte. Berechnet Vorher/Nachher pro
// Produkt clientseitig (weil PostgREST kein arithmetisches UPDATE erlaubt)
// und schickt einen Batch-UPDATE pro Produkt parallel.
async function bulkAdjustProductPrices() {
  const target = document.getElementById('products-bulk-price-target').value;
  const op     = document.getElementById('products-bulk-price-op').value;
  const valRaw = document.getElementById('products-bulk-price-value').value;
  const value  = parseFloat((valRaw || '').replace(',', '.'));
  if (!isFinite(value) || value < 0) { showToast('Bitte einen gültigen Wert eingeben.', true); return; }

  const ids = [..._bulkSelected.product];
  if (ids.length === 0) { showToast('Keine Produkte ausgewählt.', true); return; }

  // Aktuelle Preise lesen für Vorschau + Recalc
  const { data: rows, error: readErr } = await db.from('products')
    .select('id, name, einkaufspreis, verkaufspreis')
    .in('id', ids);
  if (readErr) { showToast('Fehler beim Lesen: ' + readErr.message, true); return; }

  const recalc = (price) => {
    if (price == null) return null; // null bleibt null (kein Preis hinterlegt)
    const p = Number(price) || 0;
    let n;
    switch (op) {
      case 'pct_inc': n = p * (1 + value / 100); break;
      case 'pct_dec': n = p * (1 - value / 100); break;
      case 'abs_inc': n = p + value; break;
      case 'abs_dec': n = p - value; break;
      case 'set':     n = value; break;
      default:        n = p;
    }
    if (n < 0) n = 0;
    return Math.round(n * 100) / 100;
  };

  // Preview-String bauen
  const updates = rows.map(r => {
    const newEk = (target === 'ek' || target === 'both') ? recalc(r.einkaufspreis) : r.einkaufspreis;
    const newVk = (target === 'vk' || target === 'both') ? recalc(r.verkaufspreis) : r.verkaufspreis;
    return { id: r.id, name: r.name, oldEk: r.einkaufspreis, newEk, oldVk: r.verkaufspreis, newVk };
  });

  const opLabel = { pct_inc: `+ ${value}%`, pct_dec: `− ${value}%`, abs_inc: `+ ${value} €`, abs_dec: `− ${value} €`, set: `= ${value} €` }[op];
  const targetLabel = target === 'ek' ? 'EK' : target === 'vk' ? 'VK' : 'EK + VK';
  const sample = updates.slice(0, 5).map(u => {
    const part = (target === 'ek' || target === 'both')
      ? `EK ${formatPreis(u.oldEk)} → ${formatPreis(u.newEk)}`
      : `VK ${formatPreis(u.oldVk)} → ${formatPreis(u.newVk)}`;
    return `• ${esc(u.name)}: ${part}`;
  }).join('\n');
  const more = updates.length > 5 ? `\n… und ${updates.length - 5} weitere` : '';

  const ok = await confirmDialog({
    title: `Preise anpassen (${targetLabel} ${opLabel})`,
    message: `${updates.length} Produkte werden aktualisiert.\n\nVorschau:\n${sample}${more}`,
    okLabel: 'Anpassen',
    isDanger: false
  });
  if (!ok) return;

  // Parallel-UPDATE pro Produkt
  showToast(`Aktualisiere ${updates.length} Produkte …`);
  const results = await Promise.all(updates.map(u => {
    const payload = {};
    if (target === 'ek' || target === 'both') payload.einkaufspreis = u.newEk;
    if (target === 'vk' || target === 'both') payload.verkaufspreis = u.newVk;
    return db.from('products').update(payload).eq('id', u.id).select('id');
  }));
  const errs = results.filter(r => r.error);
  if (errs.length) {
    showToast(`${updates.length - errs.length} aktualisiert, ${errs.length} Fehler.`, true);
  } else {
    showToast(`${updates.length} Produkte aktualisiert.`);
  }
  await loadProductsAndLieferanten();
  filterProducts();
  clearBulkSelection('product');
  document.getElementById('products-bulk-price-value').value = '';
}

async function bulkSetProductLieferant() {
  const lfVal = document.getElementById('products-bulk-lieferant').value;
  if (!lfVal) { showToast('Bitte einen Lieferanten wählen.', true); return; }
  const ids = [..._bulkSelected.product];
  if (ids.length === 0) return;
  const lieferantId = lfVal === '__clear__' ? null : lfVal;
  // v2.7.1-fix: kein {count:'exact'}-Option auf update() — das ist ungültiges
  // PostgREST-Syntax und führte zum 22P02 (uuid-Parse-Fehler "product").
  // Stattdessen .select('id') am Ende und length zählen.
  const { error, data } = await db.from('products')
    .update({ lieferant_id: lieferantId }).in('id', ids).select('id');
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  const n = data?.length ?? ids.length;
  showToast(`Lieferant ${lieferantId ? 'gesetzt' : 'entfernt'} bei ${n} Produkten.`);
  await loadProductsAndLieferanten();
  filterProducts();
  clearBulkSelection('product');
}

// ── v2.7.1: Generisches Bulk-Edit-Modal ──────────────────────────────
// Pro Entitätstyp eine Felder-Definition. type bestimmt die Eingabe:
// 'text' / 'textarea' / 'number' / 'boolean' / 'lookup' / 'company' / 'lieferant'

const BULK_EDIT_FIELDS = {
  company: {
    table: 'companies',
    label: 'Firmen',
    fields: [
      { key: 'typ_id',          label: 'Typ',                   type: 'lookup',   kategorie: 'unternehmens_typ' },
      { key: 'branche',          label: 'Branche',               type: 'text' },
      { key: 'abc_klassifizierung', label: 'ABC-Klassifizierung', type: 'select', options: [['A','A — Top-Kunde'],['B','B — Wichtiger Kunde'],['C','C — Geringerer Wert']] },
      { key: 'land',             label: 'Land',                  type: 'text' },
      { key: 'stadt',            label: 'Stadt',                 type: 'text' },
      { key: 'plz',              label: 'PLZ',                   type: 'text' },
      { key: 'ist_lieferant',    label: 'Auch Lieferant',        type: 'boolean' },
      { key: 'notizen',          label: 'Notizen',               type: 'textarea' }
    ]
  },
  contact: {
    table: 'contacts',
    label: 'Kontakte',
    fields: [
      { key: 'position',   label: 'Position',  type: 'text' },
      { key: 'company_id', label: 'Firma',     type: 'company' },
      { key: 'notizen',    label: 'Notizen',   type: 'textarea' }
    ]
  },
  product: {
    table: 'products',
    label: 'Produkte',
    fields: [
      { key: 'kategorie',     label: 'Kategorie',     type: 'text' },
      { key: 'einheit',       label: 'Einheit',       type: 'text' },
      { key: 'einkaufspreis', label: 'Einkaufspreis', type: 'number' },
      { key: 'verkaufspreis', label: 'Verkaufspreis', type: 'number' },
      { key: 'lieferant_id',  label: 'Lieferant',     type: 'lieferant' },
      { key: 'ist_aktiv',     label: 'Aktiv',         type: 'boolean' }
    ]
  }
};

let _bulkEditContext = null;  // { entityType, ids }

// v2.7.2: Inline-Bulk-Edit in der Toolbar — User wollte kein Modal, sondern
// die Auswahl direkt in der Bulk-Toolbar.
async function _populateBulkFieldDropdown(entityType) {
  const cfg = BULK_EDIT_FIELDS[entityType];
  if (!cfg) return;
  const selId = entityType === 'company' ? 'companies-bulk-field'
              : entityType === 'product' ? 'products-bulk-field'
              : 'contacts-bulk-field';
  const sel = document.getElementById(selId);
  if (!sel) return;
  sel.innerHTML = '<option value="">— Feld bearbeiten —</option>'
    + cfg.fields.map(f => `<option value="${esc(f.key)}">${esc(f.label)}</option>`).join('');
}

async function onBulkFieldInlineChange(entityType) {
  const prefix = entityType === 'company' ? 'companies'
               : entityType === 'product' ? 'products'
               : 'contacts';
  const fieldKey = document.getElementById(`${prefix}-bulk-field`).value;
  const valWrap = document.getElementById(`${prefix}-bulk-value-wrap`);
  const applyBtn = document.getElementById(`${prefix}-bulk-apply-btn`);
  const oeWrap = document.getElementById(`${prefix}-bulk-only-empty-wrap`);
  if (!fieldKey) {
    valWrap.style.display = 'none';
    valWrap.innerHTML = '';
    applyBtn.style.display = 'none';
    oeWrap.style.display = 'none';
    return;
  }
  const cfg = BULK_EDIT_FIELDS[entityType];
  const field = cfg.fields.find(f => f.key === fieldKey);
  if (!field) return;

  const valueId = `${prefix}-bulk-value`;
  let inputHtml = '';
  switch (field.type) {
    case 'text':
      inputHtml = `<input type="text" id="${valueId}" placeholder="${esc(field.label)}">`;
      break;
    case 'number':
      inputHtml = `<input type="number" id="${valueId}" step="0.01" min="0" placeholder="0,00">`;
      break;
    case 'textarea':
      inputHtml = `<input type="text" id="${valueId}" placeholder="${esc(field.label)}">`;  // einzeilig in Toolbar
      break;
    case 'boolean':
      inputHtml = `<select id="${valueId}"><option value="true">Ja / aktiv</option><option value="false">Nein / inaktiv</option></select>`;
      break;
    case 'select':
      inputHtml = `<select id="${valueId}">
        <option value="__NULL__">— leeren —</option>
        ${(field.options || []).map(([v, l]) => `<option value="${esc(v)}">${esc(l)}</option>`).join('')}
      </select>`;
      break;
    case 'lookup': {
      const { data } = await db.from('lookup_values')
        .select('id, wert').eq('kategorie', field.kategorie).eq('ist_aktiv', true).order('reihenfolge');
      inputHtml = `<select id="${valueId}">
        <option value="">— Bitte wählen —</option>
        <option value="__NULL__">— leeren —</option>
        ${(data || []).map(o => `<option value="${esc(o.id)}">${esc(o.wert)}</option>`).join('')}
      </select>`;
      break;
    }
    case 'company': {
      if (companiesCache.length === 0) {
        const { data: cs } = await db.from('companies').select('*').is('deleted_at', null).order('name');
        companiesCache = cs || [];
      }
      inputHtml = `<select id="${valueId}">
        <option value="">— Bitte wählen —</option>
        <option value="__NULL__">— leeren —</option>
        ${companiesCache.map(c => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}
      </select>`;
      break;
    }
    case 'lieferant': {
      if (companiesCache.length === 0) {
        const { data: cs } = await db.from('companies').select('*').is('deleted_at', null).order('name');
        companiesCache = cs || [];
      }
      const lieferanten = companiesCache.filter(c => c.ist_lieferant);
      inputHtml = `<select id="${valueId}">
        <option value="">— Bitte wählen —</option>
        <option value="__NULL__">— leeren —</option>
        ${lieferanten.map(c => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}
      </select>`;
      break;
    }
  }
  valWrap.innerHTML = inputHtml;
  valWrap.style.display = '';
  applyBtn.style.display = '';
  oeWrap.style.display = '';
}

async function applyBulkInline(entityType) {
  const ids = [...(_bulkSelected[entityType] || [])];
  if (ids.length === 0) { showToast('Keine Auswahl.', true); return; }
  const cfg = BULK_EDIT_FIELDS[entityType];
  const prefix = entityType === 'company' ? 'companies'
               : entityType === 'product' ? 'products'
               : 'contacts';
  const fieldKey = document.getElementById(`${prefix}-bulk-field`).value;
  if (!fieldKey) { showToast('Bitte ein Feld wählen.', true); return; }
  const field = cfg.fields.find(f => f.key === fieldKey);
  const valEl = document.getElementById(`${prefix}-bulk-value`);
  if (!valEl) { showToast('Bitte einen Wert wählen.', true); return; }
  const onlyEmpty = document.getElementById(`${prefix}-bulk-only-empty`)?.checked;

  let value = valEl.value;
  if (value === '__NULL__') value = null;
  else if (field.type === 'boolean') value = value === 'true';
  else if (field.type === 'number') {
    const cleaned = String(value).replace(/[^\d,.\-]/g, '').replace(',', '.');
    const num = Number(cleaned);
    value = Number.isFinite(num) ? num : 0;
  }
  else if (field.type === 'text' || field.type === 'textarea') {
    value = (value || '').trim();
    if (value === '') value = null;
  }
  else if (value === '') {
    showToast('Bitte einen Wert wählen.', true); return;
  }

  const btn = document.getElementById(`${prefix}-bulk-apply-btn`);
  btn.disabled = true;
  let query = db.from(cfg.table).update({ [fieldKey]: value }).in('id', ids);
  if (onlyEmpty) query = query.is(fieldKey, null);
  const { error, data } = await query.select('id');
  btn.disabled = false;
  if (error) { showToast('Fehler: ' + error.message, true); return; }
  const n = data?.length ?? ids.length;
  showToast(`${esc(field.label)} bei ${n} ${esc(cfg.label)} geändert${onlyEmpty ? ' (nur leere)' : ''}.`);

  // Reset inline editor
  document.getElementById(`${prefix}-bulk-field`).value = '';
  onBulkFieldInlineChange(entityType);

  // Cache + Liste aktualisieren
  if (entityType === 'company') {
    const { data: cs } = await db.from('companies').select('*, typ:lookup_values!companies_typ_id_fkey(id, wert, farbe)').is('deleted_at', null).order('name');
    companiesCache = cs || [];
    filterCompanies();
    clearBulkSelection('company');
  } else if (entityType === 'contact') {
    const { data: ks } = await db.from('contacts').select('*, company:companies(id, name)').is('deleted_at', null).order('nachname').order('vorname');
    contactsCache = ks || [];
    filterContacts();
    clearBulkSelection('contact');
  } else if (entityType === 'product') {
    await loadProductsAndLieferanten();
    filterProducts();
    clearBulkSelection('product');
  }
}

async function openBulkEditModal(entityType) {
  const ids = [...(_bulkSelected[entityType] || [])];
  if (ids.length === 0) { showToast('Keine Auswahl.', true); return; }
  const cfg = BULK_EDIT_FIELDS[entityType];
  if (!cfg) { showToast('Bulk-Edit für diesen Typ nicht verfügbar.', true); return; }

  _bulkEditContext = { entityType, ids };
  document.getElementById('bulk-edit-summary').innerHTML =
    `${ids.length} ${esc(cfg.label)} ausgewählt — der gewählte Wert wird auf alle angewandt.`;

  // Feld-Dropdown füllen
  const fieldSel = document.getElementById('bulk-edit-field');
  fieldSel.innerHTML = '<option value="">— Feld wählen —</option>'
    + cfg.fields.map(f => `<option value="${esc(f.key)}">${esc(f.label)}</option>`).join('');

  // Reset
  document.getElementById('bulk-edit-value-wrap').style.display = 'none';
  document.getElementById('bulk-edit-only-empty').checked = false;
  document.getElementById('modal-bulk-edit').classList.add('open');
}

function closeBulkEditModal() {
  document.getElementById('modal-bulk-edit').classList.remove('open');
  _bulkEditContext = null;
}

